/* ÇEVİRİ it · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("it","olay",{
"OLAYLAR_EK5:1703-12-29:0":{"b": ["Morte di Mustafa II", "626c394d"], "d": ["Mustafa II, che con l'Episodio di Edirne lasciò il trono al fratello Ahmed III, morì a Edirne, che amava molto, circa cinque mesi dopo la deposizione. Alla sua malattia si era aggiunto anche il dolore per gli ultimi sviluppi. Alcune fonti occidentali scrivono che tra la gente era diffusa l'opinione che fosse stato avvelenato.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Inizio del governo kölemen (mamelucco) a Baghdad", "abe52618"], "d": ["Con la nomina a governatore di Baghdad di Hasan Pascià, di origine georgiana, iniziò in Iraq il periodo in cui, al posto dei governatori nominati dal centro, predominò un ceto dirigente formatosi tra i suoi stessi schiavi. Con il governatorato di Süleyman Pascià nel 1749 il sistema si consolidò e la Sublime Porta fu costretta a nominare non più chi voleva, ma uno dei kölemen che avevano preso in mano l'influenza. Se questa struttura semiautonoma fu utile alla difesa del confine iraniano, indebolì per un secolo e mezzo il controllo dell'autorità centrale sull'Iraq.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Fondazione della dinastia husainide in Tunisia", "cb1a98f9"], "d": ["Nel vuoto di autorità creatosi dopo l'invasione della Tunisia da parte delle forze algerine, Hüseyin b. Ali, sipahi ağası di origine turca, si impadronì del beylicato e ottenne legittimità dichiarando la propria fedeltà al sultano ottomano. La dinastia da lui fondata governò la Tunisia nel 1705-1735 e nel 1756-1957; all'amministrazione degli ocak subentrò un ordinamento beylicale trasmesso di padre in figlio. Nacque così il primo esempio, nei Garp ocakları, di strutture dinastiche legate al centro ma di fatto autonome.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Presa di Orano e Mers el-Kébir agli Spagnoli", "b67ce06a"], "d": ["Le forze del beylerbey dell'Ocak di Algeri, dopo un lungo assedio, presero Orano e il porto di Mers el-Kébir, da due secoli in mano alla guarnigione spagnola. Fu il maggior successo ottenuto contro la Spagna nel Mediterraneo occidentale dai Garp ocakları posti sotto protezione ottomana e mise in sicurezza il fianco occidentale di Algeri. La città avrebbe subito una nuova occupazione spagnola nel 1732, ma sarebbe stata ripresa definitivamente nel 1792.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Trattato del Prut — restituzione di Azak e Taganrog", "bac5d2a1"], "d": ["Il trattato in sette articoli, firmato con la resa dell'esercito russo accerchiato sul Prut, stabilì la restituzione agli Ottomani della fortezza di Azak con il suo territorio e le munizioni. Le fortificazioni di Taganrog, Kamenka e Yenikale sarebbero state demolite e le parti non avrebbero costruito nuove fortezze in queste zone. L'assetto di flotta e basi creato da Pietro I per sedici anni a Voronež e Azak crollò; l'accesso della Russia al Mar Nero fu ritardato di circa cinquant'anni.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Fondazione della dinastia caramanlide in Tripolitania", "e1105d4a"], "d": ["In Tripolitania, esausta per le contese tra gli ağa dell'ocak, l'ufficiale di cavalleria Ahmed Karamanlı prese il potere e regolarizzò la propria posizione con il berat di beylerbey ottenuto da Istanbul. Con Ahmed Pascià, il figlio Mehmed Pascià e il nipote Yûsuf Pascià nacque una dinastia durata dal 1711 al 1835; emerse una struttura semi-indipendente, che creò una propria flotta e firmò trattati direttamente con gli Stati europei. Questo periodo sarebbe finito solo nel 1835, con il collegamento diretto della provincia al centro.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Trattato di Edirne con la Russia", "14901a70"], "d": ["Poiché le promesse fatte sul Prut non erano state mantenute, la guerra era stata dichiarata altre due volte; infine, con l'accettazione degli impegni da parte dei Russi, fu firmata a Edirne una pace duratura. Il trattato confermò le condizioni del Prut; la Russia non si sarebbe immischiata negli affari polacchi, si sarebbe ritirata dalle terre cosacche e non avrebbe ostacolato il ritorno in patria del re di Svezia Carlo XII. La chiusura del fronte settentrionale permise all'Impero ottomano di rivolgere lo sguardo ai fronti della Morea e di Venezia. Aynı tarihte katılan öteki yerler: Hotin.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Dichiarazione di guerra a Venezia — preparativi della campagna di Morea", "d970b122"], "d": ["Con la motivazione che Venezia sosteneva i ribelli montenegrini, sequestrava navi mercantili ottomane e opprimeva con pesanti imposte la Morea ottenuta a Karlowitz, il Divan decise la guerra. La campagna preparata dal gran visir Silâhdar Damad Ali Pascià si sarebbe conclusa l'anno seguente con la riconquista dell'intera penisola di Morea in meno di cento giorni. Ma questo successo avrebbe messo in moto l'Austria e nel 1716 avrebbe aperto la porta a una guerra ben più grave.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["İstendil (Tinos): resa dell'ultima isola di Venezia nell'Egeo", "4abec891"], "d": ["La flotta partita per la campagna di Morea gettò l'ancora lungo la via davanti a İstendil, l'unica isola rimasta a Venezia nell'Egeo. L'isola, che pur essendo caduto il Ducato di Nasso nel 1566 grazie alla popolazione latina aveva portato per altri centocinquanta anni la bandiera veneziana, si arrese dopo un breve assedio senza spargimento di sangue. Così fu cancellata l'ultima impronta di Venezia nel Mar Egeo e il mare divenne interamente un mare interno ottomano.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["Conquista di Anabolu (Nauplia) — fortezza chiave della Morea", "62a5808a"], "d": ["Anabolu, capitale di Venezia in Morea e sua fortificazione più forte, cadde con la presa del bastione di Palamidi dopo nove giorni di bombardamento. La presa così rapida della fortezza spezzò la resistenza nel resto della penisola. La riconquista della Morea, perduta a Karlowitz, si completò di fatto qui. Aynı tarihte atlasta Venedik'ten Osmanlı'ya geçen diğer yerleşim: Argos — Anabolu'nun abi-merkez zincirini izler (TDV anabolu; beyanlı yaklaşıklık).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["Resa di Modone", "43faa909"], "d": ["Dopo la caduta di Anabolu la fortezza di Modone, all'estremità sudoccidentale della Morea, fu assediata dall'esercito da terra e dalla flotta dal mare e si arrese in breve tempo. Questo porto, usato per duecento anni da Venezia nelle sue campagne del Mediterraneo orientale, era il punto di approdo obbligato in cui le navi prendevano acqua e viveri. La sua perdita pose fine alla libertà di movimento della flotta veneziana nell'Egeo.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["Resa di Corone — completamento della campagna di Morea", "e4b9c8a4"], "d": ["Con la resa della fortezza di Corone, che tiene l'imboccatura del golfo di Messenia, l'amministrazione veneziana nella penisola di Morea ebbe interamente fine. La penisola, perduta a Karlowitz, fu interamente ripresa a soli tre mesi dall'apertura della campagna. Nella prosecuzione della stessa campagna, nel settembre 1715, fu tolta a Venezia anche l'isola di Ayamavra (Leucade) nel Mar Ionio. Questa rapidità costrinse Venezia a trascinare l'Austria in guerra e tre anni dopo si aprì la strada verso Passarowitz.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["Presa dell'isola di Çuha (Citera)", "494de6c6"], "d": ["L'isola di Çuha, all'estremità meridionale della Morea, fu ricevuta in resa dalla flotta dopo il completamento della penisola. L'isola, che sorveglia il passaggio tra Mar Ionio ed Egeo, era l'avamposto che Venezia usava per controllare queste acque. Ma non rimase l'unica isola ottomana tenuta: tre anni dopo fu restituita a Venezia a Passarowitz.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Alleanza tra Austria e Venezia — la porta della guerra ottomano-austriaca del 1716-1718", "99511ca2"], "d": ["Dopo la ripresa della Morea da Venezia da parte degli Ottomani, l'Austria, sostenendo che il Trattato di Karlowitz era stato violato, firmò un trattato d'alleanza con Venezia; il principe Eugenio, in una lettera al gran visir, chiese la restituzione dei luoghi tolti a Venezia. Nelle consultazioni all'accampamento di Davutpaşa, per l'insistenza del gran visir Ali Pascià, fu dichiarata guerra all'Austria e per questo si ottenne la fatwa dallo şeyhülislam.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["Il gran visir Ali Pascià parte per la campagna d'Austria", "2fbdce42"], "d": ["Dopo la dichiarazione di guerra all'Austria, il serdâr-ı ekrem Ali Pascià partì per la campagna d'Austria con un esercito di oltre 100.000 uomini; la flotta si diresse nella stessa estate verso Corfù. L'esercito avrebbe marciato da Belgrado su Varadino e nella disfatta dei primi di agosto il gran visir sarebbe caduto martire.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Disfatta di Varadino (Petrovaradin) — martirio di Damad Ali Pascià", "265c1d81"], "d": ["L'esercito ottomano, attraversato il Danubio da Belgrado, si scontrò davanti a Varadino con le forze austriache al comando del principe Eugenio; al primo slancio la carica dei giannizzeri forzò le trincee nemiche, ma con il crollo dell'ala di cavalleria le file si sbandarono. Il gran visir Silâhdar Damad Ali Pascià cadde martire, colpito alla fronte, e l'accampamento e il parco d'artiglieria passarono interamente in mano nemica. Questa disfatta, che le cronache ottomane ricordano come 'l'anno di Varadino', fu il primo anello della catena che portò alla perdita di Timișoara e, l'anno seguente, di Belgrado.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Fallimento dell'assedio di Corfù", "b2aa7011"], "d": ["Il seraschiere di Morea Kara Mustafa Pascià da terra e il kapudan pascià Canım Hoca Mehmed Pascià dal mare con la flotta si gettarono su Corfù; l'isola era la base chiave di Venezia nell'Adriatico. Ma la fortificazione estremamente robusta della fortezza, i rinforzi portati dalla flotta veneziana e le notizie della disfatta dal fronte del Danubio portarono alla revoca dell'assedio. Il mancato conseguimento di Corfù spense il clima di entusiasmo seguito alla riconquista della Morea e spostò il baricentro della guerra in Ungheria.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Perdita di Timișoara (Temeşvar) a favore dell'Austria", "27fe1365"], "d": ["Dopo la disfatta di Varadino il principe Eugenio marciò direttamente su Timișoara e la fortezza, al termine di un assedio di oltre quaranta giorni, si arrese con capitolazione. La città, conquistata nel 1552 al tempo di Solimano il Legislatore e considerata per 164 anni, come sede di beylerbeylik, il pilastro orientale della difesa dell'Ungheria, andò così perduta. Con la caduta di Timișoara l'intera regione del Banato passò all'Austria e il confine ottomano fu respinto a sud del Danubio. Aynı tarihte atlasta Osmanlı'dan Habsburg'a geçen diğer yerleşimler: Csákóvár, Facset ve Karánşebeş (Caransebeş) — Temeşvar eyaletinin devriyle birlikte (TDV timisvar; yer düzeyinde gün kaynakta yok, abi-merkez zinciri, beyanlı yaklaşıklık).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Resa della fortezza di Haram (Yeni Palanka) all'Austria — il Banato perde la riva del Danubio", "38ee4c6d"], "d": ["Dopo la caduta di Timișoara, il generale di cavalleria austriaco Mercy, incaricato di prendere il resto del Banato, il 14 novembre marciò su Haram (Yeni Palanka) sulla riva del Danubio; quando il 16 novembre giunse alla fortezza, la guarnigione ottomana di 200 uomini alzò bandiera bianca e si arrese a condizione di ritirarsi liberamente. Così anche la linea danubiana del Banato meridionale, in mano ottomana dal 1552, passò all'Austria. Aynı tarihte atlasta Osmanlı'dan Habsburg'a geçen diğer yerleşim: Versec — Haram'ın abi-merkez zincirini izler (Bánlaky 0019/1703; beyanlı yaklaşıklık).", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["Trattato di Passarowitz (Pasarofça) — la Morea guadagnata, Belgrado e il Banato perduti", "d46aa216"], "d": ["La Morea era stata ripresa a Venezia, ma l'Austria, entrata in guerra, con le vittorie ottenute a Petrovaradin e Belgrado ebbe il sopravvento al tavolo. Il trattato firmato con la mediazione di Inghilterra e Olanda lasciò la Morea agli Ottomani, ma in cambio, insieme a Belgrado, furono ceduti all'Austria la Serbia settentrionale, il Banato e la Piccola Valacchia; nelle parole del TDV 'la Bosnia settentrionale è stata lasciata interamente all'Austria' — fortezze come Bosanska Dubica e Bosanski Brod sulla Sava sulla mappa passano all'Austria da questo giorno (il confine preciso fu tracciato uno per uno dai commissari, il TDV non nomina queste fortezze); Venezia conservò invece le posizioni sulla costa ionica come Prevesa e Çuha. Con l'ahidnâme commerciale firmato lo stesso giorno il dazio riscosso sulle merci austriache fu ridotto dal cinque al tre per cento. Il trattato, sancendo il ripiegamento dell'Impero ottomano in Europa centrale, gettò con la pace ventisettenne che aprì le basi dell'Età dei Tulipani (1718-1730): sotto Nevşehirli Damad İbrahim Pascià la prima stamperia ottomana (1727, İbrahim Müteferrika), i comitati di traduzione, le osservazioni sull'inoculazione del vaiolo e una nuova vita di palazzo e di cultura sono frutto di questi anni di pace. Aynı gün atlasta el değiştiren diğer yerleşimler: Krayova (Craiova), Rimnik (Râmnicu Vâlcea) ve Turnu Severin (Küçük Eflak/Oltenya, Osmanlı'dan Avusturya'ya) ile Ayamavra (Lefkada) (Osmanlı'dan Venedik'e; TDV ayamavra: 1718'de Pasarofça Antlaşması ile ada Venedik'e terk edildi). Küçük Eflak'ta ayrıca Tırgu Jiu Avusturya'ya; Vonitsa (Voniçe, TDV pasarofca-antlasmasi) ve Çuha Adası (Kythira, TDV cuka-adasi: Pasarofça'nın 3. maddesi) Venedik'e geçer.", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Campagna orientale: presa di Tiflis e inizio della guerra con l'Iran", "78343dc2"], "d": ["Con il crollo dello Stato safavide per l'invasione afghana e la discesa della Russia sulle coste del Caspio, l'Impero ottomano inviò un esercito verso oriente perché il vuoto non cadesse interamente sotto l'influenza russa. Con la presa di Tiflis la Georgia fu legata all'amministrazione ottomana; poi l'avanzata proseguì in direzione di Ganja, Erevan e Nakhchivan. Questa campagna, condotta dietro l'apparenza pacifica dell'Età dei Tulipani, fu l'inizio di una lunga avventura orientale che sarebbe durata tredici anni e si sarebbe conclusa con la restituzione di tutto ciò che era stato conquistato.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["Campagna d'Iran del 1723: ingresso nello Shirvan e in Georgia", "c81189fc"], "d": ["Con il crollo dello Stato safavide per l'invasione afghana, fu aperta una campagna verso oriente con la motivazione di impedire la discesa della Russia sulle coste del Caspio. L'esercito di Erzurum, attraverso la Georgia, entrò a Tiflis e il ramo dello Shirvan a Shamakhi, riprendendo i territori perduti centotrenta anni prima. Questa campagna fu l'ultima grande avanzata ottomana nel Caucaso.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["Presa di Kermanshah — la porta degli Zagros", "ad14799f"], "d": ["L'esercito di Baghdad, superati i passi dei monti Zagros, prese Kermanshah, considerata la porta occidentale dell'Iran. La città si trovava sulla via delle carovane e dell'esercito da Baghdad a Isfahan e la sua presa assicurava la sicurezza orientale della provincia dell'Iraq. Questa avanzata diede inizio, nel dissolto paese safavide, alla corsa alla spartizione tra Ottomani e Russia.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Mukasemenâme di Istanbul — spartizione dell'Iran con la Russia", "fce8eec2"], "d": ["Per evitare lo scontro tra Ottomani e Russia sul territorio del crollato Stato safavide, con la mediazione dell'ambasciatore francese fu firmato un trattato di spartizione. Le coste occidentali e meridionali del Mar Caspio furono lasciate alla Russia; la Georgia, lo Shirvan, l'Azerbaigian e le città dell'Iran occidentale all'Impero ottomano. Questa spartizione, che sulla carta sembrava un grande guadagno, sarebbe divenuta di fatto nulla poco dopo con l'ascesa di Nadir Shah. Secondo il trattato, le fertili terre dello Shirvan come Şabran e Müşkür furono lasciate dalla parte russa (Çaycıoğlu, DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["Presa di Nakhchivan", "bdf14d0a"], "d": ["Le forze ottomane, avanzando lungo l'Aras, presero Nakhchivan e Ordubad; anche Julfa fu aggregata al livâ di Nakhchivan. La città fu legata, come porta nordoccidentale dell'Iran, al nuovo eyalet di Erevan. Il confine ottomano raggiunse così di nuovo la linea più orientale dell'epoca di Solimano il Legislatore.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["Conquista di Hamadan", "e1339a97"], "d": ["L'esercito, marciato da Kermanshah verso est, dopo un lungo assedio prese Hamadan, alla soglia occidentale dell'altopiano iranico. La città era l'ultima grande tappa sulla via di Isfahan, il punto più orientale che gli eserciti ottomani avessero potuto raggiungere dalla Campagna dei Due Iraq. La Convenzione di Istanbul, firmata lo stesso anno con la Russia, mise su carta la spartizione dell'Iran dissolto tra Ottomani e Russia.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["Nuova conquista di Erevan", "88acabef"], "d": ["Dopo un duro assedio di novanta giorni la fortezza chiave della valle dell'Aras, Erevan, entrò di nuovo sotto amministrazione ottomana. La fortezza, costruita nel 1583 e perduta nel 1604, fu questa volta fortificata con una guarnigione più forte. La lunghezza dell'assedio era un indicatore che l'esercito ottomano non avanzava più facilmente. Anche i nahiye di Karpi (Üçkilise), Şerür, Maku e Şüregel furono legati all'eyalet di Erevan.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["Presa di Tabriz — conquista dell'Azerbaigian", "e502a4f7"], "d": ["Tabriz, assediata di nuovo dopo il tentativo fallito dell'anno precedente, si arrese all'esercito ottomano dopo un aspro combattimento strada per strada. Anche Merend, Marāgheh e Sovukbulak (Mahabad), dipendenti dalla provincia di Tabriz, passarono sotto amministrazione ottomana. Nello stesso anno furono prese anche Lori, Ganja, Ardabil e Khorramabad, e le regioni spettanti agli Ottomani secondo il Mukasemenâme di Istanbul furono di fatto occupate. L'estensione raggiunta a oriente fu il confine più avanzato dopo il periodo del Trattato di Ferhad Pascià; tuttavia mantenerla gravò pesantemente sull'esercito e sul tesoro.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["Conquista di Ganja — fine della campagna del Caucaso", "875bca7a"], "d": ["Ganja, ultimo obiettivo dell'operazione nel Caucaso, fu ricevuta in resa come centro del Karabakh tra Kura e Aras. Con il completamento della linea Shirvan, Erevan, Nakhchivan e Ganja l'Impero ottomano raggiunse nel Caucaso l'estensione del 1590. Ma questo guadagno ebbe vita breve: l'ascesa di Nadir Shah entro dieci anni avrebbe ripreso tutta la regione.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Trattato di Hamadan — annessione dell'Iran occidentale all'Impero ottomano", "94a29dc3"], "d": ["Con il trattato firmato con il sovrano afghano Ashraf Shah ebbe fine la guerra di quattro anni e i territori dell'Iran occidentale occupati dall'Impero ottomano furono riconosciuti giuridicamente. In cambio Ashraf Shah riconobbe il califfato del sultano ottomano e si impegnò a far recitare in Iran la khutba a nome del sultano. Questa vittoria diplomatica ebbe breve durata; la controffensiva lanciata nel 1730 da Nadir Shah avrebbe cancellato in pochi anni i guadagni del trattato.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Hekimoğlu Ali Pascià prende Urmia (Rûmiye)", "eac7f64d"], "d": ["Nella campagna d'Iran Hekimoğlu Ali Pascià prese prima Urmia (Rûmiye), poi Tabriz, evacuata a favore degli Ottomani, il 15 novembre 1731. Il TDV non dà il giorno della presa di Urmia; si sa solo l'anno e che venne prima di Tabriz.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Trattato di Ahmed Pascià — restituzione della maggior parte dell'Iran occidentale", "590d839f"], "d": ["In seguito alla vittoria di Nadir Shah a Malayer e agli attacchi iraniani susseguitisi, il governatore di Baghdad Ahmed Pascià firmò un testo di pace senza consultare il centro. Secondo il trattato fu riconosciuto come confine il fiume Aras; le città dell'Iran occidentale come Hamadan, Kermanshah, Ardalan, Ardabil e Tabriz furono restituite all'Iran, mentre Ganja e Tiflis rimasero agli Ottomani. Accolto con reazioni negative a Istanbul, il testo fu ritenuto insufficiente anche da Nadir Shah e la guerra si riaccese prima che il 1732 terminasse. L'atlante considera passata in questo giorno dagli Ottomani ai Safavidi anche Kotur, che segue la catena di Hoy (TDV hoy; Kotur'a özgü gün kaynakta yok — beyanlı yaklaşıklık).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["Nuova perdita di Orano a favore della Spagna", "20485027"], "d": ["La grande flotta di sbarco inviata dal re di Spagna Filippo V, giunta davanti a Orano al comando del conte di Montemar, sconfisse le forze dell'Ocak di Algeri e riprese la città. Il porto, conquistato ventiquattro anni prima, sarebbe rimasto per sessant'anni in mano a una guarnigione spagnola. Questa perdita, che mostrò i limiti della potenza dei Garp ocakları nel Mediterraneo occidentale, poté essere compensata solo con la conquista definitiva di Orano nel 1792.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Riforma all'europea dell'Ocak degli humbaracı e fondazione dell'Humbarahâne", "d980cf2a"], "d": ["Humbaracı Ahmed Pascià, di origine francese, entrato al servizio ottomano, con il sostegno del gran visir Hekimoğlu Ali Pascià fece del corpo degli humbaracı un'unità salariata e ordinata all'europea. A trecento soldati reclutati in Bosnia fu impartita una formazione regolare basata su calcolo e geometria; furono preparati nuovi regolamenti per organizzazione, equipaggiamento e pensionamento e con tecnica moderna furono fabbricati cento mortai e cinquantamila bombe. L'Humbarahâne, dove si insegnava la geometria, è considerato il primo nucleo dell'istruzione di ingegneria militare moderna nell'Impero ottomano.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["Morte di Ahmed III", "455f7fba"], "d": ["Ahmed III, deposto nel 1730 con la rivolta di Patrona Halil, trascorse gli ultimi sei anni di vita nell'appartamento del Palazzo di Topkapı riservato ai sultani deposti e morì a sessantatré anni. Fu sepolto a Bahçekapı, nel mausoleo della nonna Turhan Sultan presso Yenicami.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Trattato di Istanbul — cessione del Caucaso meridionale all'Iran", "8c205aab"], "d": ["La seconda guerra con l'Iran, durata quattro anni, si concluse con il trattato firmato dopo la disfatta di Arpaçay e la perdita di Ganja e Tiflis. L'Impero ottomano si ritirò da tutti i territori del Caucaso meridionale e dell'Iran occidentale conquistati dal 1723; il confine tornò alla linea di Qasr-i Şîrin del 1639. Dalle campagne orientali durate tredici anni rimasero un pesante onere finanziario e un tesoro svuotato; in compenso, per la nuova guerra iniziata con la Russia la chiusura del fronte orientale fu un vantaggio vitale.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Caduta della fortezza di Özi (Očakiv) in mano russa", "f93e61f3"], "d": ["L'esercito russo al comando del maresciallo Münnich assediò la fortezza di Özi alla foce del Dnepr; con l'esplosione del deposito di munizioni la difesa crollò e la fortezza cadde con gravi perdite. La perdita di Özi, considerata la chiave della costa nordoccidentale del Mar Nero, aprì ai Russi la via per la Crimea e provocò grande panico a Istanbul. L'anno seguente la fortezza, evacuata dai Russi per epidemia e difficoltà di rifornimento, sarebbe tornata agli Ottomani.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Vittoria di Banja Luka — liberazione della Bosnia", "f603865a"], "d": ["Quando le forze austriache entrarono in Bosnia e assediarono Banja Luka, il governatore di Bosnia Hekimoğlu Ali Pascià accorse in aiuto con le forze raccolte tra la popolazione locale e inflisse una grave sconfitta al nemico superiore di numero. Questa vittoria fece crollare fin dalla prima mossa il piano austriaco di occupare la Bosnia e il nord della provincia fu interamente riconquistato. Banja Luka fu uno dei punti di svolta che risollevarono il morale dell'esercito ottomano, in continua ritirata di fronte all'Austria dopo il 1683.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["Vittoria di Hisarcık (Grocka) — apertura della strada per Belgrado", "2101cdff"], "d": ["L'esercito austriaco, che avanzava per proteggere Belgrado, fu attirato in un'imboscata in una stretta gola sulla riva del Danubio e subì gravi perdite in un combattimento durato tutto il giorno. Mentre le forze del maresciallo Wallis si ritiravano disordinatamente verso Belgrado, l'esercito ottomano giunse davanti alla fortezza e iniziò l'assedio. Hisarcık fu la vittoria in campo aperto più netta ottenuta contro l'Austria dopo Karlowitz e rese possibile direttamente la riconquista di Belgrado.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Trattato di Niš — pace con la Russia, neutralizzazione di Azak e cessazione delle incursioni in Crimea", "674f974e"], "d": ["La Russia, rimasta sola dopo che l'Austria aveva acconsentito alla pace a Belgrado, fu costretta a porre fine alla guerra con la mediazione dell'ambasciatore francese Villeneuve. Le fortificazioni della fortezza di Azak furono demolite e la regione fu dichiarata territorio neutrale tra i due Stati; la Russia accettò la condizione di non tenere navi da guerra e mercantili sul Mar Nero. L'obiettivo russo di aprirsi al mare fu così rinviato di una generazione e l'Impero ottomano si alzò dal tavolo da vincitore per l'ultima volta nel XVIII secolo.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Özi ritorna dopo l'occupazione russa: consegnata dopo la demolizione della fortezza con la pace del 1739", "7ecc2bef"], "d": ["I Russi avevano preso Özi l'11 luglio 1737. In forza della pace conclusa con la Russia nel 1739, le fortificazioni furono demolite e la fortezza fu consegnata di nuovo agli Ottomani; gli Ottomani la tennero fino al 1788, prima del Trattato di Iași.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["Difesa di Mosul — respinto Nadir Shah", "c03ffbc1"], "d": ["Nadir Shah, giunto davanti a Mosul dopo aver preso Kirkuk e Erbil, bombardò la città per quaranta giorni e lanciò attacchi generali successivi. La difesa condotta dal governatore Hüseyin Pascià al-Jalili, che armò anche la popolazione cittadina, costrinse l'esercito iraniano a togliere l'assedio con gravi perdite. La tenuta di Mosul evitò la perdita dell'intero Iraq e consolidò per un secolo l'influenza della famiglia al-Jalili nella città.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["Alleanza di Dir'iyya — fondazione del primo Emirato saudita nel Najd", "188751bf"], "d": ["L'emiro Muhammad b. Saud, che a Dir'iyya prese sotto la propria protezione lo studioso Muhammad b. Abd al-Wahhab, cacciato da Uyayna, stipulò con lui un'alleanza che metteva l'autorità politica al servizio della predicazione religiosa. Questo accordo inaugurò una nuova storia per la famiglia Saud e riunì intorno a un solo movimento gli emirati di oasi sparsi del Najd. Questa forza, che nel giro di mezzo secolo si sarebbe estesa fino a Kerbela, alla Mecca e a Medina, avrebbe costretto l'Impero ottomano a difendere il proprio dominio nell'Hijaz.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Trattato di Kerden — fine delle guerre ottomano-iraniane", "1d3a919e"], "d": ["Con il trattato firmato dopo l'ultima guerra, durata quattro anni, il confine di Qasr-i Şîrin del 1639 fu rinnovato tale e quale; nessuna delle due parti ottenne guadagni territoriali. La richiesta insistente di Nadir Shah che il giafarismo fosse riconosciuto come quinta scuola giuridica rimase senza risposta; in cambio si decise che i pellegrini iraniani potessero compiere liberamente il hajj e che vi fosse scambio reciproco di ambasciatori. Le guerre ottomano-iraniane, durate oltre due secoli, si chiusero così di fatto; questo confine è rimasto in larga parte invariato fino a oggi.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["Morte di Mahmud I e ascesa al trono di Osman III", "30203700"], "d": ["Mahmud I, che nel suo regno di ventiquattro anni aveva recuperato i territori perduti con il Trattato di Belgrado e aveva sostenuto la riforma dell'Ocak degli humbaracı, morì al ritorno dal selâmlık del venerdì. Gli successe il fratello Osman III, che aveva vissuto la vita del kafes fino a cinquantotto anni. Iniziò un regno breve e inquieto; sotto Osman III, che in tre anni cambiò sei gran visir, negli affari di Stato dominò una marcata stagnazione.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["Morte di Osman III e ascesa al trono di Mustafa III", "3ac10f85"], "d": ["Dopo il regno di tre anni, con la morte di Osman III salì al trono Mustafa III, aperto alle idee di riforma e attento da vicino agli affari di Stato. Il nuovo sultano, fondandosi sull'esperienza del gran visir Koca Râgıb Pascià, cercò di risanare le finanze e di rinnovare l'esercito; in questo periodo furono creati i sürat topçuları (artiglieri a tiro rapido) del barone de Tott. Ma la guerra con la Russia, intrapresa nel 1768, avrebbe oscurato tutti i risultati del regno di diciassette anni.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Dichiarazione di guerra alla Russia — l'episodio di Balta e inizio della guerra del 1768-1774", "9c6aabe0"], "d": ["Quando i reparti russi e cosacchi, inseguendo la Confederazione di Bar in Polonia, assalirono e incendiarono la cittadina di Balta al confine ottomano, il Divan decise la guerra e l'ambasciatore russo fu imprigionato a Yedikule. La guerra, intrapresa senza seri preparativi militari e dichiarata con sei mesi di anticipo, andò male fin dall'inizio. Questo conflitto, destinato a durare sei anni, si sarebbe trasformato, con l'incursione di Çeşme, la disfatta di Kartal e l'occupazione della Crimea, in una delle più gravi serie di sconfitte della storia ottomana.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["Perdita della fortezza di Chotyn (Hotin) a favore dei Russi", "66d43ea4"], "d": ["Respinti due tentativi dell'esercito russo al comando del principe Golicyn, dopo la disfatta subita dal gran visir tra Kamianets e Hotin l'esercito si ritirò e la guarnigione evacuò la fortezza. La perdita senza resistenza della più forte fortificazione ottomana a nord del Danubio aprì ai Russi le porte di Valacchia e Moldavia. I due principati furono occupati nello stesso anno; Hotin poté essere recuperata soltanto nel 1774 con il Trattato di Küçük Kaynarca.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["Disfatta della piana di Kartal (Kagul)", "6f408eaf"], "d": ["Tre settimane dopo l'incendio della flotta a Çeşme, il principale esercito ottomano sul Danubio si disperse nella piana di Kartal di fronte alle truppe, numericamente molto più piccole ma disciplinate, del maresciallo Rumjancev. Accampamento, salmerie e centinaia di cannoni caddero in mano nemica; le truppe in fuga subirono gravi perdite nell'attraversare il Danubio. La distruzione, nella stessa estate, sia della flotta sia dell'esercito di terra portò alla caduta una dopo l'altra di Kilia, Akkerman, Ismail e Bender e all'occupazione della Crimea.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["Occupazione russa della penisola di Crimea", "217837b0"], "d": ["Le armate russe, che un anno prima avevano preso il Bucak, al comando del principe Dolgorukov superarono Or Kapı e invasero l'intera penisola di Crimea. Il khan fu deposto e, con l'insediamento del filorusso Sahib Giray, fu compiuto il primo passo verso il distacco del khanato dagli Ottomani. La perdita della Crimea, da tre secoli scudo settentrionale dell'Impero ottomano, fu l'inizio del processo che portò all'indipendenza nel 1774 e all'annessione diretta nel 1783.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["Morte di Mustafa III e ascesa al trono di Abdülhamid I", "42cba8e2"], "d": ["Al posto di Mustafa III, morto nel momento più critico della guerra con la Russia, salì al trono a quarantanove anni il fratello Abdülhamid I, che aveva trascorso quarantatré anni nel kafes del palazzo. Il nuovo sultano, ereditando uno dei periodi più difficili dello Stato, dovette affrontare le dure condizioni del Trattato di Küçük Kaynarca che sarebbe stato firmato nello stesso anno. Il suo regno di quindici anni sarebbe trascorso tra la perdita della Crimea e una nuova guerra con la Russia, e si sarebbe concluso nel 1789 con la paralisi che lo colpì mentre leggeva la notizia della caduta di Özi.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Disfatta di Kozluca — la sconfitta che portò a Küçük Kaynarca", "8e0542f9"], "d": ["Le forze ottomane riunite davanti a Şumnu furono sconfitte a Kozluca dalle colonne congiunte di Suvorov e Kamenskij e gran parte dell'esercito si disperse. Con questa disfatta nei Balcani non rimase alcuna forza in grado di resistere; le avanguardie russe assediarono Şumnu e il quartier generale del gran visir fu minacciato. Il fatto che in meno di un mese ci si sia seduti al tavolo a Küçük Kaynarca e siano state accettate condizioni straordinariamente pesanti è conseguenza diretta di questa sconfitta.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["Cessione della Bucovina (Moldavia settentrionale) all'Austria", "190f9caa"], "d": ["L'Austria, approfittando della debolezza causata da Küçük Kaynarca, chiese la regione della Bucovina, che assicurava il collegamento tra Moldavia e Transilvania, e ottenne questo territorio senza entrare in guerra, con minacce e corruzione. La perdita di questa regione fertile e strategica a sud-ovest di Hotin divise di fatto in due il voivodato di Moldavia. Questa cessione, avvenuta senza sparare un colpo, fu considerata uno degli indicatori più chiari che l'Impero ottomano aveva ormai perso la capacità di deterrenza. Con la cessione della Bucovina nel 1775 Suceava e Černivci passarono all'Austria (gün teyitsiz).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["Occupazione iraniana di Bassora", "0161e709"], "d": ["Sadiq Khan, fratello del sovrano zand Karim Khan, dopo un assedio durato un anno prese Bassora, e l'Impero ottomano perse il suo porto più importante nel Golfo Persico. L'occupazione colpì direttamente la via commerciale dell'India, le entrate dei datteri e delle perle e la difesa meridionale dell'Iraq. La città poté essere ripresa solo nel 1779, durante le lotte per il trono scoppiate in Iran con la morte di Karim Khan.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["Tenkihnâme di Aynalıkavak — intesa provvisoria sulla Crimea", "9b3b0468"], "d": ["I due Stati, giunti sull'orlo della guerra per la questione di chi dovesse salire al vertice del khanato di Crimea, con la mediazione della Francia firmarono un testo esplicativo nel Palazzo di Aynalıkavak. La Russia accettò di ritirare le truppe dalla Crimea e l'Impero ottomano di riconoscere il khanato del filorusso Şahin Giray; fu confermato il diritto di califfato religioso del sultano sulla Crimea. Questo fragile equilibrio, destinato a durare quattro anni, sarebbe crollato del tutto nel 1783 con l'annessione diretta della penisola da parte della Russia.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["Costruzione della fortezza di Anapa — linea di difesa caucasica", "be92a80f"], "d": ["Quando con Küçük Kaynarca la Crimea andò perduta, per mantenere l'influenza ottomana nel Caucaso si intraprese la costruzione di una nuova fortezza alla foce del fiume Kuban. Anapa, fondata sui resti di una colonia genovese, con il suo bazar, i suoi bagni e più di duecentocinquanta botteghe divenne presto una città che assicurava il collegamento con le tribù circasse. La fortezza rimase per quarantotto anni l'avamposto più avanzato degli Ottomani contro la discesa della Russia nel Caucaso.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["Destituzione ed esecuzione del gran visir Halil Hamîd Pascià", "c44001ca"], "d": ["Il gran visir riformatore Halil Hamîd Pascià, di cui Abdülhamid I aveva mostrato in varie occasioni la soddisfazione per i servigi, verso la mattina del 31 marzo 1785 fu improvvisamente destituito ed esiliato a Gallipoli e tutti i suoi beni furono confiscati. Gli furono dapprima dati l'eyalet d'Abissinia, il sanjak di Gedda e lo şeyhülharemlik della Mecca; mentre trascorreva l'aprile 1785 a Bozcaada preparando il viaggio, fu destituito anche da questa carica e con il firmano di esecuzione emesso fu ucciso da Karakethüdâzâde Ali, uno degli uomini di Cezayirli Gazi Hasan Pascià. La sua testa mozzata fu inviata a Istanbul ed esposta a Ortakapı. Secondo il TDV questa caduta improvvisa è stata interpretata con l'accusa di un complotto per deporre il sultano e metterne al posto lo şehzade Selim, ma le vere cause furono verosimilmente l'indignazione per il suo silenzio sull'annessione della Crimea, l'ostilità degli ambienti colpiti dalle sue riforme e l'opposizione di Gazi Hasan Pascià.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Dichiarazione di guerra alla Russia — inizio della guerra ottomano-russa del 1787-1792", "3bfb870c"], "d": ["Dopo il fastoso viaggio in Crimea di Caterina II e la sua presa del Caucaso georgiano sotto protezione, il Divan decise la guerra con l'obiettivo di annullare l'annessione e l'ambasciatore russo fu di nuovo rinchiuso a Yedikule. Ma l'esercito non era pronto, il tesoro era vuoto e la ricerca di alleati era stata vana. La guerra, destinata a durare cinque anni, si sarebbe conclusa con la caduta di Özi con massacro, la perdita di Ismail e le dure condizioni del Trattato di Iași.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["Entrata in guerra dell'Austria — lotta su due fronti", "ae912290"], "d": ["In forza dell'alleanza segreta stipulata con la Russia nel 1781, l'imperatore austriaco Giuseppe II dichiarò guerra all'Impero ottomano e mosse in direzione di Belgrado e della Bosnia. L'esercito ottomano si trovò all'improvviso a dover combattere su due fronti, la Russia a nord e l'Austria a ovest. Nonostante le vittorie sugli Austriaci a Lazarethane, Mehadia e Șebeș, con la perdita di Belgrado nel 1789 anche il fronte occidentale sarebbe crollato.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Alleanza ottomano-prussiana", "03b88e51"], "d": ["Selim III, che cercava alleati in Europa appena salito al trono, firmò con la Prussia un trattato d'alleanza che prevedeva mutuo soccorso; la Prussia si impegnava a dichiarare guerra a Russia e Austria, e l'Impero ottomano a non fare la pace finché la Crimea non fosse stata recuperata. Fu il primo vero testo di alleanza reciproca firmato nella storia ottomana con uno Stato europeo e mostrava l'abbandono della concezione classica secondo cui 'non c'è alleanza con gli infedeli'. La Prussia non entrò in guerra, ma costringendo l'Austria alla pace spianò la strada al Trattato di Sistova.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["Caduta e massacro della fortezza di Ismail", "6a296b0c"], "d": ["La fortezza di Ismail, considerata la più forte fortificazione del delta del Danubio, fu presa in un giorno con un sanguinoso assalto generale organizzato dal generale Suvorov; la guarnigione e la popolazione della città furono in gran parte passate a fil di spada. Questo massacro, che ebbe vasta eco in Europa, provocò un profondo shock nell'opinione pubblica ottomana e spezzò la spina dorsale della linea di difesa danubiana. La fortezza sarebbe stata restituita un anno dopo con il Trattato di Iași, ma il destino della guerra era ormai segnato.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Trattato di Sistova — chiusura del fronte austriaco", "58741f1d"], "d": ["Grazie alla pressione della Prussia e al fatto che la Rivoluzione francese impegnava l'Austria a ovest, i due Stati giunsero alla pace sulla base dei confini prebellici. L'Austria restituì tutti i luoghi occupati, compresa Belgrado; l'Impero ottomano accettò soltanto piccole rettifiche al confine croato. La chiusura del fronte occidentale a queste condizioni permise all'Impero ottomano di concentrare tutte le forze contro la Russia e limitò la perdita a Iași. Con queste rettifiche al confine croato Cetin (Cetingrad) e Drežnik Grad passano dagli Ottomani agli Asburgo (TDV zistovi-antlasmasi; Korić 2016, n. 118, art. 4). Orsova (Eski Orsova) è invece l'unico luogo non restituito (Bánlaky 0019/1796); l'atlante scrive in questo giorno il trasferimento giuridico (occupazione di fatto il 16 aprile 1790).", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Trattato di Iași — perdita definitiva della Crimea e confine sul Dnestr", "a56fd194"], "d": ["Con il trattato firmato al termine della guerra di cinque anni il fiume Turla (Dnestr) fu riconosciuto come confine; la riva sinistra del fiume rimase alla Russia, la destra agli Ottomani, e Özi con i dintorni andò perduta definitivamente. L'Impero ottomano abbandonò del tutto la speranza di riprendere la Crimea e riconobbe giuridicamente l'annessione del 1783; Valacchia e Moldavia furono restituite con due anni di esenzione fiscale. Accettato anche l'obbligo di un'indennità di guerra di dodici milioni di kuruş, il nord del Mar Nero fu lasciato in modo permanente alla Russia. Aynı tarihte katılan öteki yerler: İsmail.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["Evacuazione di Orano (Vehrân) da parte degli Spagnoli e cessione ad Algeri", "9f95cee6"], "d": ["Quando nel terremoto del 1790 fortezza e città furono in gran parte distrutte, la Spagna, che non poteva più sostenere la costosa guarnigione mantenuta da tre secoli, accordandosi con l'ocak di Algeri cedette Orano e Mers el-Kébir senza guerra. Fu così liquidata anche l'ultima posizione europea sulla costa nordafricana. L'Algeria ottomana, per i trentotto anni che passarono fino all'occupazione francese, dominò l'intera costa.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["Governo di fatto di Osman Pazvandoğlu a Vidin", "0ce70361"], "d": ["Osman Pazvandoğlu, sollevatosi contro le disposizioni del Nizâm-ı Cedîd, fece fuggire il governatore di Vidin, si impadronì della città e la fortificò con profondi fossati lungo il Danubio. Nel 1797, all'apice della potenza, radunò una forza di quasi ottantamila uomini e prese il controllo di Nicopoli, Sistova, Ruse, Sofia e Niš; si presentava non come ribelle ma come riformatore. L'assedio della Sublime Porta del 1798-1799, durato mesi, non ebbe esito e Osman governò in modo semi-indipendente la Bulgaria settentrionale fino alla morte nel 1807.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["Apertura della Mühendishâne-i Berrî-i Hümâyun", "e9a3a34b"], "d": ["Per formare ufficiali di artiglieria, genio e cartografi per l'esercito del Nizâm-ı Cedîd fu aperta a Hasköy la scuola di ingegneria terrestre, corrispettivo nell'esercito di terra della Scuola di ingegneria navale fondata nel 1773. Nel programma si insegnarono algebra, geometria, meccanica, fortificazione e balistica, e furono tradotti dalle lingue europee libri di matematica e artiglieria. Questa scuola, considerata la radice dell'istruzione ingegneristica moderna in Turchia, è ritenuta l'inizio dell'odierna Università Tecnica di Istanbul.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Dichiarazione di guerra alla Francia e alleanza con Russia e Inghilterra", "80e95bd7"], "d": ["In seguito all'occupazione dell'Egitto da parte di Napoleone, l'Impero ottomano ruppe la tradizionale amicizia francese di due secoli e mezzo e dichiarò guerra alla Francia. Nello stesso processo, per la prima volta nella sua storia, si alleò con la Russia e permise alla flotta russa di passare dagli Stretti verso il Mediterraneo; poi fu firmata un'alleanza anche con l'Inghilterra. Grazie a queste alleanze le isole Ionie furono tolte ai Francesi, ma l'apertura degli Stretti a una flotta straniera creò un precedente dal prezzo gravoso per il futuro.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["Presa di Prevesa ai Francesi — Battaglia di Nicopoli", "d8e5e892"], "d": ["Quando nel 1797 la Repubblica di Venezia fu abbattuta, le isole Ionie e sulla terraferma Prevesa, Parga e Vonitsa passarono alla Francia. Il governatore di Ioannina Alì Pascià di Tepedelen, approfittando della guerra aperta dall'occupazione francese dell'Egitto, marciò su Prevesa e nelle rovine di Nicopoli fuori città inflisse una grave sconfitta alla guarnigione francese. Così questo porto, lasciato a Venezia a Passarowitz, ottanta anni dopo entrò sotto amministrazione ottomana. Butrinto cadde il 25 ottobre con la guarnigione francese che fece saltare le fortificazioni e si ritirò a Corfù (Curlin, Preveza B, 2010; atlas günü Preveze'den alır) e passò sotto amministrazione ottomana.", "f32e8843"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["Difesa di Acri — respinto Napoleone", "56b5c45b"], "d": ["Napoleone, avanzato dall'Egitto verso la Siria, assediò Acri e per due mesi lanciò assalti successivi; la città fu difesa da Cezzâr Ahmed Pascià con il sostegno della flotta inglese e delle truppe del Nizâm-ı Cedîd inviate da Istanbul. Costretto a togliere l'assedio e a ritirarsi in Egitto, Napoleone seppellì davanti a queste mura il sogno di spingersi verso oriente. La notizia fu accolta a Istanbul con grande gioia e considerata la prova che l'esercito addestrato appena creato aveva superato la sua prima seria prova.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["Incursione wahhabita a Kerbela", "522341ed"], "d": ["Le forze wahhabite partite dal Najd entrarono a Kerbela, saccheggiarono la città, distrussero il mausoleo dell'imam Husayn e uccisero più di tremila persone. I governatori kölemen dell'Impero ottomano in Iraq non poterono impedire l'attacco; il fatto suscitò grandi reazioni sia in Iran sia a Istanbul. Questo attacco fu la proclamazione che il movimento saudita non era più un emirato di oasi, ma si era trasformato in una potenza regionale che minacciava le città sante ottomane.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["Annessione alla Russia del Kartli-Kakheti (Georgia orientale)", "3b650c5e"], "d": ["Il regno di Kartli-Kakheti, che nel 1783 aveva accettato la protezione russa e nel 1795 aveva subìto la devastante campagna iraniana, fu sciolto; con l'ordine del 12 settembre 1801 fu proclamato provincia della Russia e si iniziò a stabilirvi il sistema amministrativo russo. La Georgia da questa data perse l'indipendenza; nel giro di pochi anni anche la Mingrelia (1803), l'Imerezia e la Guria (1804) entrarono sotto il dominio russo e la Russia giunse al confine caucasico ottomano. Con questo fatto Gori, Dusheti (Kartli) e Telavi (Kakheti) passarono alla Russia.", "f5e0d5d5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["Evacuazione dell'Egitto dai Francesi", "00cfdc8c"], "d": ["In seguito all'operazione congiunta delle forze ottomane e inglesi da terra e da mare furono prese prima il Cairo, poi Alessandria, e le forze francesi furono rimandate in patria per nave. Con la fine dell'occupazione triennale l'Egitto tornò sulla carta all'amministrazione ottomana, ma la lotta per il predominio tra i bey kölemen e i reparti albanesi precipitò il paese nel caos. Questo vuoto avrebbe preparato, nel giro di pochi anni, il terreno per l'ascesa di Mehmed Ali di Kavala.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Trattato di Parigi — ristabilimento della pace con la Francia", "1b76991f"], "d": ["Con il trattato firmato dopo l'evacuazione dell'Egitto lo stato di guerra tra l'Impero ottomano e la Francia terminò ufficialmente e le antiche capitolazioni furono rinnovate. Alle navi mercantili francesi fu consentito l'ingresso nel Mar Nero; in cambio la Francia riconobbe l'integrità territoriale ottomana. Il ristabilimento della pace restituì uno spazio di manovra alla politica estera di Selim III, stretta tra Russia e Inghilterra.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["Presa di Ta'if da parte dei wahhabiti", "7b791359"], "d": ["Le forze wahhabite al comando di Saud b. Abd al-Aziz, nella prima mossa verso l'Hijaz, assediarono e saccheggiarono Ta'if; la città cadde come prima porta verso le terre sante. Per il sultano ottomano, che portava il titolo di protettore dei Haramayn, fu un colpo che scuoteva direttamente la legittimità del sultanato. Due mesi e mezzo dopo lo stesso esercito avrebbe marciato sulla Mecca.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["Prima presa della Mecca da parte dei wahhabiti", "21157c05"], "d": ["Due mesi e mezzo dopo la caduta di Ta'if le forze wahhabite entrarono alla Mecca, abbatterono i mausolei e stabilirono un ordine secondo la propria concezione; lo sharif Ghalib dovette ritirarsi a Gedda. La chiusura delle vie del pellegrinaggio ebbe eco in tutto il mondo islamico e costrinse Istanbul a chiedere aiuto militare al governatore d'Egitto Mehmed Ali. Questo primo dominio sarebbe durato soltanto tre mesi.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Ripresa della Mecca da parte dello sharif Ghalib", "83d08dff"], "d": ["Lo sharif Ghalib, ritiratosi a Gedda, con le forze raccolte assediò la Mecca e, dopo un assedio di venticinque giorni, la riprese ai wahhabiti; la khutba fu di nuovo recitata a nome ottomano. Anche questo secondo dominio non sarebbe stato duraturo: le forze saudite avrebbero ripreso la città nel 1806.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["Inizio della Prima rivolta serba", "0f6e8767"], "d": ["Quando i dahi giannizzeri ribelli, impadronitisi del governo a Belgrado, massacrarono in massa i notabili serbi, iniziò una resistenza armata guidata da Karađorđe. Condotto inizialmente restando fedeli al sultano e solo contro i dahi, il movimento si trasformò presto in una rivolta nazionale che chiedeva autonomia e indipendenza. Le forze serbe presero Belgrado nel 1806; questa sollevazione fu il primo anello dei movimenti nazionalisti di indipendenza nei Balcani.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["Occupazione di Medina da parte dei wahhabiti", "84e310d7"], "d": ["Dopo la Mecca anche Medina cadde in mano alle forze wahhabite; il tesoro della Rawda al-Mutahhara fu disperso e i mausolei con cupola della città furono distrutti. Così le due città sante uscirono insieme dal controllo ottomano e le carovane di pellegrini da Damasco e dall'Egitto non poterono mettersi in cammino per anni. Medina poté essere ripresa solo sette anni dopo, nel 1812, dall'esercito egiziano al comando di Tosun Pascià, figlio di Mehmed Ali Pascià.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["Inizio della guerra con la Russia (guerra ottomano-russa del 1806-1812) e chiusura degli Stretti", "ea170804"], "d": ["Quando Selim III, avvicinatosi alla Francia dopo la vittoria di Napoleone ad Austerlitz, destituì i voivodi di Valacchia e Moldavia nonostante la pressione russa, gli eserciti russi occuparono i due principati e iniziò la guerra. L'Impero ottomano chiuse gli Stretti alla flotta russa; in risposta anche l'Inghilterra si schierò con la Russia e inviò una flotta a Istanbul. Questa guerra, destinata a durare sei anni, intrecciatasi con la rivolta di Kabakçı e la deposizione di Selim III, si sarebbe conclusa con la perdita della Bessarabia nel Trattato di Bucarest del 1812.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["Arrivo della flotta inglese davanti a Istanbul (operazione Duckworth)", "195bb58f"], "d": ["L'Inghilterra, che voleva costringere l'Impero ottomano a rompere con la Francia, fece passare dai Dardanelli la flotta al comando dell'ammiraglio Duckworth e la ancorò davanti a Istanbul. Con la spinta anche dell'ambasciatore francese Sébastiani la popolazione di Istanbul si mobilitò, le batterie costiere furono rinforzate in pochi giorni e la flotta dovette ritirarsi senza poter bombardare la città; al ritorno subì gravi perdite ai Dardanelli. La minaccia così ravvicinata alla capitale da parte di una flotta straniera, per la prima volta, collocò la questione degli Stretti al centro della diplomazia europea.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["Strangolamento di Mustafa IV", "eeb75c20"], "d": ["Quando Alemdar Mustafa Pascià fu sorpreso da un attacco e morì e i ribelli volevano marciare sul palazzo, Mustafa IV, deposto, fu strangolato per ordine del fratello Mahmud II. Il funerale fu sepolto a Bahçekapı nel mausoleo del padre Abdülhamid I; tra i ribelli si diffuse la voce che la bara fosse vuota.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Trattato di Kal'a-i Sultâniyye — pace con l'Inghilterra e regola degli Stretti", "fe282117"], "d": ["Con il trattato firmato con l'Inghilterra dopo il fallimento dell'operazione Duckworth la guerra tra i due Stati terminò e furono restituiti gli antichi privilegi dei mercanti inglesi. La disposizione contenuta nel testo, detta 'antica regola', stabilì che in tempo di pace nessuna nave da guerra straniera potesse passare dagli Stretti. Questo principio divenne il fondamento giuridico di tutte le disposizioni internazionali che avrebbero plasmato il regime degli Stretti nel corso dell'Ottocento.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["Disfatta di Slobozia — accerchiamento dell'esercito del Danubio", "54b60fd1"], "d": ["Gran parte dell'esercito ottomano che aveva attraversato il Danubio davanti a Ruse fu stretta a Slobozia dalla manovra di accerchiamento di Kutuzov dalla riva opposta del fiume e lasciata alla fame. Migliaia di soldati dovettero arrendersi; la forza in mano al gran visir si sciolse di fatto e la Sublime Porta un mese dopo fu costretta a chiedere l'armistizio. Questa sconfitta è la causa diretta dell'accettazione della cessione della Bessarabia nel Trattato di Bucarest del 1812.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["Ripresa di Belgrado e repressione della Prima rivolta serba", "06f56f52"], "d": ["I ribelli serbi, privati dell'appoggio russo dal Trattato di Bucarest, non poterono resistere all'operazione congiunta delle forze giunte da Bosnia e Rumelia; Hurşid Ahmed Pascià entrò a Belgrado e la sollevazione di nove anni fu repressa del tutto. Karađorđe fuggì in Austria e il sanjak di Smederevo fu di nuovo legato direttamente all'amministrazione ottomana. Tuttavia le dure misure applicate avrebbero provocato due anni dopo una seconda rivolta, duratura, guidata da Miloš Obrenović.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["Seconda rivolta serba e principato di Miloš Obrenović (başknez)", "e6e82ad2"], "d": ["Contro le pesanti misure applicate dopo la repressione della prima rivolta scoppiò una nuova sollevazione guidata da Miloš Obrenović; stavolta la Sublime Porta preferì la conciliazione alla forza. Con l'accordo stipulato Miloš fu riconosciuto con il titolo di 'başknez' e il potere di riscuotere le imposte e di condurre gli affari interni fu lasciato ai knez serbi. Questo primo nucleo di autonomia di fatto fu il punto di partenza del processo che condusse al firmano del 1830 e all'indipendenza del 1878.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["Rivolta di Valacchia — Ypsilanti attraversa il Prut e sollevazione di Vladimirescu", "67d46a98"], "d": ["Aleksandros Ypsilantis, generale nell'esercito russo, a nome della Filikí Etería attraversò il Prut e tentò di avviare una sollevazione greca generale in Valacchia e Moldavia; negli stessi giorni anche Tudor Vladimirescu mise in movimento i contadini locali. I due movimenti non poterono unirsi: Vladimirescu rispose all'invito di Ypsilantis a combattere insieme contro i Turchi con 'Io non mi sono sollevato contro i Turchi, ma contro i Greci' e poco dopo fu ucciso dagli uomini di Ypsilantis. La rivolta fu repressa dalle forze ottomane a maggio, ma l'ordinamento dei voivodati fanarioti ebbe fine e il fuoco della rivolta si propagò alla Morea.", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["Fondazione del Secondo Stato saudita a Riyad", "34dad3bd"], "d": ["Sei anni dopo la caduta di Dir'iyya nel 1818 e la distruzione del primo Stato saudita, Turki b. Abdallah scacciò le guarnigioni egiziane dal Najd e fondò un nuovo emirato saudita con centro a Riyad. La nuova struttura evitò di estendersi all'Hijaz, preferì restare nel Najd e si tenne lontana da scontri diretti con le forze ottomano-egiziane. Questo secondo Stato sarebbe durato fino alla fine del secolo e avrebbe costituito il secondo anello della catena che porta alla fondazione dell'odierna Arabia Saudita. Aynı tarihte elden çıkan diğer yerleşimler: Dir'iye (Necid).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["Convenzione di Akkerman — concessioni alla Serbia e ai principati", "c75f15d0"], "d": ["Subito dopo l'abolizione del Corpo dei giannizzeri, l'Impero ottomano, rimasto senza esercito, fu costretto ad accettare di fronte all'ultimatum della Russia un trattato a condizioni pesanti. Fu confermata l'autonomia promessa alla Serbia, si accettò che i voivodi di Valacchia e Moldavia non potessero essere destituiti senza il consenso russo e fu concessa alle navi mercantili russe piena libertà negli Stretti. Quando la Sublime Porta due anni dopo dichiarò di non riconoscere la convenzione a causa della questione greca, la Russia l'avrebbe considerata un motivo di guerra.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["Liquidazione del sistema del timar", "84d5d1d6"], "d": ["Un anno dopo l'abolizione del Corpo dei giannizzeri, circa 5.200 sipahi titolari di timar nei cinquantatré sanjak di Rumelia e Anatolia furono trasformati, con le rendite dei timar, in cavalleria degli Asâkir-i Mansûre. Così il regime del timar, spina dorsale quadricentenaria dell'ordinamento ottomano di terra, imposte ed esercito, ebbe fine di fatto. I timar rimasti vacanti furono trasferiti al tesoro e si aprì la strada al passaggio a un esercito centrale salariato e a un sistema fiscale in denaro.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["Fondazione della Tıphâne-i Âmire — inizio dell'istruzione medica moderna", "ac3e57c0"], "d": ["Per formare medici e chirurghi per il nuovo esercito degli Asâkir-i Mansûre, su proposta del capo dei medici Mustafa Behçet Efendi fu aperta a Şehzadebaşı la Tıphâne-i Âmire. Le lezioni furono organizzate secondo il programma europeo e l'insegnamento fu inizialmente in francese; pochi anni dopo fu fondata anche la Cerrahhâne-i Âmire e le due istituzioni furono unite. Questa scuola, considerata l'inizio dell'insegnamento medico moderno in Turchia, è ritenuta l'origine dell'odierna Facoltà di Medicina di Istanbul.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["Inizio della guerra ottomano-russa del 1828-1829", "9dff4e05"], "d": ["Dopo l'incendio della flotta a Navarino e la dichiarazione della Sublime Porta di non riconoscere la Convenzione di Akkerman, la Russia aprì la guerra su due fronti contemporaneamente. Poiché il Corpo dei giannizzeri era stato appena abolito e il nuovo esercito era ancora in formazione, la difesa ottomana fu debole fin dall'inizio; mentre i Russi attraversavano il Danubio, a oriente presero Kars e Akhaltsikhe. L'esercito russo, avanzato nel giro di un anno fino a Edirne, avrebbe imposto le dure condizioni del Trattato di Edirne del 1829 e l'indipendenza della Grecia.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["Primo trattato con gli Stati Uniti d'America", "d737516f"], "d": ["Con il trattato di commercio e navigazione firmato dopo anni di contatti, gli Stati Uniti ottennero nel territorio ottomano lo status di nazione più favorita e il diritto di transito commerciale dagli Stretti. Un articolo segreto separato prevedeva che l'Impero ottomano, se lo desiderava, facesse costruire navi nei cantieri americani e acquistasse navi pronte e legname; il Senato degli Stati Uniti ratificò il trattato ma respinse questo articolo segreto con 27 voti contro 18. La via delle navi non si chiuse comunque: Henry Eckford nel 1831 vendette agli Ottomani la nave che aveva portato e i maestri americani che lavoravano ad Aynalıkavak procurarono alla flotta navi di nuovo tipo. Questo trattato fu il documento della prima relazione di ampia portata dell'Impero ottomano con uno Stato fuori dall'Europa.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["Fine del governo kölemen a Baghdad", "7e1d38a3"], "d": ["Mahmud II, che perseguiva una politica di centralizzazione, dichiarò ribelle il governatore di Baghdad Dâvud Pascià, che non inviava il denaro richiesto e aveva fatto uccidere il funzionario giunto dal centro. La forza al comando di Ali Rızâ Pascià, dopo un assedio di novanta giorni, prese la città e quasi tutti i kölemen furono eliminati. Così il governo semi-indipendente dei Kölemen, in vigore dal 1704, ebbe fine e l'Iraq fu di nuovo legato direttamente al centro.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["Fondazione della Mekteb-i Harbiye nella caserma di Maçka", "bf31c7d9"], "d": ["Per fornire agli Asâkir-i Mansûre-i Muhammediyye ufficiali formati all'europea fu aperta nella caserma di Maçka la Mekteb-i Fünûn-ı Harbiyye. Agli studenti furono insegnati matematica, cartografia, fortificazione e lingue straniere; poco dopo furono inviati studenti a Vienna e a Parigi per rafforzare i quadri. Questa scuola fu il luogo in cui nacquero, nell'esercito ottomano, la tradizione dell'ufficiale formato nelle scuole e dunque la nuova generazione di militari-intellettuali che sarebbe emersa alla fine dell'Ottocento.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["Legame diretto di Tripolitania con il centro — fine della dinastia caramanlide", "faabcb96"], "d": ["In seguito alle lotte per il trono all'interno della famiglia Karamanlı e alla crescente pressione europea dopo l'occupazione di Algeri da parte della Francia nel 1830, la Sublime Porta intervenne direttamente in Tripolitania. La flotta inviata da Istanbul entrò in città, l'ultimo bey caramanlide fu destituito e portato a Istanbul e la provincia fu consegnata a un governatore nominato dal centro. Con la fine del periodo dinastico di 124 anni fu consolidato l'ultimo lembo di territorio nordafricano amministrato direttamente dall'Impero ottomano.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["Abolizione del defterdarlık e fondazione del Ministero delle Finanze (Maliye Nezâreti)", "89f8125e"], "d": ["Abolita la carica di defterdar, capo del classico ordinamento finanziario ottomano, fu istituito il Maliye Nezâreti, ministero di tipo europeo, e i tesori dispersi furono riuniti in un'unica mano. Nello stesso anno le altre unità della Sublime Porta furono riorganizzate sotto il nome di nezâret e si passò a una struttura moderna di consiglio dei ministri. Questo riordino fu uno dei passi più importanti nella preparazione dell'infrastruttura amministrativa dell'Editto di Tanzimat che sarebbe stato proclamato un anno dopo.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["Insediamento degli Inglesi ad Aden", "ddbd556b"], "d": ["L'Inghilterra, basandosi sul trattato di commercio e amicizia firmato nel 1802 con il sultano di Lahej Ahmed b. Abd al-Karim, sbarcò truppe nel porto di Aden e ne prese il controllo. Questo porto, che tiene l'imbocco del Mar Rosso, divenne come base di rifornimento di carbone sulla rotta dell'India il punto chiave della strategia imperiale inglese. Anche se la pretesa dell'Impero ottomano sullo Yemen continuò sulla carta, il suo dominio di fatto sulla costa meridionale non tornò più dopo questa data.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["Ritorno alla costa della Tihama: presa di Hodeida, Zabid e Mocha", "353982d2"], "d": ["Sulla costa dello Yemen rimasta senza padrone dopo il ritiro dell'esercito egiziano nel 1840, forze al comando di Tevfik Pascià, sotto la supervisione dello sharif della Mecca, sbarcarono e legarono all'amministrazione ottomana i porti di Hodeida, Zabid e Mocha. Si voleva avanzare fino a Sana'a, ma per la resistenza della popolazione si tornò a Hodeida; così gli altopiani rimasero agli imam zaiditi e il dominio ottomano per ventitré anni proseguì soltanto nella fascia della Tihama. Lo Yemen interno sarebbe stato ripreso solo nel 1872 con la campagna di Ahmed Muhtar Pascià.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Convenzione di Balta Limanı: protettorato congiunto ottomano-russo su Valacchia e Moldavia", "d3bb22e9"], "d": ["Dopo che le rivoluzioni del 1848 si erano estese a Valacchia e Moldavia, forze ottomane e russe avevano occupato insieme i principati. Con la convenzione firmata a Balta Limanı si stabilì che i voivodi non fossero eletti ma nominati dal sultano per sette anni e che i due Stati esercitassero un controllo congiunto sulla regione. L'accordo, pur conservando la sovranità ottomana sulla carta, riconobbe alla Russia un diritto di compartecipazione di fatto e accelerò il distacco dei principati danubiani dall'Impero ottomano.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["Questione dei rifugiati ungheresi: Kossuth e compagni si rifugiano nell'Impero ottomano", "1c7d7ef4"], "d": ["Dopo la repressione della rivoluzione ungherese del 1848-1849 con l'intervento russo-austriaco, Lajos Kossuth e migliaia di rifugiati ungheresi e polacchi si rifugiarono in territorio ottomano. Austria e Russia chiesero duramente l'estradizione dei rifugiati; la Sublime Porta, con il sostegno di Inghilterra e Francia, rifiutò l'estradizione e sistemò il gruppo a Kütahya. L'entourage di Kossuth vi rimase circa diciotto mesi e centinaia di rifugiati si convertirono all'islam ed entrarono al servizio ottomano. L'episodio fu considerato una delle rare vittorie diplomatiche che innalzarono il prestigio dell'Impero ottomano del Tanzimat presso l'opinione pubblica europea.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Fondazione dell'Encümen-i Dâniş: prima accademia ottomana a Istanbul", "6fda1365"], "d": ["L'Encümen-i Dâniş, fondato per decisione del Meclis-i Maârif-i Umûmiyye, è la prima accademia scientifica ottomana costituita per preparare opere scientifiche e libri di testo in turco. Fu inaugurato con una cerimonia il 18 luglio 1851 nell'edificio del Dârülmaârif; tra i suoi membri locali e stranieri c'era anche Ahmed Cevdet Pascià. Pur breve, opere come il Târih di Cevdet Pascià e il Kavâid-i Osmâniyye furono frutto di questa istituzione ed essa è considerata una pietra angolare nel divenire del turco lingua scientifica.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["Vittoria di Oltenița: primo successo ottomano sul fronte del Danubio", "a660ad2f"], "d": ["Nella fase iniziale della Guerra di Crimea il serdâr-ı ekrem Ömer Lütfi Pascià attraversò il Danubio e a Oltenița respinse le forze russe con gravi perdite. La vittoria, fermando l'avanzata russa subito all'inizio della guerra, mostrò all'Europa la forza che l'esercito ottomano aveva acquisito con l'addestramento dopo il Tanzimat. Questo successo preparò il terreno psicologico che facilitò la decisione di Inghilterra e Francia di entrare in guerra al fianco degli Ottomani.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["Trattato d'alleanza con Inghilterra e Francia a Istanbul", "04809278"], "d": ["Il trattato d'alleanza firmato nella Guerra di Crimea contro la Russia tra l'Impero ottomano, l'Inghilterra e la Francia stabilì che i tre Stati conducessero operazioni comuni e che gli alleati non facessero pace separata prima della fine della guerra. Così l'Impero ottomano entrò per la prima volta nella sua storia in un'alleanza militare con le grandi potenze europee come parte paritaria. Questo trattato costituì anche il fondamento giuridico dell'ammissione ufficiale dell'Impero ottomano al sistema degli Stati europei a Parigi due anni dopo.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["Fondazione dello Şehremaneti di Istanbul: prima organizzazione municipale moderna", "be4af27f"], "d": ["La crisi infrastrutturale causata dai soldati alleati affluiti a Istanbul durante la Guerra di Crimea e dalla popolazione in aumento rivelò l'insufficienza dell'amministrazione cittadina classica incentrata sul kadı. Con lo Şehremaneti, fondato sul modello europeo, pulizia, narh, controllo dei mercati e lavori urbanistici furono riuniti in un'unica mano; l'anno seguente a Beyoğlu-Galata fu costituito come zona pilota il Sesto Distretto Municipale (Altıncı Daire-i Belediye). Questo passo è considerato l'inizio dell'amministrazione municipale moderna nell'Impero ottomano.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["Trattato di Parigi: fine della Guerra di Crimea e ammissione dell'Impero ottomano al sistema degli Stati europei", "4aee0e2a"], "d": ["Con il Trattato di Parigi che pose fine alla Guerra di Crimea l'Impero ottomano fu dichiarato membro paritario del diritto degli Stati europei e la sua integrità territoriale fu posta sotto la garanzia comune delle grandi potenze. Il Mar Nero fu neutralizzato, la pretesa russa di protezione sui sudditi ortodossi, ottenuta dal Trattato di Küçük Kaynarca, fu dichiarata nulla, e la Bessarabia meridionale (distretti di Kilia, Cahul, Ismail e Bolgrad) fu data alla Moldavia. Ma lo stesso trattato, facendo dell'Editto di Riforma (Islahat Fermanı) un impegno internazionale, aprì anche la porta all'ingerenza negli affari interni.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["Apertura del Palazzo di Dolmabahçe: il centro amministrativo lascia Topkapı", "71ad26d0"], "d": ["Il palazzo commissionato da Abdülmecid nel 1842 alla famiglia Balyan fu aperto dopo quattordici anni di costruzione e il centro amministrativo dello Stato si trasferì dal Topkapı quadricentenario alla riva del Bosforo. Con lo stile europeo, lo scalone di cristallo e la Sala delle Cerimonie (Muayede Salonu), il palazzo fu l'espressione in pietra della pretesa occidentalizzatrice del Tanzimat. Il suo enorme costo divenne una delle voci più criticate degli anni in cui le finanze ottomane entrarono nella spirale dell'indebitamento estero.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["Unione di Valacchia e Moldavia sotto Cuza: nascita della Romania", "baef4da5"], "d": ["Nelle elezioni tenute dopo il Trattato di Parigi i due principati elessero entrambi voivoda il colonnello Alexandru Ioan Cuza, realizzando l'unione di fatto. Anche se la Sublime Porta e l'Austria si opposero, il fatto compiuto, sostenuto dalla Francia, dovette essere accettato. Quest'unione, rimasta sulla carta legata agli Ottomani, nel 1862 avrebbe assunto il nome di Romania e nel 1877 avrebbe dichiarato unilateralmente l'indipendenza; è un punto di svolta nello sgretolarsi del dominio ottomano lungo il Danubio.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Episodio di Kuleli: primo tentativo di colpo di Stato contro Abdülmecid a Istanbul", "e3653b21"], "d": ["Una società segreta mista di militari e civili, che reagiva alla politica del Tanzimat e all'uguaglianza concessa ai non musulmani dall'Editto di Riforma, mentre progettava di deporre il sultano fu scoperta durante una riunione nella moschea di Kılıç Ali Pascià. Poiché gli imputati furono processati nella caserma di Kuleli, il fatto è ricordato con questo nome; le condanne a morte furono commutate in esilio. È considerato il primo tentativo di colpo di palazzo, nella storia ottomana, di un'organizzazione costituita per motivi ideologici.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["Guerra civile drusa-maronita sul Monte Libano e fatti di Damasco", "5595fdd6"], "d": ["Gli scontri scoppiati nel maggio 1860 con l'uccisione di due drusi presso Sidone si trasformarono nella più sanguinosa guerra civile drusa-maronita della montagna e a luglio si estesero a Damasco, con la morte di migliaia di cristiani. Dopo lo sbarco di truppe francesi la Sublime Porta inviò nella regione Fuad Pascià con poteri straordinari; fu condotta una dura azione repressiva. Gli eventi costituirono il pretesto dell'intervento europeo e furono la causa diretta dell'acquisizione da parte del Libano di uno statuto speciale.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["Inizio delle pubblicazioni del Tercümân-ı Ahvâl: primo giornale turco privato a Istanbul", "24792957"], "d": ["Il Tercümân-ı Ahvâl, pubblicato da Agâh Efendi e con Şinâsi alla direzione redazionale, è il primo giornale turco pubblicato senza sostegno statale. Nella premessa del primo numero fu difeso il diritto del popolo di parlare dei propri affari e il giornale, pubblicando a puntate il Şair Evlenmesi di Şinâsi, aprì la porta anche alla letteratura turca moderna. La nascita nell'Impero ottomano del concetto di opinione pubblica e della stampa di opposizione è fatta risalire a questa data.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["Regolamento del Monte Libano: statuto di mutasarrıflık privilegiata per il Libano", "bf375603"], "d": ["Il regolamento preparato dopo i massacri del 1860 con la pressione delle grandi potenze fece del Monte Libano un mutasarrıflık privilegiato, legato direttamente alla Sublime Porta e governato da un consiglio amministrativo costituito secondo l'equilibrio tra le confessioni. Si stabilì che il mutasarrıf fosse un suddito ottomano cristiano cattolico e che la sua nomina fosse sottoposta all'approvazione delle grandi potenze; il primo mutasarrıf fu Dâvud Pascià. Questo ordinamento sarebbe durato fino al 1915 e avrebbe costituito il nucleo dello Stato libanese moderno.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["Morte di Abdülmecid e ascesa al trono del sultano Abdülaziz", "27204d7c"], "d": ["Quando Abdülmecid, che nel suo regno di ventidue anni aveva firmato gli editti di Tanzimat e di Riforma, soccombette alla tubercolosi, salì al trono il fratello Abdülaziz. Il nuovo sultano nei primi anni diede speranze con misure di risparmio e una vita sobria; fece della flotta una delle poche potenze del mondo. Ma alla fine del suo regno il pesante debito estero, la bancarotta del 1875 e le rivolte balcaniche, accumulandosi, avrebbero preparato il terreno al movimento di deposizione del 1876.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["I principati uniti assumono il nome di Romania", "d960e3fc"], "d": ["Valacchia e Moldavia, di fatto unite nel 1859 con la doppia elezione di Cuza, nel 1862, riunendo a Bucarest sotto un unico tetto assemblee e governi, assunsero ufficialmente il nome di Romania. Anche se l'Impero ottomano conservava giuridicamente la qualità di sovrano e il tributo annuo, perse di fatto il controllo sul principato. La fine dell'influenza ottomana quadricentenaria a nord del Danubio è simboleggiata da questa data.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["Annessione di Suakin, Massaua e Dahlak all'Egitto", "a0924860"], "d": ["Massaua, data nel 1846 dal sultano Abdülmecid al khedivé d'Egitto Mehmed Ali Pascià insieme a Suakin come sâlyâne (assegnazione di rendite), fu inclusa, al tempo del khedivé İsmâil Pascià, nei possedimenti dell'Egitto insieme a Dahlak e Suakin e organizzata con lo statuto di kaymakamlık. Così questi tre porti sulla costa africana del Mar Rosso, pur restando giuridicamente territorio ottomano, passarono sul piano amministrativo direttamente dalla Sublime Porta al Cairo — rientrando nello stesso strato di dipendenza dell'Egitto e del Sudan, loro vicini.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["Inizio della rivolta di Creta (1866-1869)", "3679b861"], "d": ["La sollevazione di vasta portata scoppiata sull'isola con l'aperto sostegno della Grecia fece per la prima volta della richiesta di enosis (unione alla Grecia) dei Greci di Creta una questione internazionale. L'aspra guerra di montagna, durata tre anni, inflisse gravi perdite all'esercito ottomano e suscitò grande eco nell'opinione pubblica europea. La rivolta poté spegnersi soltanto nel 1868, quando Âlî Pascià si recò sull'isola e mise in vigore il regolamento che concedeva ampi privilegi.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["Ritiro delle ultime guarnigioni ottomane dalle fortezze di Belgrado e Serbia", "b34217db"], "d": ["Per la pressione delle grandi potenze e l'insistente richiesta del principe Mihailo, la Sublime Porta accettò di evacuare le ultime basi militari rimaste in Serbia; il 18 aprile 1867 fu ammainata la bandiera ottomana nella Fortezza di Belgrado e le chiavi furono consegnate al principe. Così ebbe fine la presenza militare ottomana di fatto, in vigore dal 1521, e fu rimosso l'ultimo grande ostacolo sulla via dell'indipendenza della Serbia. La sovranità del sultano fu ridotta a una semplice questione di bandiera simbolica e tributo.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["Concessione del titolo di khedivé ai governatori d'Egitto", "09e10c12"], "d": ["In seguito alla fitta attività di lobby di İsmâil Pascià, della terza generazione della dinastia di Kavala, e al denaro da lui fatto affluire a Istanbul, al governatore d'Egitto fu concesso il titolo di khedivé, che sottolineava la sua superiorità sugli altri governatori. Negli stessi anni anche il sistema di successione fu cambiato in modo che passasse di padre in figlio e all'Egitto furono riconosciuti poteri di natura sovrana come contrarre debiti esteri, conferire decorazioni, tenere consolati. Questi passi sono il primo anello della catena che accelerò il distacco giuridico dell'Egitto dall'Impero ottomano.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["Regolamento di Creta: ampi privilegi amministrativi all'isola", "12052262"], "d": ["Per porre fine alla rivolta di tre anni il gran visir Âlî Pascià si recò personalmente sull'isola e con il regolamento pubblicato con l'approvazione del sultano furono concessi ai Cretesi consigli amministrativi misti, tribunali locali, l'uso del greco negli atti ufficiali e agevolazioni fiscali. Questo ordinamento mantenne in piedi per altri trent'anni il dominio ottomano sull'isola. Ma i privilegi concessi alla popolazione cristiana indebolirono la posizione dei Cretesi musulmani e gettarono i semi della crisi del 1896-1898.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Apertura dello Şûrâ-yı Devlet: fondazione del Consiglio di Stato ottomano", "70b16497"], "d": ["Con l'irade del 5 marzo 1868 il Meclis-i Ahkâm-ı Adliyye fu diviso in due: gli affari amministrativo-legislativi furono lasciati allo Şûrâ-yı Devlet, quelli giudiziari al Dîvân-ı Ahkâm-ı Adliyye; l'istituzione fu aperta con cerimonia alla Sublime Porta e alla presidenza fu posto Midhat Pascià. Fu incaricata di preparare i progetti di legge, di risolvere le controversie amministrative e di condurre i processi ai funzionari. Con la sua struttura mista di membri musulmani e non musulmani è considerata la prima applicazione istituzionale dell'idea di separazione dei poteri nell'Impero ottomano.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["Apertura del Canale di Suez: accorciamento della rotta dell'India attraverso l'Egitto", "377ccd04"], "d": ["La costruzione, iniziata nel 1859, durò dieci anni e il canale di 163 chilometri che collega il Mediterraneo al Mar Rosso entrò in servizio con una cerimonia sfarzosa. Quando la via che collega l'Europa all'India si accorciò di migliaia di miglia, l'Egitto divenne di colpo il punto chiave del commercio mondiale. Questo valore geostrategico sarebbe stato la principale ragione dell'occupazione dell'Egitto da parte dell'Inghilterra tredici anni dopo l'apertura del canale; il debito che il canale gravò sull'Egitto avrebbe portato il khedivato alla bancarotta.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["Fondazione dell'Esarcato bulgaro: la chiesa bulgara si separa dal Fanar", "33a8272c"], "d": ["Con un firmano del sultano fu istituita una chiesa bulgara autonoma (esarcato), separata dal Patriarcato greco, e quali distretti dovessero essere legati all'esarcato fu lasciato a un voto popolare. La Sublime Porta compì questo passo per spezzare l'influenza greca, ma il risultato fu opposto: la chiesa si trasformò nel centro organizzato dell'identità nazionale bulgara e della pretesa bulgara sulla Macedonia. Fu così gettata la base istituzionale della rivalità bulgaro-greco-serba nei Balcani e delle rivolte del 1876.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["Presa in amministrazione diretta dell'Asir", "4559e099"], "d": ["Quando con l'apertura del Canale di Suez crebbe il valore strategico del Mar Rosso, si vide che i monti dell'Asir, a metà della via di terra verso lo Yemen, non potevano essere lasciati incontrollati. Le forze di Redif Pascià, partite per la campagna dello Yemen, entrarono ad Abha e legarono la regione all'amministrazione ottomana diretta e fu fondato il sanjak di Asir. A causa della geografia montuosa e dell'influenza idrisida questo dominio non si assestò mai pienamente.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Campagna di Midhat Pascià nel Najd: ristabilimento del dominio ottomano ad al-Hasa", "7db51461"], "d": ["Il governatore di Baghdad Midhat Pascià, approfittando della lotta per il trono all'interno della famiglia saudita, inviò truppe sulla costa occidentale del Golfo Persico e legò la regione di al-Hasa alla provincia di Bassora con il nome di sanjak di Najd. Abdallah b. Faysal fu nominato mutasarrıf e il dominio ottomano fu stabilito sulla carta. La campagna aveva lo scopo di fermare la diffusione dell'influenza inglese nel Golfo e nello stesso anno portò anche al passaggio del Qatar sotto controllo ottomano.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["Morte del gran visir Âlî Pascià: fine del quadro dirigente del Tanzimat", "1cf0141c"], "d": ["Con la morte di Âlî Pascià, che dopo la scomparsa di Fuad Pascià nel 1869 aveva portato da solo sulle spalle la politica del Tanzimat, si esaurì la generazione di abili diplomatici che per trent'anni aveva guidato la politica estera dello Stato. Il governo filorusso e arbitrario di Mahmud Nedim Pascià, che gli succedette, consolidò la gestione personale di Abdülaziz. Nei cinque anni successivi alla morte di Âlî Pascià le finanze fallirono, i Balcani si sollevarono e il cambio di sultano divenne inevitabile.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["Instaurazione del controllo ottomano in Qatar", "3b453165"], "d": ["Su invito dello sceicco Qasim b. Thani, sotto pressione inglese, forze ottomane sbarcarono nella penisola del Qatar e nell'autunno del 1871 fu assicurato nella regione il controllo ottomano. Il Qatar fu organizzato come kaza dipendente dal sanjak di Najd e lo sceicco fu nominato kaymakam. Questa mossa fu il risultato più concreto della politica avanzata condotta da Midhat Pascià nel Golfo contro l'Inghilterra; la bandiera ottomana sventolò nella penisola fino al 1913.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["Firmano di successione per la Tunisia — il beylicato alla famiglia di Mehmed Sadık Pascià", "1509ebb0"], "d": ["Con il firmano emesso grazie alle iniziative di Hayreddin Pascià, inviato a Istanbul dal bey di Tunisi Mehmed Sadık Pascià, che aveva colto l'occasione della sconfitta della Francia contro la Prussia, la Tunisia fu data a Mehmed Sadık Pascià e ai suoi discendenti con sistema di successione, restando direttamente legata a Istanbul. Non si sarebbero condotti negoziati di guerra e di pace senza il permesso del sultano, nessun territorio del paese sarebbe stato dato ad altri e la richiesta ottomana di soldati sarebbe stata soddisfatta. La Francia non riconobbe il firmano; dieci anni dopo occupò la Tunisia.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["Presa di Sana'a: ristabilimento dell'autorità ottomana nello Yemen", "978e20a0"], "d": ["Quando con l'apertura del Canale di Suez crebbe il valore strategico del Mar Rosso, la Sublime Porta inviò nello Yemen l'esercito della fırka-i ihtiyâtiyye al comando di Ahmed Muhtar Pascià. Con la presa di Sana'a l'autorità dello Stato fu ristabilita nello Yemen interno, di fatto perso da due secoli, e la regione fu fatta provincia. Ma la lotta con gli imam zaiditi non finì mai; le rivolte del 1891, 1898 e 1904 costituirono il fronte interno più costoso e più lungo dell'Impero ottomano. Aynı tarihte katılan öteki yerler: Sana, Taiz.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["Inizio della rivolta d'Erzegovina: nuova fiammata della Questione d'Oriente", "571b18ec"], "d": ["La sollevazione dei contadini cristiani intorno a Nevesinje, causata dalle imposte pesanti e dalla pressione degli ayan, si estese presto a tutta l'Erzegovina e fu alimentata dai volontari giunti da Serbia e Montenegro. La rivolta, che portò Austria e Russia a imporre riforme, l'anno seguente provocò le sollevazioni bulgare e le dichiarazioni di guerra di Serbia e Montenegro. Così si spezzò il primo anello della grande catena che condusse alla Guerra del '93 e, con il Trattato di Berlino, alla perdita dei Balcani.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["Bancarotta delle finanze ottomane: dimezzamento dei pagamenti del debito estero", "2cac2fa5"], "d": ["I prestiti contratti di continuo dal 1854, le spese della Guerra di Crimea, le costruzioni di palazzi e la carestia anatolica del 1873-74 trasformarono il disavanzo di bilancio in un abisso superiore a cinque milioni di lire. Il governo di Mahmud Nedim Pascià, dichiarando che i pagamenti di interessi e capitale del debito sarebbero stati dimezzati per cinque anni, dichiarò di fatto una moratoria. Questa decisione, che suscitò grandi reazioni nelle borse europee, avviò il processo che sei anni dopo si sarebbe concluso con il Decreto di Muharrem e la fondazione dell'Amministrazione del Debito Pubblico (Düyûn-ı Umûmiyye).", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["Deposizione di Murad V e ascesa al trono di Abdülhamid II", "cffb2271"], "d": ["Murad V, salito al trono dopo la deposizione di Abdülaziz, per la morte dello zio e per la salute mentale scossa dall'episodio di Çerkes Hasan, divenne incapace di esercitare la carica; solo in sette giorni del suo regno di novantatré giorni il suo giudizio fu lucido. Deposto con fatwa dello şeyhülislam, gli subentrò il fratello Abdülhamid II. Il nuovo sultano salì al trono dando a Midhat Pascià la promessa di proclamare la monarchia costituzionale; iniziava un'epoca destinata a durare trentatré anni.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["Conferenza dei Cantieri (Tersane Konferansı): imposizione di riforme balcaniche da parte delle grandi potenze", "b5006a2c"], "d": ["La conferenza riunita a Istanbul dalle grandi potenze per risolvere la crisi balcanica chiese la divisione della Bulgaria in due province autonome e l'applicazione in Bosnia-Erzegovina di riforme sotto controllo internazionale. La Sublime Porta, annunciando con salve di cannone il giorno stesso dell'apertura della conferenza la proclamazione del Kanûn-ı Esâsî, cercò di rispondere alle imposizioni con una riforma costituzionale. I delegati, considerandola una manovra dilatoria, si dispersero il 20 gennaio 1877; quattro mesi dopo la Russia dichiarò guerra.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["Apertura a Dolmabahçe del primo Meclis-i Meb'ûsan", "429bb279"], "d": ["I 115 deputati eletti in base al Kanûn-ı Esâsî si riunirono per la prima volta il 19 marzo 1877 con una cerimonia nella Sala delle Cerimonie del Palazzo di Dolmabahçe; iniziò così nella storia ottomana il periodo dell'assemblea rappresentativa. I deputati musulmani e non musulmani interrogarono duramente il governo e discussero la conduzione della guerra e la responsabilità dei ministri. Questa coraggiosa opposizione sarebbe stata la principale causa dell'abbreviarsi della vita dell'assemblea.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["Inizio della difesa di Plevna: la resistenza di Gazi Osman Pascià", "0e04a878"], "d": ["Osman Pascià, marciato da Vidin a Plevna per tagliare la strada di Istanbul all'esercito russo che aveva attraversato il Danubio nella Guerra del '93, fortificò la cittadina con tabya e trincee e diede inizio a una leggendaria difesa di cinque mesi. Tre grandi attacchi successivi russo-romeni furono respinti con gravi perdite e l'esercito diretto personalmente dallo zar Alessandro II fu costretto all'assedio. Plevna è entrata nella storia come il più brillante successo difensivo dell'esercito ottomano nel XIX secolo.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["Caduta di Plevna: crollo del fronte del Danubio", "185e7602"], "d": ["Osman Pascià, esaurite le provviste dopo cinque mesi d'assedio, tentò una sortita sul fiume Vit; ferito e fatto prigioniero, la città si arrese. I comandanti russi salutarono il pascià prigioniero restituendogli la spada e a Osman Pascià fu dato il titolo di 'Gazi'. Con la caduta di Plevna la strada dell'esercito russo fu aperta; in due mesi caddero Sofia, Filippopoli ed Edirne e le avanguardie russe raggiunsero Yeşilköy.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["Occupazione di Sofia da parte delle forze russe", "ef369d22"], "d": ["Dopo la caduta di Plevna l'esercito russo, valicati i Balcani, entrò in Sofia rimasta senza difesa. La città non sarebbe più tornata all'amministrazione ottomana e alla fine del 1878 sarebbe diventata la capitale del Principato autonomo di Bulgaria, di fatto nel 1879. Sulla mappa Sofia da questa data esce dall'amministrazione diretta ottomana e passa a un'occupazione russa temporanea e poi all'amministrazione autonoma bulgara.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["Armistizio di Edirne: il silenzio delle armi nella Guerra del '93", "1f899180"], "d": ["Con la caduta in rapida successione di Sofia, Filippopoli ed Edirne e l'esercito russo giunto alle coste del Marmara, la Sublime Porta fu costretta a chiedere l'armistizio. La tregua firmata a Edirne fece accettare agli Ottomani condizioni preliminari di pace quali l'autonomia della Bulgaria, l'indipendenza di Montenegro, Serbia e Romania e una pesante indennità di guerra. Queste condizioni un mese dopo sarebbero diventate il testo del trattato di Santo Stefano.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Sospensione a tempo indeterminato del Meclis-i Meb'ûsan da parte di Abdülhamid II", "e770b540"], "d": ["Alle aspre critiche dei deputati, che ritenevano governo e palazzo responsabili del disastroso esito della guerra, Abdülhamid II, in base al potere conferitogli dal Kanûn-ı Esâsî, sospese l'assemblea a tempo indeterminato. Il primo parlamento ottomano, attivo per circa undici mesi, si chiuse così e iniziò l'epoca dell'istibdat (assolutismo), destinata a durare trent'anni. L'assemblea avrebbe potuto riunirsi di nuovo solo dopo la Rivoluzione del 1908.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["Trattato di Santo Stefano (Ayastefanos): progetto della Grande Bulgaria", "2c7cc611"], "d": ["Il Trattato di Santo Stefano, che pose fine alla Guerra del '93, istituiva una gigantesca Bulgaria autonoma che si estendeva fino all'Egeo e comprendeva la Macedonia; riconosceva l'indipendenza di Serbia, Montenegro e Romania; lasciava alla Russia Kars, Ardahan, Batum e Doğubayazıt e imponeva inoltre un'indennità di guerra impossibile da pagare. Questo testo, che portava la Russia al Mediterraneo, suscitò la violenta reazione di Inghilterra e Austria. Senza essere applicato fu riordinato nel giro di quattro mesi dal Congresso di Berlino; rimase tuttavia il documento che proclamò la fine della Rumelia ottomana.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["Kars, Ardahan e Batum lasciate alla Russia — elviye-i selâse", "99bdfad2"], "d": ["Con il Trattato di Berlino l'Impero ottomano lasciò alla Russia Kars, Ardahan e Batum in corrispondenza di una parte dell'indennità di guerra; Doğubayazıt e la valle di Eleşkirt, date alla Russia a Santo Stefano, rimasero invece agli Ottomani. Batum fu data come porto franco, ma poté conservare questo status solo fino al 1886. I Russi fecero di Kars una provincia dipendente dal governatorato generale della Transcaucasia con centro a Tiflis; una popolazione dell'elviye-i selâse che arrivava a 100.000 persone fu costretta a emigrare verso Erzurum. Con lo stesso trattato la Bessarabia meridionale (Kilia, Cahul, Bolgrad) fu restituita dalla Romania alla Russia.", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Occupazione di Bosnia-Erzegovina e Novi Pazar da parte dell'Austria-Ungheria", "e5f901df"], "d": ["In base all'autorizzazione data dal Trattato di Berlino, gli eserciti austro-ungarici entrarono in Bosnia; sebbene il governo ottomano avesse accettato di non resistere, la popolazione locale musulmana e ortodossa di Sarajevo e Mostar prese le armi e oppose per tre mesi una dura resistenza. L'occupazione poté essere completata solo il 20 ottobre 1878. La sovranità giuridica del sultano continuò sulla carta fino al 1908, ma la Bosnia ottomana, quadricentenaria, andò di fatto perduta e iniziò una grande ondata migratoria musulmana. Aynı tarihte elden çıkan diğer yerleşimler: Banaluka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Decreto di Muharrem e fondazione dell'Amministrazione del Debito Pubblico (Düyûn-ı Umûmiyye)", "02b7cc03"], "d": ["I negoziati condotti con i rappresentanti degli Stati creditori dopo la bancarotta del 1875 si conclusero con il decreto datato 28 Muharrem 1299 (20 dicembre 1881): il capitale del debito fu ridotto di oltre la metà e in cambio le voci di reddito più redditizie, come le imposte su sale, tabacco, seta, bollo e pesca, furono cedute all'Amministrazione del Debito Pubblico (Düyûn-ı Umûmiyye), gestita direttamente dai creditori. Questa amministrazione, che impiegava migliaia di funzionari, si trasformò in un'organizzazione finanziaria distinta all'interno dello Stato. È considerata la data in cui l'indipendenza finanziaria ottomana terminò di fatto.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Suakin — l'unico porto non caduto in mano al Mahdi", "5a37b198"], "d": ["Mentre dal febbraio 1884 tutte le regioni del Sudan orientale tranne Suakin passavano sotto il dominio di Muhammad Ahmad al-Mahdi, il porto rimase in piedi grazie alla protezione militare di una forza britannica di tre battaglioni al comando del generale Graham. Fu l'inizio di un periodo in cui situazione di fatto e di diritto si separarono: sebbene la costa fosse di fatto sotto controllo militare britannico, il suo legame amministrativo nel 1885 sarebbe stato tolto all'Egitto e legato direttamente alla provincia dello Yemen, cioè alla Sublime Porta — quell'ordinamento durò fino al 1888, quando terminò con l'occupazione di Zeila da parte della Francia.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Uccisione di Midhat Pascià nella prigione di Ta'if", "f4562261"], "d": ["Midhat Pascià, architetto del Kanûn-ı Esâsî e nome simbolo della Prima monarchia costituzionale, giudicato colpevole dal Tribunale di Yıldız in relazione alla morte di Abdülaziz e con la pena capitale commutata in esilio, era stato inviato a Ta'if. Secondo la scheda TDV, nella notte del 7-8 maggio 1884 fu strangolato nella sua cella e come causa ufficiale fu indicata la malattia 'şîrpençe'. La sua morte divenne il simbolo della liquidazione dell'opposizione costituzionale sotto Abdülhamid II.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Concessione ai Tedeschi della ferrovia Haydarpaşa-Ankara", "5705b163"], "d": ["Con irade del sultano la concessione di costruzione e gestione della linea Haydarpaşa-Ankara fu data al banchiere Alfred von Kaulla, rappresentante della Deutsche Bank, e fu fondata la Società delle Ferrovie Anatoliche. Questa concessione fu il punto di svolta che spezzò il monopolio anglo-francese nei trasporti e nella politica estera ottomana e radicò l'influenza tedesca. Con la concessione della linea di Baghdad che sarebbe stata data alla stessa società undici anni dopo, sarebbe nato il sogno 'Berlino-Baghdad', che sarebbe divenuto uno degli assi principali della rivalità tra grandi potenze prima della Prima guerra mondiale.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Fondazione a Istanbul dell'Ittihad-ı Osmânî Cemiyeti", "b7187939"], "d": ["Quattro studenti della Scuola Militare di Medicina (Askerî Tıbbiye) fondarono come organizzazione segreta contro il regime dell'istibdat l'İttihâd-ı Osmânî Cemiyeti; questa struttura si trasformò presto nel Comitato Unione e Progresso (İttihat ve Terakkî Cemiyeti), che avrebbe riunito sotto il proprio tetto tutti gli elementi di opposizione del movimento dei Giovani Turchi. L'organizzazione, basata su cellule, si unì agli esuli in Europa e agli ufficiali di Salonicco. Da questa piccola cellula di studenti uscì il gruppo che nel 1908 avrebbe fatto proclamare la Seconda monarchia costituzionale e che dopo il 1913 avrebbe governato da solo lo Stato.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Irruzione alla Banca Ottomana: azione degli attivisti Dashnak a Galata", "08b3095f"], "d": ["Un gruppo armato dell'organizzazione armena Dashnaktsutyun, con lo scopo di attirare l'attenzione dell'Europa sulla questione armena, fece irruzione nella sede centrale della Banca Ottomana a Galata, prese ostaggi e minacciò di far saltare l'edificio. La crisi si concluse, con l'intervento degli ambasciatori, in cambio dell'allontanamento degli attivisti dal paese su una nave. I sanguinosi eventi verificatisi a Istanbul nei giorni successivi all'irruzione furono determinanti nella trasformazione della questione armena in una leva di intervento internazionale.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["Inizio della guerra ottomano-greca del 1897: fronte di Tessaglia", "33e490ab"], "d": ["In seguito allo sbarco di flotta e truppe della Grecia a Creta e agli attacchi di bande al confine della Rumelia, l'Impero ottomano dichiarò guerra. L'esercito ottomano, addestrato dalla missione tedesca di riforma, avanzò rapidamente in Tessaglia e in un mese prese Yenişehir (Larissa), Çatalca e Dömeke; l'esercito greco si disperse. Con l'intervento delle grandi potenze i territori conquistati furono restituiti, ma la guerra rimase l'unica vittoria militare netta dell'epoca di Abdülhamid II e non poté evitare la perdita di fatto di Creta.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Concessione ai Tedeschi della linea Konya-Baghdad", "fd8b6cbd"], "d": ["Dopo la visita del Kaiser Guglielmo II a Istanbul e Damasco nel 1898, alla Società delle Ferrovie Anatoliche fu data la concessione preliminare per la linea che da Konya si sarebbe estesa a Baghdad e Bassora. Il progetto della Ferrovia di Baghdad significava per gli Ottomani il rafforzamento del controllo centrale sulle province arabe, per la Germania il raggiungimento del Golfo Persico. Questo progetto, a cui Inghilterra e Russia si opposero con forza, divenne uno dei dossier più controversi della rivalità imperialista che portò alla Prima guerra mondiale.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Inizio a Damasco della costruzione della Ferrovia dell'Hijaz", "62f58f68"], "d": ["La linea ordinata con l'irade di Abdülhamid II del 2 maggio 1900 vide l'inizio dei lavori il 1° settembre 1900 con una cerimonia ufficiale a Damasco. Il progetto, realizzato interamente con donazioni raccolte nel mondo islamico e con il lavoro di ingegneri-soldati ottomani, ridusse il viaggio dei pellegrini Damasco-Medina da quaranta giorni a cinque. Fu allo stesso tempo un'opera di prestigio che rafforzava l'autorità spirituale del califfato e un investimento strategico che consolidava il controllo militare sull'Hijaz.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Programma di Mürzsteg: controllo internazionale delle riforme in Macedonia", "4c7464da"], "d": ["Dopo la rivolta di Ilinden gli imperatori russo e austriaco, incontratisi a Mürzsteg, prepararono un nuovo pacchetto di riforme per la Macedonia. Il programma prevedeva l'affiancamento di due agenti civili stranieri all'ispettore generale ottomano, la riorganizzazione della gendarmeria da parte di ufficiali europei e la modifica dei confini amministrativi secondo il criterio della nazionalità. La Sublime Porta oppose resistenza ritenendo lesi i diritti di sovranità, ma di fronte alla pressione comune dovette accettare; il programma fu uno dei fattori fondamentali che accelerarono l'organizzazione unionista tra i giovani ufficiali.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["Morte di Murad V", "396659a7"], "d": ["Murad V, rimasto sul trono circa tre mesi nel 1876 e deposto, dopo i tentativi di rimetterlo sul trono visse ventotto anni prigioniero sotto stretta sorveglianza e morì di diabete. Fu sepolto accanto alla madre nel Mausoleo Cedîd Havâtîn di Yenicami. Entrò nella storia come il sultano ottomano rimasto meno tempo sul trono.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Perdita di Sana'a a favore dell'imam Yahya", "e7f876cb"], "d": ["La rivolta avviata nel 1904 dall'imam zaidita Yahya Hamid al-Din si concluse nell'aprile 1905 con la caduta di Sana'a al termine dell'assedio; la città uscì dall'amministrazione ottomana e durante l'assedio si diffusero fame ed epidemia. La geografia montuosa dello Yemen, la lunghezza delle linee di rifornimento e la legittimità locale dell'imamato zaidita rendevano fragile il dominio ottomano fin dalla sua fondazione. La città sarebbe stata ripresa cinque mesi dopo a costo di gravi perdite, ma la questione dello Yemen non si sarebbe chiusa fino al 1918.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Attentato di Yıldız: attacco con bomba ad Abdülhamid II", "1ee2e1a6"], "d": ["L'organizzazione Dashnaktsutyun compì un attentato facendo esplodere una landò con bomba a orologeria davanti alla carrozza del sultano all'uscita dal selâmlık del venerdì; il ritardo di qualche minuto di Abdülhamid, che parlava con lo şeyhülislam, gli salvò la vita. Nell'esplosione morirono ventisei persone e più di cinquanta furono ferite. Il fatto inasprì ulteriormente l'ossessione per la sicurezza del sultano e il regime dell'istibdat fondato sulla rete di spie; fu anche il soggetto della poesia 'Bir Lahza-i Taahhur' di Tevfik Fikret.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Ripresa di Sana'a: repressione della rivolta dell'imam Yahya", "dec3b8f9"], "d": ["La rivolta avviata nel 1904 sotto la guida dell'imam zaidita Yahya si concluse nell'aprile 1905 con la caduta di Sana'a e in città si diffusero fame ed epidemia. Gli eserciti di rinforzo al comando di Ali Rızâ Pascià e Ahmed Feyzi Pascià, con un'operazione condotta tra il 15 luglio e il 1° settembre 1905 e sostenuta anche dalle forze di Taiz, ripresero la città a costo di gravi perdite e la rivolta fu repressa. La campagna dello Yemen costò all'esercito ottomano decine di migliaia di perdite e un onere finanziario enorme; tra gli ufficiali della Rumelia la paura dell''esilio nello Yemen' era tra i primi motivi di lamentela che alimentavano l'organizzazione unionista.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Riunione del primo Meclis-i Meb'ûsan della Seconda monarchia costituzionale", "e7fd2716"], "d": ["L'assemblea formata con elezioni a due gradi tenute dopo un intervallo di trent'anni fu aperta il 17 dicembre 1908 con il discorso del sultano e alla presidenza fu eletto Ahmed Rızâ Bey, leader del movimento dei Giovani Turchi. Composta da deputati turchi, arabi, albanesi, greci, armeni ed ebrei, l'assemblea fu l'ultimo grande tentativo dell'ideale ottomanista. Ma l'indipendenza della Bulgaria, l'annessione della Bosnia e la proclamazione dell'unione di Creta alla Grecia avevano offuscato questo ottimismo prima ancora dell'apertura dell'assemblea.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Hareket Ordusu e deposizione di Abdülhamid II: ascesa al trono di Mehmed V Reşad", "6a65a704"], "d": ["L'Hareket Ordusu (Esercito d'Azione), partito da Salonicco dopo l'episodio del 31 Mart, entrò a Istanbul su quattro colonne nella notte del 22-23 aprile e il 24 aprile il Palazzo di Yıldız si arrese. Il Meclis-i Umûmî-i Millî il 27 aprile decise la deposizione di Abdülhamid II; il sultano fu inviato a Salonicco e al suo posto fu fatto salire al trono il fratello Mehmed V Reşad. Il governo personale di trentatré anni ebbe così fine, ma fu sostituito da una nuova epoca in cui il sultano era diventato un simbolo e il Comitato Unione e Progresso governava con il sostegno dell'esercito.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Rivolta albanese: resistenza armata a Kosovo e Scutari", "93ed30c6"], "d": ["La politica fiscale centralista del governo unionista, la campagna di raccolta delle armi e il dibattito sull'alfabeto latino fecero sollevare le tribù albanesi, fino ad allora considerate tra gli elementi più fedeli allo Stato. Anche se l'esercito al comando di Mahmud Şevket Pascià represse duramente la rivolta, l'inquietudine si riaccese nel 1911 e nel 1912. Queste rivolte logorarono l'esercito ottomano alla vigilia della Guerra balcanica e accelerarono la nascita del movimento nazionale albanese.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Trattato di Ouchy (Uşi): cessione di Tripolitania e Bengasi all'Italia", "4ffa1fd2"], "d": ["La Sublime Porta, che di fronte ai preparativi bellici degli Stati balcanici non poteva permettersi di affrontare un conflitto su due fronti, firmò con l'Italia nella cittadina svizzera di Ouchy una pace segreta e cedette Tripolitania e Bengasi. L'Impero ottomano perse così il suo ultimo territorio in Africa; in cambio fu promessa la restituzione di Rodi e delle Dodecaneso occupate dall'Italia, ma la promessa non fu mai mantenuta. Quando il trattato fu firmato la Guerra balcanica era già iniziata. Con questo fatto Murzuq (Fezzan), Ghat, Sebha, Ubari, Tırgan (Traghan), Zevîle (Zawila) e el-Katrûn (Fizan (Trablusgarp vilâyeti sancağı)) passarono sotto amministrazione italiana.", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["Occupazione greca di Lemno", "9555af1d"], "d": ["Nella Prima guerra balcanica la flotta greca occupò Lemno; il porto di Mudros dell'isola divenne base per il blocco dei Dardanelli. L'isola fu lasciata alla Grecia a Losanna (24 luglio 1923).", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["Occupazione greca di Taso", "6c03c7f0"], "d": ["Nella Prima guerra balcanica la Grecia occupò Taso e Samotracia.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["Occupazione greca di Samotracia", "911e82a3"], "d": ["Nella Prima guerra balcanica la Grecia occupò Samotracia.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["Occupazione greca di Mitilene (Lesbo)", "6b2b07ba"], "d": ["La flotta greca sbarcò a Mitilene; l'isola alla fine della Prima guerra balcanica fu presa dall'esercito e dalla flotta greci. La Conferenza di Londra (maggio 1913) confermò la situazione.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["Sbarco greco a Chio", "901c6539"], "d": ["A Chio, bombardata il 7 aprile 1912 nella Prima guerra balcanica, i Greci effettuarono lo sbarco; la guarnigione ottomana si arrese il 3 gennaio 1913. L'isola fu lasciata alla Grecia con il Trattato di Losanna (24 luglio 1923).", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Uccisione per attentato a Istanbul del gran visir Mahmud Şevket Pascià", "68e60e63"], "d": ["Mahmud Şevket Pascià, nominato gran visir dopo l'irruzione alla Sublime Porta, fu ucciso dai colpi sparati contro la sua carrozza presso Çarşıkapı mentre si recava al Ministero della Guerra. Il Comitato Unione e Progresso, addossando l'attentato all'opposizione, avviò una vasta ondata di arresti ed esecuzioni e il Partito della Libertà e dell'Intesa fu di fatto liquidato. Con questo fatto fu stabilita in modo definitivo la dittatura a partito unico degli unionisti, fondata sul triumvirato Enver-Talat-Cemal.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Inizio della Seconda guerra balcanica: lite degli alleati per la spartizione", "48d088a2"], "d": ["Gli alleati balcanici, che non riuscivano a spartirsi i territori tolti agli Ottomani con il Trattato di Londra, si scontrarono tra loro; con l'attacco della Bulgaria alle posizioni serbe e greche iniziò la seconda guerra. Quando anche Romania e Montenegro entrarono in campo contro la Bulgaria l'esercito bulgaro crollò. L'Impero ottomano, approfittando dell'occasione, superò la linea Midye-Enez tracciata dal Trattato di Londra e riprese la Tracia orientale con Edirne.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Trattato di Istanbul: pace con la Bulgaria e registrazione di Edirne", "c8c18b2d"], "d": ["Il trattato firmato tra l'Impero ottomano e la Bulgaria dopo la Seconda guerra balcanica, riconoscendo il fiume Maritza (Meriç) come confine, sancì giuridicamente che Edirne, Kırklareli, Dimetoka e la Tracia orientale restassero agli Ottomani. Dedeağaç fu lasciata alla Bulgaria (Kavala invece era passata alla Grecia nel luglio 1913 dopo l'occupazione bulgara dell'autunno 1912 ed era stata registrata come greca con il Trattato di Bucarest del 10 agosto 1913), furono regolati uno scambio reciproco di popolazione tra i due paesi e i diritti dei musulmani in Bulgaria. Questo testo è la garanzia dell'unico lembo di territorio che fu possibile riprendere dal disastro balcanico. Aynı tarihte katılan öteki yerler: Gümülcine.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["Ripresa di Bozcaada e Imbro — Trattato di Atene", "ec084d09"], "d": ["Bozcaada e Imbro, che tengono l'imboccatura dello Stretto, tra le isole dell'Egeo settentrionale occupate dalla Grecia nella Guerra balcanica, furono considerate indispensabili per la difesa di Çanakkale nei negoziati del Trattato di Atene e furono restituite agli Ottomani. Le altre isole restarono alla Grecia. Queste due isole furono gli ultimi territori che l'Impero tenne nell'Egeo e furono lasciate alla Turchia anche a Losanna.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Trattato di Atene: pace con la Grecia e cessione di Salonicco e Ioannina", "8e94def7"], "d": ["Il trattato firmato tra l'Impero ottomano e la Grecia riconobbe ufficialmente il passaggio alla Grecia di Salonicco, Ioannina e Macedonia meridionale, perdute nella Guerra balcanica, e fu abbandonato ogni diritto ottomano su Creta. Furono regolati in dettaglio i diritti di religione e proprietà dei musulmani rimasti in Grecia, lo statuto dei vakıf e la nomina dei müftü. Lo statuto delle isole dell'Egeo fu invece lasciato irrisolto e rimase una fonte di tensione continua tra i due Stati.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Firma a Istanbul del trattato segreto d'alleanza ottomano-tedesco", "0472efb3"], "d": ["Non appena scoppiò la guerra in Europa, nel palazzo del gran visir Said Halim Pascià fu firmato un trattato segreto d'alleanza tra l'Impero ottomano e la Germania; il testo prevedeva che, nel caso la Russia fosse entrata in guerra contro la Germania, gli Ottomani si schierassero con la Germania. Il trattato fu nascosto persino al gabinetto ed era noto solo a quattro persone. Tre mesi dopo, con l'incursione nel Mar Nero, l'Impero ottomano sarebbe stato di fatto trascinato in guerra e il destino dell'Impero fu legato con questo documento.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Abolizione unilaterale delle capitolazioni", "ec773d18"], "d": ["Il governo ottomano, in un momento in cui l'Europa era impegnata nella guerra, dichiarò di abolire unilateralmente dal 1° ottobre 1914 le capitolazioni, che riconoscevano agli stranieri privilegi giudiziari, finanziari e doganali. La fine di questo ordinamento di privilegi quadricentenario fu accolta nel paese con grande entusiasmo d'indipendenza e a Istanbul si tennero celebrazioni. Tutti gli Stati, compresa l'alleata Germania, protestarono contro la decisione; le capitolazioni sarebbero entrate definitivamente nella storia solo nel 1923 a Losanna.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Incursione nel Mar Nero: bombardamento dei porti russi da parte della flotta ottomana", "8ad4ef61"], "d": ["Il Goeben e il Breslau (Yavuz e Midilli), fuggiti dalla Germania e uniti alla flotta ottomana come se fossero stati 'acquistati', al comando dell'ammiraglio Souchon si spinsero nel Mar Nero, bombardarono i porti russi e affondarono navi. Questo ordine, dato da Enver Pascià all'insaputa del gabinetto, pose fine di fatto alla neutralità. Entro una settimana Russia, Inghilterra e Francia dichiararono guerra e l'Impero ottomano entrò nella Prima guerra mondiale in modo irreversibile.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Presa di Fao da parte delle forze anglo-indiane — apertura del fronte iracheno", "08663813"], "d": ["La mattina successiva al giorno in cui gli Stati dell'Intesa dichiararono guerra all'Impero ottomano, la brigata anglo-indiana in attesa a Bahrein sbarcò a Fao, alla foce dello Shatt al-Arab. Il piccolo reparto ottomano nella fortezza in rovina di Fao si ritirò sotto il fuoco delle navi da guerra e la stazione della linea telegrafica dell'India passò in mano agli Inglesi. Il fronte iracheno fu così aperto.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Proclamazione del Cihâd-ı Ekber: lettura della fatwa del jihad nella moschea di Fatih", "2a6174e8"], "d": ["Le cinque fatwa emesse dallo şeyhülislam Ürgüplü Hayri Efendi furono lette nella moschea di Fatih a nome del sultano-califfo e tutti i musulmani furono chiamati al jihad contro gli Stati dell'Intesa. Questa mossa, su cui la Germania riponeva grandi speranze, mirava a sollevare i musulmani delle colonie inglesi e francesi. La sollevazione generale attesa non avvenne; al contrario, la rivolta dell'emiro della Mecca Sharif Husayn con il sostegno inglese, due anni dopo, mostrò amaramente i limiti dell'influenza politica del califfato.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Resa di Qurna agli Inglesi", "621d36b0"], "d": ["Le forze del governatore di Bassora Subhi Bey, ritiratesi dopo la caduta di Bassora a Qurna, dove si uniscono Tigri ed Eufrate, dopo gli scontri del 4-8 dicembre si arresero la mattina del 9 dicembre 1914.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-18:0":{"b": ["Protettorato britannico sull'Egitto e proclamazione del sultanato", "55d4e520"], "d": ["Con l'entrata in guerra dell'Impero ottomano l'Inghilterra dichiarò di porre ufficialmente sotto la propria protezione l'Egitto, che occupava di fatto dal 1882; il khedivé Abbas Hilmi Pascià, rimasto fedele agli Ottomani, fu destituito e al suo posto fu messo Hüseyin Kâmil con il titolo di 'sultano'. Così la sovranità giuridica ottomana, in vigore dal 1517, fu fatta cessare unilateralmente. La Sublime Porta non riconobbe la decisione e due mesi dopo tentò di riprendere l'Egitto con l'Operazione del Canale.", "0eae0c0c"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Operazione di Sarıkamış: disastro sul fronte del Caucaso", "5cbde7f0"], "d": ["Enver Pascià, con lo scopo di riprendere Kars-Ardahan-Batum, perduti nel 1878, e di sollevare i Turchi del Caucaso, spinse in inverno la III Armata, attraverso i monti Allahuekber, in una manovra per accerchiare le forze russe. Per l'equipaggiamento invernale insufficiente, i rifornimenti esauriti e le tormente fino a trenta gradi sotto zero, l'armata si sciolse prima ancora di entrare in battaglia; decine di migliaia di soldati morirono assiderati. L'operazione fu uno dei più gravi disastri ottomani nella guerra e lasciò il fronte orientale indifeso per due anni.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Prima Operazione del Canale: attacco a Suez attraverso il deserto del Sinai", "02dd72f5"], "d": ["Il comandante della IV Armata Cemal Pascià, con lo scopo di liberare l'Egitto dall'occupazione britannica e di chiudere il Canale di Suez alla navigazione, organizzò un attacco attraverso il deserto del Sinai. Anche se le unità ottomane raggiunsero la riva orientale del canale e alcune riuscirono ad attraversarlo, si ritirarono per la superiorità britannica e per il mancato verificarsi della sollevazione popolare egiziana attesa. L'operazione non raggiunse l'obiettivo, ma creò un effetto strategico indiretto costringendo l'Inghilterra a mantenere in Egitto una grande forza.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Emanazione della Legge di Deportazione e Insediamento (Sevk ve İskân / Tehcir)", "2f2bc22c"], "d": ["Dopo la rivolta di Van e l'avanzata russa, il governo emanò la legge provvisoria che permetteva ai comandanti d'armata di trasferire in altre regioni la popolazione ritenuta pericolosa per la sicurezza nelle retrovie, e il sultano la ratificò il 27 maggio 1915. Come conseguenza dell'applicazione, gran parte della popolazione armena delle province orientali e meridionali dell'Anatolia fu avviata in direzione di Siria e Mosul; durante i trasferimenti si ebbero perdite di vite umane molto gravi a causa di malattie, fame e aggressioni. La decisione è rimasta la questione più grave e ancora oggi più controversa degli ultimi anni ottomani.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["Le unità ottomane riprendono Muş all'occupazione russa", "fb1be113"], "d": ["Sei mesi dopo la prima occupazione russa di Muş, il XVI Corpo d'armata ottomano entrò nella cittadina nella controffensiva di Bitlis-Muş.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Muş passa di nuovo in mano russa", "43ad8a03"], "d": ["Per la controffensiva russa il distaccamento ottomano evacuò Muş; la cittadina tra il 22 e il 25 agosto 1916 entrò di nuovo sotto occupazione russa e vi rimase fino alla primavera del 1917.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Muş liberata definitivamente dall'occupazione russa", "f0e89703"], "d": ["Muş, passata sotto occupazione russa nella Prima guerra mondiale, fu ripresa in modo definitivo dalle forze ottomane il 1° maggio 1917.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Morte di Abdülhamid II nel Palazzo di Beylerbeyi", "c9662582"], "d": ["Abdülhamid II, deposto nel 1909 e portato prima a Salonicco e poi, per la perdita della città nella Guerra balcanica, a Istanbul, dove era tenuto agli arresti nel Palazzo di Beylerbeyi, morì. Nei trentatré anni del suo regno aveva cercato di guadagnare tempo tenendo lo Stato lontano dalle guerre, ma era anche ricordato per il regime dell'istibdat. La salma fu sepolta con una grande folla nel mausoleo di Mahmud I a Divanyolu; la sua morte coincise con un anno di guerra in cui l'ordine da lui creato era da tempo liquidato.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Trattato di Brest-Litovsk: ripresa di Kars, Ardahan e Batum", "da82636f"], "d": ["Il trattato firmato tra la Russia, ritiratasi dalla guerra dopo la rivoluzione bolscevica, e gli Imperi centrali chiuse il fronte orientale e restituì all'Impero ottomano Kars, Ardahan e Batum (Elviye-i Selâse), perduti con il Trattato di Berlino del 1878. Fu l'unico guadagno territoriale ottenuto nella storia ottomana dopo un intervallo di quarant'anni. Ma dopo l'Armistizio di Mudros la regione sarebbe andata di nuovo perduta e la soluzione definitiva sarebbe venuta con il Trattato di Kars del 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Le unità ottomane entrano ad Artvin", "ca7d1778"], "d": ["Le unità ottomane, che il 25 marzo avevano superato il confine del 1914, marciarono sull'Elviye-i Selâse, di cui Brest-Litovsk restituiva il confine anteriore al 1878, ed entrarono ad Artvin il 28 marzo 1918. Artvin era stata lasciata alla Russia nel 1878 come parte del sanjak di Batum; la voce Artvin del TDV scrive il ritorno soltanto come 'marzo 1918', il giorno lo dà Mustafa Sarı.", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ardahan passa in mano all'esercito turco", "7fd9e3db"], "d": ["Nell'operazione dell'Elviye-i Selâse l'esercito ottomano prese Ardahan, dopo Artvin, il 3 aprile 1918; Ardahan era caduta nella Guerra del '93 nel 1877 ed era stata lasciata alla Russia nel 1878. Kars sarebbe stata presa un mese dopo, il 25 aprile.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["Ripresa di Batum", "d37a1a0d"], "d": ["L'esercito ottomano, avanzato verso est dopo il ritiro della Russia dalla guerra con il Trattato di Brest-Litovsk, riprese dopo quarant'anni il porto di Batum, perduto nel 1878. Questo porto, all'estremità orientale del Mar Nero, era lo sbocco marittimo del petrolio di Baku. Il guadagno durò soltanto sette mesi; dopo l'Armistizio di Mudros la regione sarebbe stata evacuata.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elviye-i Selâse: Kars entra sotto amministrazione ottomana", "02cbf0b3"], "d": ["A Brest-Litovsk fu deciso il ritorno dei tre sanjak perduti con il Trattato di Berlino del 1878 — Kars, Ardahan e Batum; l'esercito ottomano entrò ad Ardahan il 3 aprile, a Batum il 14 aprile, a Kars il 25 aprile 1918 e l'amministrazione fu di fatto stabilita. Questi territori, noti con il nome di 'Elviye-i Selâse', furono considerati la compensazione della perdita in corso dalla Guerra del '93. Dopo l'armistizio sarebbero andati di nuovo perduti e sarebbero stati legati alla Turchia in modo definitivo solo con il Trattato di Kars del 1921.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Presa di Iğdır — avanzata nella valle dell'Aras", "87ebf4d3"], "d": ["Nel quadro dell'operazione in avanti iniziata nel febbraio 1918, le unità turche sconfissero le unità armene a Serderabad, a nord dell'Aras, e presero Iğdır il 20 maggio 1918. Iğdır non faceva parte dell'Elviye-i Selâse, ma era il distretto di Sürmeli del governatorato di Erevan; dopo circa 180 anni fu stabilita nella regione la prima amministrazione ottomana.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Morte di Mehmed V Reşad e ascesa al trono di Mehmed VI Vahdeddin", "d302ba07"], "d": ["Mehmed V Reşad, il cui regno di nove anni era trascorso tra le guerre di Tripolitania, balcaniche e mondiale, morì nel periodo più critico della guerra e al suo posto salì al trono il fratello Vahdeddin con il nome di Mehmed VI. Il nuovo sultano cercò di liberarsi dalla tutela del gruppo unionista; quattro mesi dopo, quando fu firmato l'armistizio, avrebbe dovuto gestire la liquidazione dell'Impero. Fu il trentaseiesimo e ultimo sultano della dinastia ottomana.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Arrivo della flotta dell'Intesa davanti a Istanbul e occupazione di fatto della città", "d10cb14d"], "d": ["Dopo l'Armistizio di Mudros la flotta alleata, composta da oltre sessanta unità di navi inglesi, francesi, italiane e greche, gettò l'ancora davanti a Dolmabahçe e Istanbul passò di fatto sotto occupazione. Dopo quattrocentosessantacinque anni la capitale era per la prima volta sotto il controllo di soldati stranieri. La frase 'Come sono venuti se ne andranno', che si racconta sia stata pronunciata lo stesso giorno da Mustafa Kemal Pascià sbarcato a Haydarpaşa alla vista del panorama, sarebbe divenuta una delle frasi simbolo della Lotta Nazionale.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["Ritirata nella regione dell'Aras: evacuata Iğdır", "57572ab4"], "d": ["In conformità alla disposizione dell'Armistizio di Mudros sul ritiro dietro il confine del 1914, Yakup Şevki Pascià con l'ordine del 21 novembre ordinò di ritirare entro il 4 dicembre le unità fuori dal confine di Brest-Litovsk; Iğdır e dintorni furono completamente evacuati a questa data. Poi il Governo Aras-Turco fu rovesciato dagli Armeni alla fine del dicembre 1918.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["Gli Inglesi si insediano ad Artvin", "e2cb3153"], "d": ["Poiché l'Armistizio di Mudros del 30 ottobre 1918 imponeva il ritiro dell'esercito ottomano dietro il confine del 1914, Artvin fu evacuata e il 17 dicembre 1918 fu occupata dagli Inglesi. Secondo la voce Artvin del TDV l'occupazione inglese durò fino all'aprile 1920.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["Amministrazione britannica a Batum dopo Mudros", "9dd768fc"], "d": ["In forza dell'Armistizio di Mudros del 30 ottobre 1918 l'Impero ottomano fu costretto a ritirarsi da Batum; la città fu occupata il 24 dicembre 1918 dalle unità britanniche. Batum, resa nell'aprile 1918 centro di sanjak autonomo, da questa data fino al luglio 1920 rimase sotto controllo inglese.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Ardahan passa sotto dominio georgiano", "97cf47f6"], "d": ["Ardahan, evacuata dopo Mudros, fu occupata dalle forze georgiane il 20 aprile 1919, nei giorni in cui il Governo del Caucaso Sudoccidentale veniva sciolto dagli Inglesi. Il dominio georgiano sarebbe durato fino al 23 febbraio 1921.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Preston consegna l'amministrazione di Kars al governatore armeno", "efa81cb0"], "d": ["Il comandante inglese Preston, che il 12-13 aprile 1919 sciolse il Governo del Caucaso Sudoccidentale, il 30 aprile 1919 abolì il governo provvisorio dello şûrâ e cedette l'amministrazione della città all'armeno Karganov, fatto governatore di Kars; a Kars iniziò il periodo dell'amministrazione armena, che durò fino alla vittoria di Kâzım Karabekir del 30 ottobre 1920.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Congresso di Erzurum: decisione di resistenza nazionale delle province orientali", "41ef0457"], "d": ["Il congresso convocato dalla Società per la Difesa dei Diritti dell'Anatolia Orientale, dopo un rinvio per pressione inglese, fu aperto con cinquantasei delegati e alla presidenza fu eletto Mustafa Kemal Pascià, che si era dimesso dall'esercito. Il congresso dichiarò che entro i confini nazionali la patria è un tutto, che mandato e protettorato non possono essere accettati e che, in caso di dissoluzione del governo, la nazione avrebbe preso nelle proprie mani il proprio destino. Queste decisioni sei mesi dopo avrebbero costituito il nucleo del testo del Misâk-ı Millî.", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Congresso di Sivas: unione della resistenza nazionale sotto un unico tetto", "0e9ad36b"], "d": ["Il congresso, che iniziò i lavori il 4 settembre 1919 nel Sivas Sultânîsi, riunì le società per la difesa dei diritti di ogni parte del paese sotto il nome di Società per la Difesa dei Diritti dell'Anatolia e della Rumelia ed elesse un Heyet-i Temsîliyye (Comitato di Rappresentanza). La proposta di mandato americano fu respinta dopo lunghe discussioni. Con la dichiarazione pubblicata l'11 settembre la Lotta Nazionale divenne un movimento politico legittimo e a centro unico e iniziò una aperta lotta di potere con il governo di Istanbul.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Protocollo di Amasya: colloquio del governo di Istanbul con l'Heyet-i Temsîliyye", "40e6a6ab"], "d": ["Dopo la caduta di Damat Ferid e la formazione del governo di Ali Rızâ Pascià, il ministro della Marina Salih Pascià fu inviato ad Amasya per incontrare l'Heyet-i Temsîliyye. Con i protocolli raggiunti il governo di Istanbul riconobbe di fatto l'esistenza del movimento anatolico; furono accettati la convocazione del Meclis-i Meb'ûsan, la libertà delle elezioni e la salvaguardia dei confini nazionali. Fu il primo guadagno politico ufficiale ottenuto dalla Lotta Nazionale di fronte a Istanbul.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Adozione del Misâk-ı Millî nell'ultima Assemblea ottomana", "6322865e"], "d": ["Il testo dell'Ahd-i Millî, firmato da 121 deputati nell'ultimo Meclis-i Meb'ûsan ottomano, richiedeva l'integrità indivisibile dei territori rimasti entro la linea di Mudros e abitati da una maggioranza turco-musulmana, il plebiscito nelle province arabe e in Tracia occidentale, l'abolizione delle capitolazioni e la piena indipendenza politica e finanziaria. Il testo fu adottato all'unanimità il 17 febbraio 1920 e proclamato al mondo. Questa dichiarazione fu non solo il programma politico della Lotta Nazionale ma anche la mappa dei confini che sarebbero stati difesi a Losanna; fu la causa diretta dell'occupazione ufficiale di Istanbul da parte degli Stati dell'Intesa il 16 marzo.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["Al ritiro degli Inglesi Artvin resta alla Georgia", "6d086b06"], "d": ["Secondo la voce Artvin del TDV l'occupazione inglese durò fino all'aprile del 1920; ritirandosi gli Inglesi lasciarono la città alla Georgia. Artvin rimase in mano alla Georgia fino all'ultimatum della GANT del 23 febbraio 1921.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Batum ceduta all'amministrazione georgiana", "6523d095"], "d": ["La consegna ufficiale di Batum da parte degli Inglesi ai Georgiani avvenne il 7 luglio 1920 (la voce Batum del TDV dà soltanto 'luglio 1920'). Il governo di Ankara il 25 luglio protestò contro la cessione definendola 'occupazione'.", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Trattato di Gümrü: primo trattato internazionale del governo della GANT", "9232c690"], "d": ["Quando l'esercito del fronte orientale al comando di Kâzım Karabekir riprese Sarıkamış e Kars, l'Armenia chiese la pace e con il trattato firmato a Gümrü dichiarò di non riconoscere Sèvres e accettò di rinunciare alle rivendicazioni territoriali a oriente. Questo primo trattato firmato dal governo di Ankara fu il primo documento internazionale a respingere di fatto Sèvres e aprì alla GANT la via del riconoscimento giuridico. Il confine orientale fu così messo in sicurezza e divenne possibile spostare forze sul fronte occidentale.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["Prima battaglia di İnönü: prima vittoria dell'esercito regolare", "4add3719"], "d": ["Il nuovo esercito regolare costituito fermò sulle posizioni di İnönü le forze greche che avanzavano in direzione di Bursa e le costrinse a ritirarsi. Questo successo, di scala militare limitata, ebbe conseguenze politiche molto grandi: il governo di Ankara fu invitato alla Conferenza di Londra, si aprì la strada al Trattato di Mosca con la Russia sovietica e fu adottata la Legge di Teşkilât-ı Esâsiyye (Legge sull'Organizzazione Fondamentale). Anche la fiducia dell'opinione pubblica interna nell'esercito regolare si consolidò con questa vittoria.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["Seconda battaglia di İnönü: l'attacco greco spezzato per la seconda volta", "a974521c"], "d": ["L'esercito greco, che non aveva ottenuto risultati dalla Conferenza di Londra, passò a un nuovo attacco dalle direzioni di Bursa e Uşak, ma fu fermato di nuovo sulle alture di İnönü e dovette ritirarsi. Il telegramma inviato da Mustafa Kemal Pascià a İsmet Pascià, 'Voi lì non avete vinto soltanto il nemico, ma anche il destino avverso della nazione', fu scritto dopo questa vittoria. La battaglia innalzò il prestigio internazionale della Lotta Nazionale e accelerò il processo di ritiro dell'Italia dall'Anatolia.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Accordo di Ankara: pace con la Francia e chiusura del fronte meridionale", "35fc32db"], "d": ["Con l'accordo firmato ad Ankara con la Francia dopo la vittoria del Sakarya la guerra sul fronte meridionale ebbe fine; le forze francesi evacuarono la Çukurova e il Sud-Est, compresi Adana, Antep, Maraş e Urfa, ritirandosi sul confine siriano. Uno degli Stati dell'Intesa riconobbe così di fatto il governo di Ankara e si aprì la prima crepa sul fronte di Sèvres. Le armi rilevate dalle regioni evacuate e le unità rese libere ebbero un ruolo critico nella preparazione della Grande Offensiva.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Armistizio di Mudanya: cessione senza guerra di Istanbul e degli Stretti", "ac0d9baf"], "d": ["Dopo la Grande Offensiva, con l'esercito turco giunto a fronteggiare le forze inglesi a Çanakkale e a İzmit, la conferenza riunita a Mudanya si concluse con l'armistizio dopo undici giorni di aspre trattative. Fu accettato che la Tracia orientale fino alla Maritza fosse evacuata dalla Grecia entro quindici giorni e consegnata all'amministrazione turca e che Istanbul e gli Stretti fossero consegnati con il trattato di pace. Così la fase armata della Lotta Nazionale si chiuse con una vittoria diplomatica conseguita senza sparare un colpo e si aprì la porta di Losanna.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Partenza di Mehmed VI Vahdeddin da Istanbul ed elezione di Abdülmecid Efendi a califfo", "8ab0e847"], "d": ["Mehmed VI Vahdeddin, ultimo sultano, la cui posizione era divenuta controversa dopo l'abolizione del sultanato, il mattino di venerdì 17 novembre 1922 lasciò Istanbul con la corazzata inglese Malaya e si recò a Malta. La GANT due giorni dopo, il 19 novembre, elesse Abdülmecid Efendi come califfo privo di potere politico. Il governo dinastico ottomano di seicentoventitré anni terminò così di fatto; il califfato sarebbe continuato in forma simbolica per altri quindici mesi. Vahdeddin, passato a Malta e poi in Italia, si stabilì a Villa Nobel a Sanremo; non ottenne risultati dalle richieste fatte per essere accolto in un paese musulmano e morì lì il 16 maggio 1926, ribadendo di non aver mai rinunciato ai diritti di sultanato e califfato.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["Morte a Sanremo dell'ultimo sultano Mehmed VI Vahdeddin", "7149ed0e"], "d": ["L'ultimo sultano ottomano Mehmed Vahdeddin, stabilitosi nella città italiana di Sanremo dopo aver lasciato Istanbul, morì il 16 maggio 1926 senza aver saputo della riunione del congresso del califfato (13 maggio 1926), nel quale aveva dichiarato di non aver mai rinunciato ai diritti di sultanato e califfato. Era in gravi difficoltà finanziarie; doveva 60.000 lire ai commercianti di Sanremo e i creditori, saputa della morte, fecero apporre il sequestro ai mobili della sua casa.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["Conquista della zona di Bolu da parte di Konuralp — Mudurnu, Konurapa e Bolu", "e245cd27"], "d": ["Konuralp, uno dei comandanti di Orhan Gazi, rivolgendosi alla regione montuosa a est del Sakarya legò all'amministrazione ottomana la zona di Mudurnu, Konurapa e Bolu; la cittadina nella piana di Düzce fu detta con il suo nome. La data esatta della conquista non è nota; il racconto si basa sulla tradizione di Âşıkpaşazâde. La regione era allora un territorio di frontiera che passava di mano tra Candaridi e Bisanzio; la conquista avvicinò per la prima volta gli Ottomani alla costa occidentale del Mar Nero. Dopo la Battaglia di Ankara la zona sarebbe passata di nuovo ai Candaridi, ma sarebbe stata ripresa in modo definitivo al tempo di Maometto il Conquistatore.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["Presa dei centri bizantini a sud del Marmara — Mihaliç, Kirmasti, Gölyazı", "9c61b8d4"], "d": ["Dopo la presa di Nicea e Nicomedia, i centri rimasti in mano bizantina a ovest della piana di Bursa entrarono a uno a uno sotto amministrazione ottomana. Gölyazı attorno al lago di Uluabat, Kirmasti lungo il fiume Susurluk e Mihaliç completarono il corridoio che collegava la costa meridionale del Marmara ai territori di Karesi. Questi centri si arresero a lungo senza vedere un assedio, con l'isolamento dei dintorni; la presenza bizantina nella regione fu così ridotta al golfo di Gemlik.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Gördüs (Corinto) passa al Despotato di Morea", "392495eb"], "d": ["Corinto, feudo legato al principato d'Acaia della famiglia fiorentina Acciaiuoli dal 1358, nel 1395 passò in mano al despota bizantino di Morea Teodoro. La città da allora rimase sotto l'amministrazione del despotato fino alla conquista ottomana.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["Annessione del Beylicato degli Hacıemîroğulları — Ordu e Ünye", "c064f07f"], "d": ["Il beylicato turcomanno fondato da Bayram Bey intorno a Ordu e ampliato negli anni 1350 dal figlio Hacı Emîr era un piccolo ma strategico Stato costiero con centro nell'odierna Eskipazar: era l'unica area di dominio indipendente tra Samsun e Trebisonda. L'emiro Süleyman nel 1398, nella campagna di Canik di Yıldırım Bayezid, aveva dichiarato la propria fedeltà; dopo la Battaglia di Ankara il beylicato era tornato libero. Al tempo di Murad II, negli stessi anni della liquidazione dei Tâceddinoğulları, i territori del beylicato furono legati all'amministrazione ottomana diretta e la costa del Mar Nero da Samsun a Giresun fu riunita in una sola mano.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Conquista di Gördüs (Corinto)", "87a2bc59"], "d": ["Nella campagna di Morea di Maometto il Conquistatore la fortezza di Acrocorinto fu assediata per tre mesi e alla fine ricevuta in resa per via pacifica. L'istmo di Corinto, considerato la porta della Morea, passò così agli Ottomani.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["Annessione del Montenegro all'amministrazione ottomana — Cetinje", "7fdb7cc8"], "d": ["Quando la dinastia Crnojević, che governava Zeta, abbandonò il dominio nel 1496, la regione montuosa del Montenegro, retrovia di Scutari, fu posta sotto amministrazione ottomana diretta e fu organizzata dapprima come sanjak separato, poi come parte del sanjak di Scutari. Il monastero di Cetinje fu lasciato al suo posto come centro religioso della regione. Per la durezza della geografia l'amministrazione qui non funzionò mai in modo così stretto come nelle pianure; due secoli dopo il governo dei vladika nato dallo stesso monastero sarebbe stato il nucleo dell'indipendenza di fatto.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["La fortezza di Bayezid accetta il dominio ottomano nella Campagna dei Due Iraq", "f29e2e17"], "d": ["Quando il gran visir İbrahim Pascià, nella Campagna dei Due Iraq, giunse nei dintorni di Bingöl, insieme a molte tribù curde della regione le fortezze di Van, Toprakkale, Avnik e Bayezid accettarono di entrare sotto il dominio ottomano. Bayezid si era unita agli Ottomani nel 1514 nella campagna di Selim il Severo, ma al ritorno dell'esercito i Safavidi avevano ripreso la regione.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Tabriz passa di nuovo ai Safavidi — il ritorno dell'Irakeyn", "80b8b761"], "d": ["Nella Campagna dei Due Iraq l'esercito era entrato a Tabriz, ma, poiché l'obiettivo principale era Baghdad, in città non era stata lasciata una guarnigione stabile. Mentre l'esercito, che aveva passato l'inverno a Baghdad, tornava a ovest, lo shah Tahmasp rientrò nell'Azerbaigian evacuato e riprese Tabriz. Questo era lo schema ricorrente delle guerre ottomano-safavidi: Tabriz fu presa cinque volte e in tutte e cinque non poté essere tenuta; la città avrebbe avuto una guarnigione ottomana di lunga durata solo nel 1585.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["Van ed Erciş cadono nelle mani di Tahmasp (la posizione ottomana terminò nel 1534-35)", "cb93d561"], "d": ["Nella regione che aveva dato Van al dominio ottomano nel 1534, Ulama Pascià resistette nella fortezza di Van all'assedio safavide; la fortezza passò in mano safavide e anche le forze safavidi che assediavano Erciş si erano ritirate con l'aiuto ottomano. Quando Solimano il Legislatore giunse ad Ahlat (23 settembre 1535) Van era ormai in mano a Tahmasp. Van rimase safavide fino al 1548.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["Il sanjak di Bayezid passa sotto dominio safavide (Van ed Erciş erano già safavidi nel 1535)", "806a2cf1"], "d": ["Il sanjak di Bayezid, a metà del confine ottomano-safavide, passò di nuovo in mano iraniana (Kaya 2017 lo ricorda 'insieme a Van ed Erciş'; ma Van ed Erciş secondo Karataş 2025 e TDV erano tornate ai Safavidi il 22 settembre 1535 — cfr. voce precedente); in questo cambio di mano alcuni luoghi del sanjak furono devastati. Il sanjak cambiò di mano ripetutamente tra i due Stati fino all'ultimo quarto del XVI secolo.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["Il sanjak di Bayezid passa di nuovo agli Ottomani durante la Campagna di Nakhchivan", "cf0171fa"], "d": ["Durante la terza campagna d'Iran (Nakhchivan) di Solimano il Legislatore il sanjak di Bayezid fu posto di nuovo sotto amministrazione ottomana. Nella campagna del 1554 Bayazıt fu un'importante base per l'esercito; il sanjak entrò in modo definitivo sotto sovranità ottomana nel 1578.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["Perdita di Erevan a favore di Shah Abbas", "34413cf2"], "d": ["Quando, negli anni in cui le rivolte celâli bloccavano l'Anatolia, il fronte orientale rimase indifeso, Shah Abbas, che aveva riorganizzato il suo esercito all'europea, passò all'attacco. La fortezza di Erevan, fatta costruire da Ferhad Pascià nel 1583, dopo un assedio di sette mesi si arrese. Il primo anello della linea caucasica guadagnata con il Trattato di Ferhad Pascià si era spezzato e nei tre anni successivi tutto il Caucaso meridionale sarebbe andato perduto.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["Perdita di Tiflis e Ganja", "3fb51753"], "d": ["Dopo la caduta di Erevan l'esercito safavide avanzò lungo la valle del Kura; Ganja, centro del Karabakh, e Tiflis, capitale della Georgia, andarono perdute una dopo l'altra. L'Impero ottomano conduceva contemporaneamente sul fronte austriaco la lunga guerra di tredici anni e in Anatolia era alle prese con i Celâli; non c'erano forze da inviare a oriente. Così l'ordinamento delle ampie province caucasiche stabilito con il Trattato di Ferhad Pascià del 1590 ebbe fine di fatto.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["Perdita dello Shirvan — Shamakhi, Baku e Derbent", "81beab11"], "d": ["La provincia dello Shirvan sulla costa del Caspio, guadagnata con le campagne di Özdemiroğlu Osman Pascià del 1578-1585, aveva fornito alle finanze ottomane un reddito importante come principale fonte del commercio della seta. L'operazione di Shah Abbas verso nord, prendendo di seguito Shamakhi, Baku e Derbent, liquidò questa provincia. La perdita non fu solo territoriale: anche la via con cui la seta iraniana affluiva in Europa attraverso gli Ottomani uscì dal controllo e lo Stato safavide cominciò a commercializzare la seta attraverso l'Oceano Indiano.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["Perdita di Taiz", "65f20d53"], "d": ["Nel 1038 (1629) gli Ottomani abbandonarono Taiz insieme al dominio sullo Yemen, lasciato all'amministrazione qasimide di Sana'a — il primo grande passo del processo con cui gli imam zaiditi ripresero l'interno dello Yemen.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["Perdita dello Yemen — dominio degli imam qasimidi", "49e83e3c"], "d": ["Lo Yemen era provincia ottomana dal 1538; ma la resistenza degli imam zaiditi non cessò mai. La rivolta avviata dall'imam Qasim si estese a tutto il paese al tempo del figlio al-Mu'ayyad Muhammad e le guarnigioni ottomane furono assediate una dopo l'altra. Negli anni in cui Murad IV era concentrato su Baghdad ed Erevan non si poterono inviare rinforzi; Taiz era andata perduta nel 1629, mentre Mocha era stata evacuata nell'ultima fase dello stesso crollo, il 22 ottobre 1635. Nel 1635 anche le ultime unità a Sana'a e Zabid evacuarono lo Yemen. Così la costa orientale del Mar Rosso rimase fuori dall'Impero per duecentotrentasette anni, poté essere ripresa solo nel 1872. Lahej (al-Hawta), secondo il TDV İslâm Ansiklopedisi, fu in mano agli Ottomani fino al 1635; da quella data ebbero influenza gli imam zaiditi.", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["Evacuazione di Mocha", "c6b3061a"], "d": ["Mustafa Bey il 10 Cemâziyelevvel 1045 (22 ottobre 1635) evacuò Mocha con le forze e le armi rimaste; poi Hasan b. Qasim, figlio dell'imam Qasim, nominando propri uomini a Zabid e Mocha, stabilì il controllo qasimide anche sulla costa della Tihama.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["Perdita di al-Hasa a favore dell'Emirato dei Banu Khalid", "a9b6131a"], "d": ["Al-Hasa era una provincia istituita nel 1550 per chiudere al Portogallo la costa occidentale del Golfo di Bassora; ma era lontanissima da Istanbul, all'estremità di un'unica via del deserto. Negli anni in cui l'assedio di Creta esauriva le risorse, la tribù dei Banu Khalid della regione, guidata da Barrak b. Ghurayr, cacciò la guarnigione ottomana e fondò un proprio emirato. La costa occidentale del Golfo rimase per un secolo e mezzo negli emirati tribali; nel 1795 sarebbe passata ai Sauditi, nel 1871 di nuovo agli Ottomani.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["Perdita di Prevesa e Vonitsa a favore di Venezia — apertura della costa dell'Epiro", "1201204c"], "d": ["Venezia, entrata nella Lega Santa, prima di iniziare la campagna di Morea prese le due fortezze che tengono l'imboccatura del golfo di Arta: Prevesa e, sulla riva opposta, Vonitsa. Nella stessa estate era caduta anche Ayamavra (Leucade). Queste tre posizioni permisero di introdurre in sicurezza la flotta dal Mar Ionio nell'interno della Grecia e divennero la base della campagna di Morea che sarebbe iniziata l'anno seguente. Prevesa e Vonitsa furono lasciate a Venezia anche a Passarowitz; sarebbero tornate sotto amministrazione ottomana solo nel 1798.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["Perdita di Szolnok — dissoluzione della linea del Tibisco", "51c2c8ef"], "d": ["Dopo la caduta di Uyvar in agosto l'esercito asburgico si volse a sud e prese Szolnok, testa di ponte sul fiume Tibisco. La città era l'unico passaggio sicuro tra Buda e la Transilvania; la sua perdita significava la separazione tra loro delle fortezze ottomane nella metà orientale dell'Ungheria. Fu determinante, l'anno seguente, nell'assedio di Buda, il fatto che la via dei rifornimenti fosse tagliata.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["Perdita di Modone a favore di Venezia", "114c9cc0"], "d": ["Modone, all'estremità sudoccidentale della Morea, era il porto che Venezia aveva perduto tre secoli prima e che chiamava 'uno dei due occhi dello Stato'. La fortezza, assediata dopo la caduta di Corone, fu battuta contemporaneamente da terra e da mare e ricevuta in resa. La campagna di Morea di Morosini prese così tutta la costa occidentale della penisola e si aprì la via verso l'interno.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["Perdita di Peçuy", "99d54cf4"], "d": ["Dopo la caduta di Buda a settembre le forze asburgiche scesero a sud, a ovest del Danubio, e presero Peçuy, ottomana dal tempo di Solimano il Legislatore. La città, ricordata con la moschea di Gazi Kâsım Pascià, era uno dei centri di sanjak più sviluppati dell'eyalet di Buda. La sua perdita significava l'apertura della via che scende nella piana di Mohács; l'anno seguente la Seconda disfatta di Mohács si sarebbe verificata proprio qui.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["Perdita di Seghedino", "9fbee1b2"], "d": ["Seghedino, alla confluenza dei fiumi Tibisco e Maros, era la porta meridionale della pianura ungherese e teneva la via per l'eyalet di Timișoara. La fortezza, assediata dopo la caduta di Buda e Peçuy nello stesso autunno, si arrese in breve tempo. La perdita di tre fortezze in una stagione fu il segno che la struttura amministrativa ottomana in Ungheria, stabilita dal 1541, cominciava a crollare. L'atlante considera nello stesso giorno passata dagli Ottomani agli Asburgo anche Zenta sul Tibisco (il giorno di resa specifico di Zenta non è stato letto nella fonte, il giorno è preso da Seghedino; TDV zenta: dall'ottobre 1686 iniziarono scontri tra gli Ottomani e gli alleati guidati dagli Asburgo — beyanlı yaklaşıklık).", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["Perdita di Balyabadra (Patrasso) — la porta settentrionale della Morea", "b9cff63c"], "d": ["Balyabadra, all'imboccatura del golfo di Corinto, era il porto che controllava il passaggio tra Morea e Rumelia. Dopo che l'esercito veneziano ebbe preso la città, caddero una dopo l'altra anche le fortezze sulle due rive del golfo e la penisola fu completamente isolata da terra. Alla fine di questa campagna tutta la Morea passò a Venezia; la regione fu governata fino al 1715 con il nome di 'Regno di Morea'.", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Gördüs (Corinto) lasciata a Venezia", "9a25b6b9"], "d": ["Dopo la caduta di Balyabadra Corinto fu lasciata ai Veneziani per via pacifica e la popolazione musulmana abbandonò la città. Nell'agosto 1687 l'esercito di Morosini si raccoglieva a Corinto per la campagna di Atene.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["Perdita di Eger", "983391aa"], "d": ["Eger era stata presa nel 1596 con la campagna a cui partecipò personalmente Mehmed III ed era divenuta centro di un eyalet con il proprio nome. Questa ultima grande fortezza ottomana dell'Ungheria settentrionale, completamente assediata dopo la Seconda disfatta di Mohács, resistette un anno e si arrese per la fame. Con la sua perdita il fianco settentrionale dell'Impero ottomano in Ungheria fu interamente liquidato.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["Perdita di İstolni Belgrad (Székesfehérvár) — la città dell'incoronazione dei re ungheresi", "c6147255"], "d": ["La città in cui per secoli furono incoronati e sepolti i re ungheresi era stata presa nel 1543 da Solimano il Legislatore ed era divenuta uno dei più importanti centri di sanjak dell'eyalet di Buda. Circa due anni dopo la caduta di Buda la fortezza, completamente isolata, si arrese. Con questa perdita la presenza ottomana a ovest del Danubio fu ridotta ai dintorni di Sirmio e Osijek.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["Perdita di Szigetvár", "834910a7"], "d": ["Szigetvár era la fortezza in cui Solimano il Legislatore morì nel 1566, durante l'assedio, nella tredicesima e ultima campagna; per questo aveva un posto simbolico nella memoria ottomana. Centoventitré anni dopo, caduta ogni fortezza circostante, si arrese anche la fortezza protetta dalle paludi. Il mausoleo in cui erano sepolte le viscere di Solimano e la cittadina circostante furono distrutti dopo il passaggio all'amministrazione asburgica. Aynı tarihte atlasta Osmanlı'dan Habsburg'a geçen diğer yerleşim: Barcs — Zigetvar'ın abi-merkez zincirini izler (Bánlaky 0017/1449; beyanlı yaklaşıklık).", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["Perdita di Varad", "6cce360d"], "d": ["Varad era la fortezza chiave verso la Transilvania presa nel 1660 da Köprülü Mehmed Pascià e fatta centro di un eyalet con il proprio nome. Rimasta del tutto sola dopo la disfatta di Slankamen, la fortezza, dopo un blocco durato quasi due anni, si arrese per la fame. Con la sua perdita l'influenza ottomana sulla Transilvania ebbe fine di fatto e il dominio asburgico si stabilì a est del Tibisco.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["Perdita di Yanova — chiusura della via di Transilvania", "4b5e30d8"], "d": ["Yanova era una fortezza presa nel 1658 che teneva il collegamento tra Varad e Timișoara. Subito dopo la caduta di Varad, isolata, andò perduta anch'essa. Così l'eyalet di Timișoara fu completamente isolato da nord e fino a Karlowitz continuò a esistere come unico territorio ungherese rimasto in mano ottomana.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["Istituzione del governo dei vladika in Montenegro — distacco di fatto di Cetinje", "a924b778"], "d": ["Negli anni in cui la Guerra della Lega Santa allentava il controllo ottomano nei Balcani, il metropolitato a capo del monastero di Cetinje divenne una carica trasmessa di padre in figlio nella famiglia Petrović e la regione acquisì di fatto un'amministrazione separata. Grazie all'inaccessibilità dei monti questo vladikato per due secoli continuò a esistere in una condizione né pienamente indipendente né pienamente legata; la sua indipendenza giuridica sarebbe stata riconosciuta solo con il Trattato di Berlino del 1878.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Ripresa di Gördüs (Corinto)", "26f53e3a"], "d": ["La prima grande tappa della campagna di Morea di Damad Ali Pascià fu Corinto; gli Ottomani nel giugno 1715 ripresero la città ai Veneziani e da qui avanzarono verso il resto della penisola.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Offensiva di Nadir: perdita di Tabriz, Nakhchivan, Hamadan, Kermanshah, Marāgheh e Qasr-i Şîrîn", "d95efd59"], "d": ["Le città dell'Iran occidentale prese tra il 1723 e il 1727 approfittando del crollo dello Stato safavide andarono perdute una a una con l'offensiva di Nadir Khan, che aveva preso il potere di fatto in Iran. In Azerbaigian anche Ardabil e Khalkhal passarono a Nadir. La perdita di Hamadan, Kermanshah e Qasr-i Şîrîn ebbe grande eco a Istanbul; il fatto che l'esercito non partisse in campagna ma attendesse a Üsküdar e che si cercasse di occultare la perdita fu una delle cause dirette della Rivolta di Patrona Halil scoppiata sei settimane dopo. L'atlante considera passata in questo giorno dagli Ottomani ai Safavidi anche Kotur, che segue la catena di Hoy (Uluerler 2015, Turkish Studies 10/5, p. 6; Kotur'a özgü gün kaynakta yok — beyanlı yaklaşıklık).", "412bd324"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["Disfatta di Baghavard (Arpaçay) — perdita del Caucaso a favore di Nadir Khan", "4262f54c"], "d": ["Le province caucasiche prese nel 1723-1725 approfittando del crollo dello Stato safavide poterono essere tenute dieci anni. Nadir Khan, che aveva preso il potere di fatto in Iran, inflisse una grave sconfitta all'esercito ottomano a Baghavard, presso Erevan; il serdar Abdullah Köprülü Pascià perse la vita sul campo di battaglia. Dopo la disfatta Erevan, Tiflis, Ganja e lo Shirvan furono evacuate nel giro di mesi. Il confine orientale tornò alla linea di Qasr-i Şîrîn del 1639, come sarebbe stato confermato nel 1746.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["Perdita di Bender a favore dei Russi", "0daca453"], "d": ["Dopo la disfatta della piana di Kartal l'esercito ottomano si era ritirato a sud del Danubio e le fortezze tra Moldavia e Özi erano rimaste sole. Bender, che teneva il punto di passaggio del fiume Turla, fu presa d'assalto dopo un assedio di due mesi; la città fu saccheggiata. La perdita della fortezza spezzò l'anello centrale della linea di difesa del Mar Nero settentrionale, dopo di che caddero anche Akkerman e Kilia. A Küçük Kaynarca Bender sarebbe stata restituita, ma nel 1806 sarebbe stata perduta di nuovo.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["L'emirato Sabah del Kuwait entra sotto la protezione ottomana", "3584dba0"], "d": ["Secondo la voce Kuwait del TDV lo scalo era stato fondato all'inizio del XVIII secolo dalla tribù degli Utub provenienti dal Najd e la famiglia Sabah aveva preso l'amministrazione verso la fine del secolo. Negli stessi anni in cui al-Hasa passava ai Sauditi, l'emirato, che di fronte alla pressione wahhabita non aveva altra scelta che appoggiarsi a Bassora, entrò sotto la protezione ottomana. Il legame sarebbe stato formalizzato nel 1871 con il riordino di Bassora di Midhat Pascià e il Kuwait sarebbe stato considerato uno dei tre kaza del sanjak di Bassora; anche la successiva rivendicazione territoriale dell'Iraq si basa su questa registrazione.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["Perdita della Mecca a favore dei wahhabiti", "2da23acd"], "d": ["Il movimento wahhabita, nato nel Najd, si volse all'Hijaz al tempo di Saud b. Abd al-Aziz; dopo Ta'if e Medina anche la Mecca fu ricevuta in resa per la seconda volta — l'emiro della Mecca sharif Ghalib consegnò la città ai wahhabiti a condizione di restare nell'emirato. I mausolei furono abbattuti e la via delle carovane di pellegrini da Damasco e dal Cairo fu tagliata; anche il surre che il sultano inviava ogni anno ai Haramayn fu interrotto in questi anni — l'unica eccezione a questa assegnazione ininterrotta fino al 1915 è il periodo del dominio wahhabita. Poiché il titolo di protettore dei Haramayn era uno dei pilastri fondamentali della legittimità del sultano, questa perdita fu, oltre che territoriale, un grave colpo politico; la ripresa sarebbe durata sette anni e sarebbe stata possibile con l'esercito di Mehmed Ali Pascià di Kavala.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Fine della Repubblica di Ragusa (Dubrovnik) — occupazione francese", "f8e27bf1"], "d": ["I Francesi, stabilitisi sulla costa dalmata con il Trattato di Campoformio (1797), il 27 maggio 1806 presero Dubrovnik e posero fine alla piccola repubblica mercantile. Così terminò lo status di dipendenza di tre secoli e mezzo di Dubrovnik, che dal 1458 pagava tributo agli Ottomani preservando l'autonomia e i privilegi commerciali; la città e l'isola di Mljet della repubblica sulla mappa passano direttamente all'amministrazione francese.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Perdita di Sukhum a favore dei Russi — apertura della costa orientale del Mar Nero", "adc96bd4"], "d": ["Nella guerra ottomano-russa del 1806-1812 la flotta russa si volse alla costa orientale del Mar Nero e prese Sohumkale, su cui poggiava il dominio ottomano in Abcasia. La fortezza era il centro del collegamento con le tribù caucasiche e del commercio costiero. Con la sua perdita la Russia si stabilì per la prima volta in modo permanente sulla costa orientale del Mar Nero; l'influenza ottomana nel Caucaso fu ridotta alle zone di Anapa e Poti.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Parga lasciata all'amministrazione ottomana", "66e0cc5d"], "d": ["Parga era in mano a Venezia dal 1401 e non era mai entrata sotto amministrazione ottomana; dopo la caduta di Venezia passò in successione alla Francia e all'Inghilterra. La voce Tepedelenli Ali Paşa del TDV riassume la situazione così: la città si arrese agli Inglesi e fu ceduta all'amministrazione di Ali Pascià solo nel 1819. La cessione si concluse con l'emigrazione di gran parte della popolazione nelle isole Ionie. Così anche l'ultimo del trio Prevesa-Parga-Vonitsa, lasciato a Venezia a Passarowitz, fu aggregato all'Impero; Parga sarebbe rimasta ottomana per novantaquattro anni.", "555a1119"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Gördüs (Corinto) passa ai ribelli greci", "892dcdc6"], "d": ["Durante la guerra d'indipendenza greca Acrocorinto passò in mano ai ribelli e il comandante della fortezza Kâmil Bey fu fatto prigioniero.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Perdita di Anabolu (Nauplia) a favore dei ribelli", "1a67fa50"], "d": ["Anabolu, porto con la fortificazione più forte della Morea, si arrese per la fame dopo un blocco di oltre un anno. La fortezza era dall'inizio della rivolta l'ultimo grande appoggio del controllo ottomano nella penisola; con la sua perdita tutta la Morea passò in mano ai ribelli. La città sarebbe divenuta poco dopo la prima capitale del nuovo Stato greco.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-01:0":{"b": ["Passaggio di Lepanto (İnebahtı) all'amministrazione greca", "c9d19d4b"], "d": ["Lepanto, sulla costa settentrionale del golfo di Corinto, rimasta in mano ottomana fino alla rivolta greca, andò perduta nell'aprile 1829 ed entrò sotto amministrazione greca; il nome della cittadina fu cambiato nell'antico Naupatto (Nafpaktos). La popolazione musulmana ed ebraica della città scomparve del tutto e questa si trasformò in una piccola cittadina.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Occupazione francese di Algeri — fine dell'ocak di trecento anni", "0be8f568"], "d": ["Con il pretesto dell'episodio del ventaglio nato da una controversia su un credito, la Francia tenne per tre anni sotto blocco la costa algerina, poi sbarcò truppe a Sidi Ferruch. Al termine di un'operazione di tre settimane Hüseyin Dey si arrese e l'Ocak ottomano di Algeri, in vita dal 1516, ebbe fine. L'occupazione non rimase limitata alla capitale; anche Tlemcen, Cherchell e Medea nell'interno andarono perdute nella stessa estate. L'ingresso dell'intera costa sotto controllo francese avrebbe richiesto altri ventiquattro anni.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Cessione di Negroponte (Eğriboz) alla Grecia — con l'isola (Caristo, Oreoi)", "7b524aa4"], "d": ["Negroponte, teatro di intensi combattimenti durante la guerra d'indipendenza greca ma rimasta in mano ottomana, fu data ai Greci nel 1831 dopo l'entrata in vigore del trattato di pace. La popolazione musulmana della città, importante base navale dal 1470, vendendo tutti i beni a prezzi bassissimi emigrò in massa in territorio ottomano; la città rimase a lungo vuota e il viaggiatore tedesco Fallmerayer nel 1842 la definì una città fantasma.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Occupazione francese di Orano (Vehrân)", "a8415d66"], "d": ["Orano, ceduta senza guerra dalla Spagna nel 1792, era il più grande porto dell'Algeria occidentale. Sei mesi dopo la caduta della capitale le truppe francesi entrarono in città. L'operazione verso ovest partita da qui si sarebbe presto scontrata con la resistenza quindicennale dell'emiro Abd al-Qadir.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Occupazione di Annaba (Bona)", "21f37fb1"], "d": ["Annaba, porto dell'Algeria orientale vicino al confine tunisino, fu presa dalle forze francesi e fatta base della marcia su Costantina. La città era anche il porto africano più vicino di fronte all'isola di Sardegna.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["Cessione di Atene al nuovo Stato greco (giorno in cui le unità bavaresi presero in consegna l'Acropoli)", "deee4d37"], "d": ["Atene, ottomana dal 1456, durante la guerra d'indipendenza greca era passata di mano più volte e la guarnigione sull'Acropoli era tornata sotto controllo ottomano nel 1827. Poiché si trovava a nord del confine tracciato dal Protocollo di Londra, la città fu ceduta al nuovo regno e la guarnigione evacuò l'Acropoli. Il giorno dell'atlante è quello in cui le unità bavaresi presero in consegna l'Acropoli; l'uscita di fatto della guarnigione ottomana avvenne alcuni giorni dopo (St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, cap. 13; Finlay, Journals and Letters, vol. I, p. 67). L'anno seguente Atene fu proclamata capitale della Grecia al posto di Anabolu.", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Occupazione di Bugia (Bicâye)", "a8927e00"], "d": ["Il porto di Bugia, dove le montagne della Cabilia si aprono sul mare, era l'ultimo anello indipendente della linea costiera tra Algeri e Annaba. Fu preso con il sostegno dell'artiglieria navale; ma l'interno montuoso alle sue spalle non sarebbe entrato sotto controllo francese per altri trent'anni. Queste occupazioni lungo la costa costituiscono lo sciogliersi anno per anno sulla mappa dell'Algeria ottomana.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Occupazione di Sétif", "2073731a"], "d": ["Dopo la caduta di Costantina un anno prima, le forze francesi salirono sull'altopiano e, prendendo l'antica città romana di Sétif, vi stabilirono una guarnigione permanente. Sétif era il punto di incrocio delle vie carovaniere tra la costa e il Sahara; la sua occupazione mostrò che la Francia cominciava a controllare non più solo i porti ma anche la rete commerciale interna.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Occupazione di Biskra — perdita della porta del Sahara", "d895cad0"], "d": ["Biskra era, ai piedi meridionali dei monti dell'Atlante, la porta che si apre sul Sahara e il centro delle oasi di palme da dattero. Con la sua presa negli anni in cui la resistenza dell'emiro Abd al-Qadir cominciava a spezzarsi, il controllo francese raggiunse per la prima volta la sponda settentrionale del deserto. Da allora in poi sarebbe stata una campagna del deserto che avanzava oasi per oasi.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Occupazione di Touggourt — perdita dell'intera Algeria", "33c056e2"], "d": ["Con la presa di Touggourt, città-oasi a nord del Sahara, l'occupazione iniziata nel 1830 si completò nella metà settentrionale dell'odierna Algeria. L'Impero ottomano in questi anni combatteva nella Guerra di Crimea sullo stesso fronte della Francia; pur senza aver mai rinunciato ufficialmente alla propria pretesa giuridica sull'Algeria, di fatto non poté compiere un solo passo. L'unico territorio rimasto in Nordafrica era la Tripolitania.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["Caduta di El Obeid — il Kordofan passa alle forze del Mahdi", "58299f62"], "d": ["Il movimento avviato da Muhammad Ahmad, che si proclamò mahdi, si diffuse rapidamente contro l'amministrazione egiziana del Sudan. El Obeid, centro del Kordofan, cadde dopo un assedio di quattro mesi e divenne capitale della rivolta; il tesoro e i depositi d'armi della città permisero al movimento di organizzarsi in esercito. Il Sudan era giuridicamente ancora territorio del khedivato d'Egitto legato agli Ottomani, dunque la perdita cade sulla mappa dal corpo dell'Impero.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Caduta di Khartum — perdita dell'intero Sudan", "d4b98464"], "d": ["Dopo un assedio di dieci mesi le forze del Mahdi entrarono a Khartum, al punto di confluenza tra Nilo Azzurro e Nilo Bianco; il governatore della città, Gordon, fu ucciso e la colonna britannica inviata in soccorso arrivò con due giorni di ritardo. Da questa data l'intero Sudan, compresi Sennar, Dongola e Kordofan, rimase per quattordici anni sotto l'amministrazione dello Stato del Mahdi. La regione sarebbe entrata solo nel 1899 nell'amministrazione congiunta anglo-egiziana, con il legame ottomano completamente reciso.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Occupazione italiana di Massaua — perdita della costa occidentale del Mar Rosso", "c333b95b"], "d": ["Il porto di Massaua, centro dell'eyalet di Abissinia, fu occupato dall'Italia, che approfittava della confusione in cui la rivolta del Mahdi aveva immerso il Sudan; ciò costituì il nucleo dell'Eritrea italiana. Anche Suakin a nord e l'arcipelago di Dahlak al largo andarono perduti nello stesso processo. Così ebbe fine il dominio ottomano sulla costa occidentale del Mar Rosso, in vigore dal tempo di Selim il Severo, e il mare divenne ormai acqua straniera su entrambe le sponde.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Occupazione italiana di Rodi", "e08662c5"], "d": ["Nella Guerra di Tripolitania l'Italia, che voleva far sedere al tavolo l'Impero ottomano, portando la guerra nel Mediterraneo sbarcò truppe a Rodi. L'isola fu presa in pochi giorni. Rodi, che Solimano il Legislatore aveva preso nel 1522 con un lungo assedio e che era rimasta in mano ottomana per trecentonovant'anni, cessò così di essere la maggiore base insulare dell'Impero nel Mediterraneo orientale; pur considerata occupazione temporanea nel Trattato di Ouchy, non poté più essere ripresa.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Occupazione italiana del Dodecaneso", "200aacf2"], "d": ["Entro una settimana dalla presa di Rodi la flotta italiana occupò anche le isole circostanti; in seguito questo arcipelago sarebbe stato chiamato 'Dodecaneso'. La maggior parte delle isole era a poche miglia dalla costa anatolica e controllava il passaggio sudorientale dell'Egeo. L'occupazione fu considerata temporanea nel Trattato di Ouchy in cambio della cessione della Tripolitania, ma l'Italia non evacuò mai le isole; sarebbero state cedute alla Grecia nel 1947.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Occupazione di Coo", "ab246c62"], "d": ["Coo, ultimo anello dell'operazione del Dodecaneso, era un'isola fertile e popolosa proprio di fronte alla penisola di Bodrum. Con l'occupazione tutte le isole nell'angolo sudorientale dell'Egeo passarono sotto controllo italiano e la costa sudoccidentale dell'Anatolia fu circondata da un capo all'altro da una catena di isole straniere.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Dichiarazione d'indipendenza di Nikarya", "c4452033"], "d": ["Sulla piccola isola di Nikarya, tra Samo e Chio, la popolazione, nel clima di incertezza creato dalle occupazioni italiane, si sollevò, cacciò dall'isola la gendarmeria ottomana e proclamò uno 'Stato libero' durato cinque mesi con propria bandiera, francobolli e assemblea. Nel novembre 1912 l'isola si unì alla Grecia. Nonostante le dimensioni ridotte, questo episodio è un chiaro indicatore di come si stesse dissolvendo l'amministrazione centrale nell'Egeo.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Uscita di Samo dall'amministrazione ottomana", "3a862f2b"], "d": ["Samo era un principato autonomo dal 1832, tributario degli Ottomani e governato da un bey nominato da Istanbul. Nel vuoto creato dalla Guerra di Tripolitania il movimento unionista sull'isola prese l'amministrazione e l'ordinamento del principato autonomo cessò di fatto; l'isola nello stesso anno dichiarò l'unione alla Grecia. Quest'isola, a due chilometri dalla costa anatolica, fu uno dei primi territori perduti nell'Egeo.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Caduta di Ioannina — perdita dell'Epiro e di Parga", "d42fce18"], "d": ["Ioannina, assediata per cinque mesi nella Guerra balcanica, si arrese dopo la caduta delle posizioni di Bizani; con la città tutto l'Epiro passò alla Grecia. Anche Parga, dipendente dal sanjak di Ioannina, andò perduta a questa data e l'amministrazione ottomana di novantaquattro anni ebbe fine. La perdita di Ioannina significava la chiusura dell'ultima finestra dell'Impero sull'Adriatico.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Caduta di Edirne ai Bulgari", "459d2e56"], "d": ["Dopo un assedio di cinque mesi e mezzo, esaurite munizioni e viveri, Edirne si arrese; Şükrü Pascià fu fatto prigioniero. La caduta della città, ottomana dal 1361 e capitale per novantadue anni, fu considerata il colpo più grave della Guerra balcanica. Edirne sarebbe stata ripresa quattro mesi dopo, approfittando del crollo della Bulgaria sugli altri fronti nella Seconda guerra balcanica.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Perdita di Yanbu a favore delle forze di Sharif Husayn", "e291c816"], "d": ["La rivolta avviata a giugno da Sharif Husayn si estese alla costa del Mar Rosso; Yanbu, porto di Medina, con il sostegno della flotta inglese passò in mano ai ribelli. Il porto divenne la principale porta del flusso di armi e denaro che giungeva dall'esterno alla rivolta. Così il collegamento con il mare delle forze di Fahreddin Pascià a Medina fu tagliato e la città rimase sola all'estremità della ferrovia dell'Hijaz.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["Terza battaglia di Gaza — perdita di Gaza e Khan Yunis", "c142a069"], "d": ["Dopo due tentativi falliti Allenby nel suo terzo attacco sfondò il fronte aggirando da Beersheba e la linea di Gaza, tenuta per sei mesi, crollò. Gaza e Khan Yunis, a sud, furono evacuate lo stesso giorno. Questo sfondamento fu l'inizio della dissoluzione del fronte di Palestina; Gerusalemme sarebbe caduta cinque settimane dopo.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Occupazione di Komotini (Gümülcine) — perdita della Tracia occidentale", "904d813c"], "d": ["La Tracia occidentale, passata dopo Mudros sotto il controllo delle forze dell'Intesa, fu lasciata alla Grecia con la decisione della conferenza di San Remo e l'esercito greco entrò a Komotini. La regione, ripresa alla Bulgaria nel 1913, fu l'ultimo territorio perduto dall'Impero in Rumelia. Lo status della popolazione turca della regione sarebbe stato regolato tre anni dopo a Losanna con il regime delle minoranze. Con questa occupazione i kaza di Komotini, Xanthi, Dedeağaç e Sofulu della Tracia occidentale passarono alla Grecia.", "ef0aeba3"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["Dissoluzione dello Stato Ilkhanide: morte di Abu Sa'id Bahadur Khan", "0f187469"], "d": ["Secondo la voce İlhanlılar del TDV İslâm Ansiklopedisi la morte di Abu Sa'id senza lasciare eredi provocò lo smembramento dello Stato Ilkhanide, che dominava l'Iran da un secolo; gli emiri, approfittando delle lotte per il trono, fondarono dinastie locali come Jalayiridi, Qara Qoyunlu, Muzaffaridi, Sarbadaridi del Khorasan ed Eretnidi. Questa dissoluzione divise la regione in un mosaico di beylicati destinato a durare un secolo; alla fine si sarebbe riunificata con le campagne di Tamerlano.", "ebf54b53"]},
"OLAYLAR_EK7:1387-11-01:0":{"b": ["Tamerlano pone sotto il proprio dominio gran parte dell'Iran", "1cee2b82"], "d": ["Secondo la voce Timur del TDV İslâm Ansiklopedisi, Tamerlano, che dall'inizio degli anni 1380 liquidò una per una le dinastie locali post-ilkhanidi come Sarbadaridi, Kert e Muzaffaridi, durante la 'campagna dei tre anni' del 1386-1388 pose di fatto sotto il proprio dominio gran parte dell'Iran; la fine definitiva della dinastia muzaffaride sarebbe stata data nel 1393. La regione fu così legata di nuovo a un'unica autorità centrale dopo un secolo di frammentazione.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["Vittoria dell'Aras: Qara Yusuf sconfigge il timuride Abu Bakr Mirza", "4b61a75a"], "d": ["Qara Yusuf, bey dei Qara Qoyunlu tornato dall'esilio dopo la morte di Tamerlano nel 1405, dopo aver preso Avnik e riottenuto i propri territori nell'Anatolia orientale marciò contro Abu Bakr Mirza, nipote di Tamerlano e considerato signore di Azerbaigian e dei due Iraq, e lo sconfisse sulla riva dell'Aras. Questa vittoria non diede Tabriz ai Qara Qoyunlu: il TDV `tebriz` scrive che nel 1408 la città era in mano ad Abu Bakr Mirza; la battaglia che diede l'Azerbaigian è quella di Sardrud del 13 aprile 1408.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["Vittoria di Sardrud: Tabriz e l'Azerbaigian passano ai Qara Qoyunlu", "1f0a429d"], "d": ["Qara Yusuf sconfisse il timuride Abu Bakr Mirza per la seconda volta, dopo l'Aras, a Sardrud, presso Tabriz; questa vittoria diede l'Azerbaigian ai Qara Qoyunlu. Qara Yusuf incaricò poi Bistam Bey della conquista dell'Iraq persiano;", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Epidemia di peste a Istanbul e trasferimento del palazzo a Edirne", "70c7a163"], "d": ["Secondo la voce Istanbul del TDV İslâm Ansiklopedisi, il rapido e intenso popolamento della città preparò di tanto in tanto il terreno alla diffusione di malattie epidemiche; durante l'epidemia di peste del 1466 il palazzo e i dignitari dello Stato si ritirarono temporaneamente a Edirne. La popolazione della città subì perdite gravi in simili epidemie.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["Uzun Hasan pone fine allo Stato Qara Qoyunlu", "ef68399e"], "d": ["Secondo la voce Uzun Hasan del TDV İslâm Ansiklopedisi, il sovrano Aq Qoyunlu Uzun Hasan sconfisse e uccise il sovrano Qara Qoyunlu Jahan Shah nella zona di Bingöl-Sancak il 12 Rebîülâhir 872 / 10 novembre 1467; il figlio di Jahan Shah, Hasan Ali, fu sconfitto a Merend nel settembre 1468 e ucciso davanti a Hamadan nell'aprile-maggio 1469, e lo Stato Qara Qoyunlu fu definitivamente abolito. I territori passarono sotto il dominio Aq Qoyunlu; lo Stato si sarebbe esteso nel decennio successivo fino all'interno dell'Iran.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Apertura all'insegnamento delle madrase Sahn-ı Semân", "021f2a83"], "d": ["Secondo la voce Sahn-ı Semân del TDV İslâm Ansiklopedisi queste otto madrase, fondate nell'ambito del Complesso di Fatih, furono concepite come l'istituzione di insegnamento di livello più alto dell'epoca e costituirono il vertice della gerarchia ottomana dell'ilmiye. L'insegnamento qui e il diploma furono considerati nei secoli successivi il gradino più prestigioso nella carriera di kadı e müderris.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Completamento del Palazzo di Topkapı (Saray-ı Cedîd)", "d2db6323"], "d": ["Secondo la voce Topkapı Sarayı del TDV İslâm Ansiklopedisi le fonti dell'epoca divergono sulle date di inizio e fine dei lavori; secondo la data 883 (1478) dell'iscrizione della Bâb-ı Hümâyun, la costruzione, iniziata probabilmente nel 1465 per ordine di Maometto il Conquistatore, era in gran parte completata entro quest'anno e il palazzo sostituì il centro dello Stato nel vecchio palazzo. Così il sultano si trasferì nella nuova residenza che per tre secoli sarebbe stata il cuore amministrativo e cerimoniale dello Stato.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Ascesa al trono di Bayezid II a Istanbul", "9b686d04"], "d": ["Secondo la voce Bayezid II del TDV İslâm Ansiklopedisi, lo şehzade Bayezid, sanjak-bey di Amasya, alla notizia della morte del padre giunse rapidamente a Istanbul e salì al trono; con il sostegno dei giannizzeri superò il fratello Cem partito da Konya. Durante l'ascesa ai giannizzeri fu distribuito il consueto dono di ascesa (cülûs bahşişi). Questo cambio sul trono accese anche la miccia della lotta tra i due fratelli.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Cem Sultan si proclama sultano a Bursa", "b355168a"], "d": ["Secondo la voce Cem Sultan del TDV İslâm Ansiklopedisi, Cem, giunto a Bursa attraverso Karaman, prese la città, si proclamò sultano e fece recitare la khutba. Questo breve sultanato terminò con la sconfitta di Cem a Yenişehir da parte delle forze inviate dal fratello maggiore Bayezid II. Per la sconfitta Cem fu costretto a fuggire verso l'Egitto.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Esecuzione di Gedik Ahmed Pascià", "6d75a58c"], "d": ["Secondo la voce Gedik Ahmed Pascià del TDV İslâm Ansiklopedisi, il pascià, noto per la campagna di Otranto e per il gran visirato, fu giustiziato a Edirne per ordine di Bayezid II a causa del suo atteggiamento nella questione di Cem Sultan e della preoccupazione per la sua influenza. La morte di uno dei comandanti più esperti dell'epoca di Maometto il Conquistatore suscitò grande eco a palazzo.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Fondazione della prima stamperia a Istanbul", "04475930"], "d": ["Secondo la voce Matbaa del TDV İslâm Ansiklopedisi, gli emigrati ebrei dalla Spagna, i fratelli David e Samuel ibn Nahmias, fondarono a Istanbul la prima stamperia che stampava in caratteri ebraici. Fu registrata come il primo tentativo di stamperia attivo in territorio ottomano; la stampa in turco con caratteri arabi sarebbe stata possibile molto più tardi, nel XVIII secolo.", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["Presa di Tabriz da parte di Shah Ismail: fondazione dello Stato safavide", "014d81e6"], "d": ["Secondo le voci Safevîler e Akkoyunlular del TDV İslâm Ansiklopedisi, il giovane sceicco della tekke di Ardabil, Ismail, con l'esercito formato dai murid Kızılbaş dell'Anatolia inflisse una grave sconfitta nella zona di Nakhchivan al sultano Aq Qoyunlu Alvand; Alvand fuggì a Diyarbakır, Ismail entrò a Tabriz, salì al trono e proclamò lo sciismo duodecimano scuola ufficiale. Si chiuse così sia il dominio Aq Qoyunlu sia il periodo dei beylicati post-ilkhanidi della regione; fu fondato lo Stato safavide, destinato a durare tre secoli.", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["Terremoto della 'Piccola Resurrezione' a Istanbul", "53e3b1d6"], "d": ["Secondo la voce Istanbul del TDV İslâm Ansiklopedisi, il violento terremoto che colpì la città fu ricordato tra la gente come 'Piccola Resurrezione'; si ebbero gravi danni a mura, moschee e molti edifici e numerose vittime. Per ordine di Bayezid II fu avviata nella città una vasta mobilitazione di riparazione e ricostruzione.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["Inizio della rivolta di Şahkulu", "3d9a4a90"], "d": ["Secondo la voce Şahkulu Baba Tekeli del TDV İslâm Ansiklopedisi, Şahkulu, alimentato dalla propaganda safavide, raccolse intorno a sé un'ampia massa turcomanna nella zona di Teke e avviò una grande rivolta di carattere religioso-sociale. La rivolta, una delle più serie crisi di sicurezza interna dell'epoca, scosse profondamente l'autorità centrale dello Stato.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["Morte di Bayezid II sulla via di Demotika", "c46e98c9"], "d": ["L'ex sultano, partito da Istanbul per recarsi nella città natale di Demotika dopo l'abdicazione, mentre avanzava nella sua portantina, che percorreva appena 5-6 km al giorno, si sentì male nel villaggio di Abalar presso Çorlu e morì il 25 Rebîülevvel 918 (10 giugno 1512). Il TDV İslâm Ansiklopedisi ritiene la causa della morte molto sospetta; secondo alcune fonti locali e straniere si insiste sulla possibilità che sia stato avvelenato. Dopo un regno di trentun anni morì così l'ottavo sultano della discendenza di Osman Gazi.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["Esecuzione dello şehzade Ahmed per ordine di Selim il Severo", "65abb2f2"], "d": ["Secondo la voce Selim I del TDV İslâm Ansiklopedisi, lo şehzade Ahmed, favorito del padre Bayezid II e principale rivale per il trono, nella lotta intrapresa dopo l'ascesa al trono del fratello Selim fu sconfitto nella piana di Yenişehir e, mentre fuggiva dal campo di battaglia, fu catturato e ucciso. Con questo fatto Selim pose in gran parte fine alla rivalità per il trono tra fratelli e nipoti.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["İbrahim Pascià nominato gran visir", "9c94c1e3"], "d": ["Secondo la voce İbrâhîm Paşa, Makbul del TDV İslâm Ansiklopedisi, İbrahim Pascià, promosso da has odabaşı a beylerbey di Rumelia e lo stesso giorno a gran visir, divenne gran visir il 13 Şâban 929 (27 giugno 1523). Fu una nomina senza precedenti, dal servizio di palazzo direttamente al gran visirato, e mostrava la straordinaria vicinanza di İbrahim Pascià a Solimano il Legislatore.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Barbaros Hayreddin Pascià nominato kapudan pascià", "a0ff6bab"], "d": ["Secondo la voce Barbaros Hayreddin Paşa del TDV İslâm Ansiklopedisi, Hayreddin Pascià, noto per i suoi successi in Algeria, fu chiamato a Istanbul il 6 aprile 1534 e nominato kapudan pascià e beylerbey di Cezâyir-i Bahr-i Sefîd. Questa nomina è considerata l'inizio della ristrutturazione della flotta ottomana e dell'istituzionalizzazione della potenza navale nel Mediterraneo.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Rüstem Pascià diventa gran visir per la prima volta", "ddfcc014"], "d": ["Secondo la voce Rüstem Paşa del TDV İslâm Ansiklopedisi, dopo la rimozione di Hadım Süleyman Pascià per un disaccordo con un visir, il 17 Ramazan 951 (2 dicembre 1544) Rüstem Pascià fu nominato gran visir. Rüstem Pascià, la cui vicinanza al palazzo era aumentata grazie al matrimonio con Mihrimah Sultan, divenne con questa carica uno degli statisti più influenti dell'epoca di Solimano il Legislatore.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Ebüssuûd Efendi diventa şeyhülislam", "11ed04f8"], "d": ["Secondo la voce Ebüssuûd Efendi del TDV İslâm Ansiklopedisi, Ebüssuûd Efendi, che era stato per otto anni kazasker di Rumelia, fu nominato şeyhülislam in Şâban 952 (ottobre 1545) e rimase in questa carica ventotto anni e undici mesi. Noto per le fatwa che armonizzavano i kanunname di Solimano il Legislatore con il diritto sciaraitico, ebbe un ruolo determinante nel dare forma alle istituzioni giuridiche ed educative della sua epoca.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Morte di Barbaros Hayreddin Pascià", "3378a0bf"], "d": ["Secondo la voce Barbaros Hayreddin Paşa del TDV İslâm Ansiklopedisi, dopo una breve malattia morì a Istanbul il 6 Cemâziyelevvel 953 (5 luglio 1546). La morte di Barbarossa, sepolto a Beşiktaş nel mausoleo adiacente alla madrasa da lui fatta costruire, fu considerata la chiusura di un'epoca della supremazia mediterranea fondata dalla flotta ottomana.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Inizio della costruzione della Moschea e del complesso di Süleymaniye", "101ec36f"], "d": ["Secondo la voce Süleymaniye Camii ve Külliyesi del TDV İslâm Ansiklopedisi, il complesso, di cui furono posate le fondamenta nel 1550 sotto la direzione dell'architetto capo Mimar Sinan, fu concepito come un grande complesso sociale composto, oltre che dalla moschea, da madrase, darüşşifa, imaret e biblioteca. La costruzione fu uno dei più grandi programmi edilizi simbolo della potenza del regno di Solimano il Legislatore e dello sviluppo urbano di Istanbul.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["Inizio di una nuova ondata di peste a Istanbul e dintorni", "547d6bf6"], "d": ["Secondo la voce Tâun del TDV İslâm Ansiklopedisi, una delle epidemie del XVI secolo che colpirono il mondo islamico si ebbe tra il 1552 e il 1566 e fu particolarmente incisiva a Istanbul, in Anatolia, Rumelia, Egitto e Nordafrica. Le vie commerciali in espansione e la crescente mobilità della popolazione sono annoverate tra i fattori che facilitarono la diffusione delle epidemie nel periodo di maggior potenza dell'Impero.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Kara Ahmed Pascià nominato gran visir", "a7d7748e"], "d": ["Secondo la voce Kara Ahmed Paşa del TDV İslâm Ansiklopedisi, Kara Ahmed Pascià, che era secondo visir, dopo l'improvvisa rimozione del gran visir in carica, il 27 Şevval 960 (5 ottobre 1553) fu promosso gran visir. Questo cambio indica un periodo, coincidente con i giorni dell'esecuzione dello şehzade Mustafa, in cui gli equilibri di potere a palazzo cambiavano rapidamente di mano.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["Giustiziato il kapudan pascià Pîrî Reis", "3b2ad7a0"], "d": ["Secondo la voce Pîrî Reis del TDV İslâm Ansiklopedisi, quando giunsero in Egitto le accuse che, togliendo l'assedio di Hormuz, avesse saccheggiato in cambio di tangenti i beni dei musulmani e abbandonato l'esercito sul campo di battaglia, il celebre navigatore e cartografo fu giustiziato al Cairo alla fine del 960 (fine 1553). La morte di Pîrî Reis, i cui beni furono confiscati, è considerata una conseguenza della rivalità tra pascià nella politica navale dell'epoca a Bassora e nell'Oceano Indiano.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Kara Ahmed Pascià giustiziato, Rüstem Pascià di nuovo gran visir", "9a85076a"], "d": ["Secondo le voci Rüstem Paşa e Kara Ahmed Paşa del TDV İslâm Ansiklopedisi, al posto di Kara Ahmed Pascià, improvvisamente giustiziato durante la riunione del divan il 13 Zilkade 962 (29 settembre 1555), con il sostegno delle sultane Hürrem e Mihrimah Rüstem Pascià fu nominato gran visir per la seconda volta lo stesso giorno. I retroscena dell'episodio sono lasciati aperti nelle fonti e sono stati valutati come il risultato di intrighi di palazzo.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Morte di Hürrem Sultan", "1ae998b5"], "d": ["Secondo la voce Hürrem Sultan del TDV İslâm Ansiklopedisi, Hürrem Sultan, che per anni come haseki sultana di Solimano il Legislatore ebbe grande influenza a palazzo, morì a Istanbul il 26 Cemâziyelâhir 965 (15 aprile 1558) e fu sepolta nel suo mausoleo nel complesso della Moschea di Süleymaniye. La morte di Hürrem Sultan, che aveva consolidato la propria autorità sull'harem dopo la morte della valide sultan Hafsa nel 1534, eliminò anche l'effetto equilibratore sulla rivalità per il trono tra i figli Bayezid e Selim.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Sokollu Mehmed Pascià sale al gran visirato", "896391a2"], "d": ["Secondo la voce Sokollu Mehmed Paşa del TDV İslâm Ansiklopedisi, Sokollu Mehmed Pascià, salito al gran visirato alla morte di Semiz Ali Pascià il 30 Zilkade 972 (29 giugno 1565), fu l'ultimo gran visir di Solimano il Legislatore e mantenne la carica anche nei periodi di Selim II e Murad III, divenendo uno dei gran visir rimasti più a lungo in carica nella storia ottomana.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Selim II giunge a Istanbul e sale al trono", "0289ef97"], "d": ["Dopo la morte di Solimano il Legislatore a Szigetvár, la notizia fu tenuta segreta per settimane da Sokollu Mehmed Pascià per non turbare l'ordine. Secondo il TDV İslâm Ansiklopedisi, Selânikî dà come data dell'arrivo di Selim a Istanbul il 15 Rebîülevvel 974 (30 settembre 1566), mentre la maggior parte degli storici contemporanei ritiene corretto il 9 Rebîülevvel (24 settembre). La morte di Solimano fu proclamata ufficialmente a Belgrado solo il 24-25 ottobre 1566.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["La flotta ricostruita da Kılıç Ali Pascià scende in mare", "d0fc9f48"], "d": ["Dopo la grave sconfitta di Lepanto (7 ottobre 1571) per tutto l'inverno si costruirono navi negli arsenali. Secondo il TDV İslâm Ansiklopedisi, il 1° Safer 980 (13 giugno 1572) la nuova flotta composta da 250 galee e circa 300 capitani volontari fu varata con una dimostrazione di forza.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Sokollu Mehmed Pascià ucciso in un attentato", "6ffa8dec"], "d": ["Sokollu Mehmed Pascià, che era stato gran visir per quattordici anni sotto tre sultani, il 20 Şâban 987 (12 ottobre 1579) fu ucciso a pugnalate da un derviscio che, nel divan pomeridiano nella sua dimora, si avvicinò come per presentare una petizione. Secondo il TDV İslâm Ansiklopedisi si discute se l'attentato fosse legato alla vendetta per lo sceicco hamzavita Hamza Bâlî, giustiziato.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["Primo ahidnâme commerciale con l'Inghilterra — capitolazioni concesse agli Inglesi", "59c8e3ee"], "d": ["Il rappresentante inglese William Harborne, inviato a Istanbul nell'ottobre 1578, con il sostegno di Sokollu Mehmed Pascià e Hoca Sâdeddin Efendi ottenne da Murad III un ahidnâme datato 1580. Con questo ahidnâme i mercanti inglesi ottennero il diritto di godere nella stessa misura dei privilegi commerciali (capitolazioni) già concessi a Francesi e Veneziani. Tra la regina Elisabetta I e Murad III furono scambiate lettere e si stabilì anche una relazione ufficiale tra i due Stati. Subito dopo questi privilegi nel 1581 fu fondata a Londra la Levant Company; gli Inglesi condussero fino al 1825 il loro commercio nella regione per mezzo di questa società.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["Osservatorio di Istanbul demolito con hatt-ı hümâyun", "3bc0c78c"], "d": ["Per l'effetto della fatwa secondo cui gli osservatori portano sventura ai paesi e dell'opposizione a palazzo, con un hatt-ı hümâyun del 4 Zilhicce 987 (22 gennaio 1580) l'Osservatorio di Istanbul fu fatto demolire con tutti gli strumenti al suo interno. Secondo il TDV İslâm Ansiklopedisi questa fu la breve fine dell'istituzione fondata da Takıyyüddin er-Râsıd.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["Inizio della festa di circoncisione dello şehzade Mehmed all'Atmeydanı", "c2926d5d"], "d": ["Lo şehzade Mehmed, figlio di Murad III, fu circonciso con sontuose cerimonie iniziate il 6 Cemâziyelevvel 990 (29 maggio 1582) e durate cinquantasei-cinquantasette giorni. Secondo il TDV İslâm Ansiklopedisi i festeggiamenti organizzati all'Atmeydanı furono una delle celebrazioni di palazzo più grandiose della sua epoca.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["Morte di Nurbânû Valide Sultan", "77d0a577"], "d": ["Nurbânû Sultan, madre di Murad III, morì il 22 Zilkade 991 (7 dicembre 1583). Secondo il TDV İslâm Ansiklopedisi, come valide sultan aveva tenuto corrispondenza con le corti di Venezia e di Francia, e il senato veneziano nello stesso anno aveva accettato di inviarle un dono del valore di 2000 ducati veneziani per i servigi resi.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["Scoppia l'episodio del Beylerbeyi per le akçe adulterate (tağşiş)", "db2f2e61"], "d": ["Quando lo Stato effettuò i pagamenti riducendo la proporzione d'argento dell'akçe, sipahi e giannizzeri assediarono il palazzo e provocarono una sanguinosa rivolta passata alla storia con il nome di Episodio del Beylerbeyi (Beylerbeyi Vak'ası). Secondo la voce Abdülkadir Şeyhî Efendi del TDV İslâm Ansiklopedisi, lo şeyhülislam fu destituito in seguito a questo fatto.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Mehmed III sale al trono, diciannove şehzade strangolati", "2cd9a8c5"], "d": ["Mehmed III, alla morte del padre Murad III, giunse a Istanbul e salì al trono venerdì 16 Cemâziyelevvel 1003 (27 gennaio 1595). Secondo il TDV İslâm Ansiklopedisi nella stessa notte furono strangolati diciannove şehzade, quattro dei quali adulti (Mustafa, Bayezid, Osman e Abdullah); fu il fratricidio più numeroso della storia ottomana.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Safiye Sultan acquisisce influenza come valide sultan", "000bec21"], "d": ["Safiye Sultan, consorte di Murad III e madre di Mehmed III, con l'ascesa al trono del figlio salì come valide sultan a una posizione determinante nella politica di palazzo. Secondo il TDV İslâm Ansiklopedisi in questo periodo l'influenza di origine harem raggiunse la dimensione di intervento diretto negli affari di Stato.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Mehmed III parte in campagna personalmente per la pressione dei giannizzeri", "d3c50656"], "d": ["Nonostante l'opposizione del gran visir Damad İbrahim Pascià, per la pressione dei giannizzeri Mehmed III, primo sultano dopo Solimano il Legislatore a porsi personalmente alla testa dell'esercito, partì da Istanbul per la campagna il 20 giugno 1596. Secondo il TDV İslâm Ansiklopedisi ciò significava la rivitalizzazione dell'antica tradizione del gazâ.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["L'epidemia di peste iniziata negli anni 1570 continuava a colpire Istanbul", "eb4ca37a"], "d": ["Secondo la voce tâun del TDV İslâm Ansiklopedisi, l'epidemia iniziata negli anni 1570 continuò a farsi sentire fino all'inizio del XVII secolo e colpì, in primo luogo Istanbul, Anatolia, Balcani, Egitto e Nordafrica. I periodi epidemici costituivano una minaccia cronica che interrompeva spesso la vita di palazzo e della città.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Muore Karayazıcı Abdülhalim, il movimento di rivolta si indebolisce", "876ca7a6"], "d": ["Karayazıcı Abdülhalim, ritiratosi ferito dopo la grave sconfitta subita il 12 agosto 1601 a Sepetli presso Elbistan, morì nel 1010 (1602). Secondo il TDV İslâm Ansiklopedisi la notizia della morte giunse a Istanbul nel Ramadan del 1010 (febbraio-marzo 1602); le fonti riferiscono che è controverso se la morte sia avvenuta per la ferita o per mano dei suoi stessi uomini.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["Fine di fatto della tradizione del fratricidio", "9046c607"], "d": ["Ahmed I, alla sua ascesa, a differenza dei sultani precedenti, non fece uccidere il fratello şehzade Mustafa e gli risparmiò la vita; questa decisione è considerata l'inizio dell'adozione di fatto nel sistema successorio ottomano del criterio ekber-erşed (il più anziano e il più capace). La voce \"Mustafa I\" del TDV İslâm Ansiklopedisi riferisce che da questa data Mustafa condusse a palazzo una vita di mahfil. La pratica pose di fatto fine agli omicidi di ascesa che si protraevano da secoli.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["Posa della prima pietra della Moschea del Sultano Ahmed", "1683262f"], "d": ["Per ordine di Ahmed I fu posata con una cerimonia la prima pietra della moschea che l'architetto Sedefkâr Mehmed Ağa avrebbe costruito all'Atmeydanı. Secondo la voce \"Sultan Ahmed Camii ve Külliyesi\" del TDV İslâm Ansiklopedisi, l'edificio fu oggetto anche di critiche dell'epoca per essere la prima grande moschea selâtin costruita direttamente dal tesoro senza una vittoria di conquista. Il complesso fu progettato in modo da includere, oltre alla moschea, anche la madrasa, l'imaret e il mausoleo.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["Uccisione di Osman il Giovane da parte dei giannizzeri (Hâile-i Osmâniye)", "324f6582"], "d": ["I giannizzeri e i sipahi, sollevatisi per le voci secondo cui con il pretesto del pellegrinaggio sarebbe uscito da Istanbul per sciogliere il corpo dei giannizzeri, deposero Osman II e lo fecero strangolare nelle prigioni di Yedikule. Secondo la voce \"Osman II\" del TDV İslâm Ansiklopedisi questo fu il primo caso nella storia ottomana in cui un sultano fu ucciso apertamente da una rivolta militare e creò una profonda frattura nel rapporto tra dinastia ed esercito. Le sue ultime ore trascorsero così: dopo che il tentativo di rifugiarsi nella dimora del comandante dei giannizzeri Ali Ağa non ebbe esito, il sultano, nelle parole del TDV 'in modo penoso, a capo scoperto, in condizioni disastrose', fu fatto salire su un cavallo e, sotto pesanti insulti, condotto prima a Orta Cami dove si trovava Mustafa I e, nel pomeriggio dello stesso giorno, a Yedikule; secondo alcuni storici, per provarne la morte gli furono tagliati orecchio e naso e mostrati alla madre di Mustafa I. Dopo il fatto Mustafa I fu fatto salire al trono per la seconda volta. L'episodio, ricordato come 'Hâile-i Osmâniye' (la tragedia di Osman), turbò in modo permanente l'equilibrio palazzo-corpo dei giannizzeri e avviò dispute di legittimità destinate a durare un secolo.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["Seconda ascesa al trono di Mustafa I", "34a0b29a"], "d": ["Dopo l'uccisione di Osman il Giovane da parte dei giannizzeri, poiché nella dinastia non c'erano altri membri maschi adulti, Mustafa I fu fatto salire al trono per la seconda volta. Secondo la voce \"Mustafa I\" del TDV İslâm Ansiklopedisi, anche questo secondo sultanato trascorse, non diversamente dal primo, senza poter condurre di fatto gli affari di Stato, e il governo dello Stato rimase in mano ai visir e alla valide sultan. Questo periodo di quattordici mesi si concluse nel 1623 con l'ascesa di Murad IV.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["Incendio di Cibali", "3e42fb08"], "d": ["L'incendio scoppiato a Cibali e diffusosi rapidamente per il vento ridusse in cenere gran parte di Istanbul; secondo la voce \"İstanbul\" del TDV İslâm Ansiklopedisi le fonti dell'epoca riferiscono che bruciarono migliaia di case. Il collegamento dell'incendio con il tessuto di case in legno e con il fumo di tabacco fu il motivo diretto del severo divieto del tabacco e dei caffè che Murad IV avrebbe proclamato poco dopo. La catastrofe fu solo uno dei grandi incendi ricorrenti nella Istanbul dell'epoca.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["Divieto di tabacco e caffè di Murad IV", "5dd71297"], "d": ["Dopo l'Incendio di Cibali, per timore di incendi e per l'ordine pubblico Murad IV vietò il fumo del tabacco e i caffè; ai trasgressori furono applicate pene gravi, compresa la pena di morte. Secondo la voce \"Murad IV\" del TDV İslâm Ansiklopedisi, il sultano seguì una politica di rigida disciplina interna al punto di girare personalmente travestito per le strade della città per far rispettare il divieto. Queste dure misure sono considerate parte dello sforzo di Murad IV per ristabilire l'autorità centrale.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["Epidemia di peste a Istanbul", "f33f58c5"], "d": ["Al tempo di Murad IV Istanbul fu scossa da una grave epidemia di peste che colpì una parte consistente della popolazione; il commercio cittadino e la vita quotidiana rimasero interrotti per mesi. La voce \"İstanbul\" del TDV İslâm Ansiklopedisi registra che le epidemie ricorrenti nel XVII secolo influirono seriamente sull'equilibrio demografico della città. Durante l'epidemia il palazzo e le élite si trasferirono per un periodo in giardini e padiglioni fuori città.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["Il volo con le ali di Hezarfen Ahmed Çelebi (tradizione)", "df474c04"], "d": ["Secondo la tradizione riferita da Evliya Çelebi, Hezarfen Ahmed Çelebi, gettandosi dalla Torre di Galata con ali da lui costruite, riuscì a planare fino a Üsküdar; anche se la sua certezza storica è discussa, divenne il simbolo dell'immaginazione tecnica. Il sultano, che inizialmente aveva ricompensato Hezarfen, per l'eco suscitata dall'episodio lo esiliò poi ad Algeri.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["Ascesa di influenza a palazzo di Cinci Hoca Hüseyin Efendi", "41d21572"], "d": ["Hüseyin Efendi, un guaritore chiamato a palazzo per curare i disturbi psichici del sultano Ibrahim, conquistò in breve la fiducia del sultano e salì fino alla carica di kazasker d'Anatolia. Secondo la voce \"Hüseyin Efendi, Cinci Hoca\" del TDV İslâm Ansiklopedisi usò questa influenza per accumulare ricchezze e interferire negli eventi politici dell'epoca. Dopo la morte di Ibrahim fu destituito da tutti gli incarichi e giustiziato nel 1648.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["Esecuzione di Kemankeş Mustafa Pascià", "0ecc8030"], "d": ["Kemankeş Mustafa Pascià, gran visir fin dal tempo di Murad IV e che con le sue riforme finanziarie aveva procurato al tesoro un notevole avanzo, fu strangolato e giustiziato in seguito all'influenza sul sultano Ibrahim dei rivali di palazzo e all'accusa di aver provocato una rivolta dei giannizzeri. Secondo la voce \"Kemankeş Mustafa Paşa\" del TDV İslâm Ansiklopedisi l'esecuzione ebbe luogo il 21 Zilkade 1053 / 31 gennaio 1644: Kemankeş Kara Mustafa Pascià fu strangolato nel Bazar di Hocapaşa dal boia Kara Ali e sepolto nel proprio mausoleo a Çarşıkapı. La sua morte è ricordata come un esempio eclatante dell'instabilità della carica di gran visir dell'epoca e pose fine a un breve periodo di rigorosa riforma.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["Decisione in Divan della Campagna di Creta e partenza della flotta", "9076827e"], "d": ["L'apertura di una campagna su vasta scala contro l'isola di Creta, appartenente a Venezia, fu decisa nel Divan-ı Hümayun e la flotta ottomana al comando del kapudan pascià mosse da Istanbul verso Creta. Secondo la voce \"Girit\" del TDV İslâm Ansiklopedisi, questa decisione costituì l'inizio politico di un lungo periodo di assedio e guerra destinato a durare circa venticinque anni. L'apertura della campagna, la maggiore iniziativa di politica estera dell'epoca di Ibrahim, aveva suscitato ampie discussioni tra i dignitari dello Stato.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["Ascesa al trono di Mehmed IV a sette anni", "a197a3bc"], "d": ["Subito dopo la deposizione di Ibrahim, il figlio Mehmed, ancora di sette anni, fu fatto salire al trono e divenne sultano con il titolo di Mehmed IV. Secondo la voce \"Mehmed IV\" del TDV İslâm Ansiklopedisi, un'ascesa al trono a un'età così giovane inasprì la lotta d'influenza a palazzo tra la nonna Kösem Sultan e la madre Turhan Sultan. Questa lotta di potere si sarebbe conclusa nel 1651 con l'uccisione di Kösem Sultan.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["Riforma del bilancio in pareggio di Tarhuncu Ahmed Pascià", "376fc7f2"], "d": ["Il gran visir Tarhuncu Ahmed Pascià, per superare la crisi finanziaria causata dai lunghi anni di guerra, applicando un duro programma di risparmio che comprendeva anche le spese di palazzo, preparò il primo bilancio in pareggio conosciuto nella storia ottomana (layiha di Tarhuncu). Secondo la voce \"Tarhuncu Ahmed Paşa\" del TDV İslâm Ansiklopedisi questa riforma procurò al tesoro un notevole avanzo, ma creò un vasto malcontento negli ambienti di palazzo e nell'alta burocrazia. Tale malcontento si sarebbe concluso un anno dopo con la sua esecuzione.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["Episodio del Platano (Çınar Vak'ası; Vak'a-i Vakvakiye)", "4c6ed90f"], "d": ["Secondo la voce Çınar Vak'ası del TDV İslâm Ansiklopedisi, i giannizzeri e i sipahi tornati senza paga dalla campagna di Creta si sollevarono a Istanbul e chiesero l'esecuzione di statisti accusati di corruzione. La proposta del gran visir Zurnazen Mustafa Pascià di confisca ed esilio non fu accolta; furono giustiziati prima tre funzionari, poi quasi trenta statisti e i loro cadaveri furono appesi ai platani della Piazza del Sultanahmet. L'episodio fu perciò ricordato con il nome di Çınar Vak'ası.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["Nomina di Köprülü Mehmed Pascià a gran visir con accettazione condizionata", "3a6b7f8f"], "d": ["Secondo la voce Köprülü Mehmed Paşa del TDV İslâm Ansiklopedisi, Köprülü Mehmed Pascià, vicino agli ottant'anni, prese il sigillo solo dopo aver fatto accettare a Valide Turhan Sultan e a Mehmed IV le pesanti condizioni da lui poste — non intromissione nelle nomine, non credere a quanto si diceva contro di lui. Subentrato a Boynueğri Mehmed Pascià, iniziò l'incarico il 26 Zilkade 1066 e si accinse a ristabilire con durezza la disciplina dello Stato.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["Repressione del movimento dei Kadızadeliler da parte di Köprülü Mehmed Pascià", "5ec3ce84"], "d": ["Secondo la voce Kadızâdeliler del TDV İslâm Ansiklopedisi, Köprülü Mehmed Pascià, appena entrato in carica, affrontò il conflitto religioso tra l'entourage di Kadızâde Mehmed Efendi e la gente delle tarîkat. Dopo aver consultato gli ulema, per i capi del movimento Üstüvânî Mehmed Efendi, Türk Ahmed e Divâne Mustafa fu emesso un firmano di esecuzione, ma la pena fu commutata in esilio e i tre furono inviati a Cipro; la seconda fase del movimento ebbe così fine.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["Grande incendio a Istanbul: distruzione di Ağakapısı", "b9253b66"], "d": ["Secondo la voce Ağakapısı del TDV İslâm Ansiklopedisi, nel grande incendio scoppiato nel luglio 1660 al tempo di Mehmed IV, l'Ağakapısı, sede ufficiale del comandante dei giannizzeri, bruciò interamente e fu poi ricostruita. Questo incendio fu uno dei grandi incendi cittadini che colpirono ripetutamente la Istanbul dell'epoca.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["Nomina di Köprülüzâde Fâzıl Ahmed Pascià a gran visir", "c1999b5c"], "d": ["Secondo la voce Köprülüzâde Fâzıl Ahmed Paşa del TDV İslâm Ansiklopedisi, alla morte del padre Köprülü Mehmed Pascià fu nominato gran visir l'8 Rebîülevvel 1072 (1° novembre 1661). Fâzıl Ahmed Pascià, noto a differenza del padre per il carattere mite, la pietà e la protezione di dotti e artisti, nel corso di un gran visirato di oltre quindici anni fece fondare biblioteche e istituzioni caritatevoli a Istanbul e nei territori conquistati.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["Nomina di Vânî Mehmed Efendi a predicatore di Yeni Cami e a precettore del sultano", "7ea6aaae"], "d": ["Secondo la voce Mehmed Efendi, Vânî del TDV İslâm Ansiklopedisi, Vânî Mehmed Efendi, chiamato a Istanbul con l'ascesa a gran visir di Köprülüzâde Fâzıl Ahmed Pascià e presentato a Mehmed IV, conquistò in breve l'interesse stretto del sultano. Nel 1665, nominato predicatore di Yeni Cami e precettore del sultano, divenne uno dei religiosi più influenti del palazzo.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["Nomina di Merzifonlu Kara Mustafa Pascià a gran visir", "3d1e836c"], "d": ["Secondo la voce Merzifonlu Kara Mustafa Paşa del TDV İslâm Ansiklopedisi, alla morte di Fâzıl Ahmed Pascià fu nominato gran visir il 28 Şâban 1087 (5 novembre 1676). Genero e allievo della famiglia Köprülü, con una lunga esperienza nel governo dello Stato, Merzifonlu divenne uno dei gran visir più potenti e influenti di Mehmed IV.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["Morte in esilio di Vânî Mehmed Efendi", "cda714aa"], "d": ["Secondo la voce Mehmed Efendi, Vânî del TDV İslâm Ansiklopedisi, Vânî Mehmed Efendi, considerato tra i principali artefici dell'accettazione da parte del sultano della campagna di Vienna, dopo l'esito di disfatta della campagna fu screditato per la pressione dell'opinione pubblica ed esiliato a Kestel, presso Bursa. Qui morì il 14 Zilkade 1096 (12 ottobre 1685) e fu sepolto all'ingresso della moschea da lui fatta costruire.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["Nomina di Köprülüzâde Fâzıl Mustafa Pascià a gran visir e sue riforme finanziarie", "b048570e"], "d": ["Secondo la voce Köprülüzâde Fâzıl Mustafa Paşa del TDV İslâm Ansiklopedisi, Fâzıl Mustafa Pascià, nominato gran visir l'11 Muharrem 1101 (25 ottobre 1689), riorganizzò il metodo di riscossione della cizye secondo i principi sciaraitici, combatté l'inflazione del mangır e rafforzò il tesoro trasferendo risorse dalle istituzioni di palazzo. Rafforzò inoltre l'amministrazione provinciale con funzionari fidati e fece costituire consigli locali simili al divan centrale.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["Entrata in vigore del sistema del mâlikâne", "316b8426"], "d": ["Secondo la voce Mâlikâne del TDV İslâm Ansiklopedisi, nell'ultimo quarto del XVII secolo l'aumento delle spese di guerra e la riduzione delle entrate per le perdite territoriali gettarono il tesoro in una grave crisi finanziaria. Con il sistema del mâlikâne, entrato in vigore nel 1106 (1695), agli appaltatori (mültezim) fu riconosciuto un diritto fiscale fisso a vita, introducendo un incentivo alla tutela della produzione in luogo dello sfruttamento a breve termine.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["Ascesa al trono di Mustafa II", "b53656c7"], "d": ["Secondo la voce Mustafa II del TDV İslâm Ansiklopedisi, Mustafa II, salito al trono a trentun anni, proclamò il proprio sultanato senza attendere l'approvazione del gran visir e dello şeyhülislam; la cerimonia della cinta della spada fu fatta alcuni giorni dopo a Eski Cami. Il sultano, salito al trono in un periodo in cui continuavano guerre su più fronti dopo la disfatta di Vienna, fu l'ultimo sultano ottomano a partire personalmente in campagna.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["Seconda nomina di Feyzullah Efendi a şeyhülislam", "1cf14cff"], "d": ["Secondo la voce Feyzullah Efendi, Seyyid del TDV İslâm Ansiklopedisi, dopo l'ascesa di Mustafa II fu nominato per la seconda volta şeyhülislam l'11 Şevval 1106 (25 maggio 1695). La sua influenza sul sultano crebbe progressivamente nel periodo di questa carica, durato oltre otto anni.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["Feyzullah Efendi pone i figli in alte cariche e reazioni accumulate", "a6398280"], "d": ["Secondo la voce Feyzullah Efendi, Seyyid del TDV İslâm Ansiklopedisi, lo şeyhülislam ottenne da Mustafa II un firmano senza precedenti secondo cui il figlio Fethullah Efendi sarebbe diventato şeyhülislam dopo di lui e collocò i parenti in giovane età in alte cariche. Queste pratiche crearono un ampio malcontento tra la classe dell'ilmiye, i soldati e la popolazione di Istanbul; unito alle voci di un trasferimento della capitale a Edirne, preparò il terreno all'Episodio di Edirne del 1703.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["Inizio dell'Episodio di Edirne", "5a106458"], "d": ["Secondo la voce \"Edirne Vak'ası\" del TDV, il movimento, iniziato con la sollevazione dei soldati che non ricevevano le ulufe, si trasformò presto in una vasta rivolta a cui parteciparono giannizzeri, studenti di madrasa, artigiani e popolo. Il vero bersaglio della rivolta era lo şeyhülislam Feyzullah Efendi, accusato di interferire eccessivamente negli affari di Stato. Una folla di circa 60.000 persone marciò da Istanbul a Edirne.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["Gran visirato di Nevşehirli Damad İbrahim Pascià", "8d627a6f"], "d": ["Secondo la voce \"Damad İbrâhim Paşa, Nevşehirli\" del TDV, fu messo alla carica di gran visir l'8 Cemâziyelâhir 1130 (9 maggio 1718) durante i negoziati di pace in corso con l'Austria e, appena nominato, si volse ai negoziati che avrebbero posto fine alla guerra; due mesi dopo fu firmato il Trattato di Passarowitz (21 luglio 1718). Nelle parole del TDV 'voleva occuparsi di questioni sociali e finanziarie e anelava a un periodo di pace che facesse dimenticare le guerre concluse da anni con la sconfitta'. Fece riforme nelle finanze, ridusse gli stipendi dei soldati e creò un notevole avanzo nel tesoro dello Stato. Il suo gran visirato, destinato a durare dodici anni, costituì la cornice politica dell'epoca che porta il suo nome (Età dei Tulipani).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["Fondazione dell'Ocak dei Tulumbacı", "f58b0d97"], "d": ["Secondo la voce \"Tulumbacı\" del TDV, per il successo mostrato da Gerçek Dâvud, tornato dalla campagna di Morea del 1715, con la tulumba (pompa antincendio) negli incendi di Istanbul, il gran visir Nevşehirli Damad İbrahim Pascià lo incaricò di fondare un ocak ufficiale di vigili del fuoco. L'ocak, fondato nella Caserma degli Acemi Oğlanları con sei ufficiali e cinquanta soldati, raggiunse le 150 persone nel 1724 e le 461 nel 1755. Dâvud rimase a capo dell'ocak fino alla morte nel 1733.", "3b860f0f"]},
"OLAYLAR_EK7:1721-03-21:0":{"b": ["Ricevimento di Mehmed Efendi da parte di Luigi XV", "0ff5b174"], "d": ["Secondo la voce \"Yirmisekiz Çelebi Mehmed Efendi\" del TDV, l'ambasciatore fu ricevuto ufficialmente nel Palazzo delle Tuileries dal re di Francia Luigi XV e presentò i doni e la lettera di Ahmed III. Durante la visita visitò i palazzi di Versailles, Trianon e Marly, ospedali, osservatori e manifatture; registrò con disegni ciò che vedeva.", "c0c34dbc"]},
"OLAYLAR_EK7:1721-10-08:0":{"b": ["Ritorno di Mehmed Efendi a Istanbul", "a09a8bba"], "d": ["Secondo la voce \"Yirmisekiz Çelebi Mehmed Efendi\" del TDV, le osservazioni dell'ambasciatore, tornato dopo un anno di ambasceria a Parigi, influenzarono il gusto architettonico dell'Età dei Tulipani. Il fatto che il figlio abbia poi lavorato con İbrahim Müteferrika preparò il terreno per la fondazione della prima stamperia turca, la più duratura eredità dell'ambasceria.", "799571fc"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["Costruzione del Padiglione di Sâdâbâd", "aec9c65e"], "d": ["Secondo la voce \"Sâdâbâd\" del TDV, sulle rive del torrente Kâğıthane fu costruito un ampio complesso di svago e di passeggio composto da padiglioni, canali, fontane e kiosk ispirati all'architettura di palazzo francese. Divenuto il luogo di svago più in voga dell'epoca, Sâdâbâd fu immortalato nei versi del poeta Nedîm. Il complesso fu in gran parte distrutto durante la Rivolta di Patrona Halil del 1730.", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["Presa di Derbent da parte delle forze russe: la campagna del Caspio di Pietro I", "c2b269f9"], "d": ["Mentre lo Stato safavide era trascinato nel disordine interno dall'invasione afghana, lo zar russo Pietro I intraprese una campagna per impadronirsi dei territori iraniani sulla costa del Caspio; la città costiera di Derbent si arrese alle forze russe senza vedere una resistenza degna di nota. Secondo la voce Derbend del TDV İslâm Ansiklopedisi questa occupazione fu l'inizio di un dominio russo temporaneo destinato a durare tredici anni; anche l'Impero ottomano, approfittando della stessa confusione, si volse alla parte occidentale del Caucaso. L'esercito era sbarcato da Astrachan' per mare nel golfo di Agrachan e di lì aveva marciato via terra lungo la costa attraverso Tarku; lo shamkhal di Tarku ospitò Pietro ed entrò sotto la dipendenza russa.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["Abolizione dello shamkhalato di Tarku: amministrazione russa diretta", "b0f029c6"], "d": ["Lo shamkhal di Tarku Adil-Girey, che nel 1722 aveva ospitato Pietro ed era entrato sotto la dipendenza russa, nel 1725 si ribellò; Eropkin distrusse Tarku nell'autunno 1725, lo shamkhal fu arrestato ed esiliato a metà maggio 1726 e lo shamkhalato fu abolito. Tarku e dintorni rimasero sotto amministrazione russa diretta fino al Trattato di Ganja del 1735.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["Permesso a İbrahim Müteferrika di fondare una stamperia", "0659dd0a"], "d": ["Secondo la voce \"İbrâhim Müteferrika\" del TDV, con il firmano di Ahmed III e la fatwa dello şeyhülislam Yenişehirli Abdullah Efendi fu permessa la fondazione della prima stamperia turca. La stamperia entrò in attività nel quartiere di Yavuzselim a Istanbul. Müteferrika fino alla morte nel 1747 stampò diciassette opere in ventitré volumi.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["Completamento del primo libro stampato, il Vankulu Lügati", "684700e8"], "d": ["Secondo la voce \"İbrâhim Müteferrika\" del TDV, la traduzione turca del Sıhâhu'l-Cevherî (Vankulu Lügati), prima opera della stamperia, fu completata all'inizio del 1729. Fu il primo libro stampato con caratteri arabi in territorio ottomano ed è considerato l'inizio della storia della stampa turca.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["Esecuzione di Nevşehirli Damad İbrahim Pascià", "50c64341"], "d": ["Secondo la voce \"Damad İbrâhim Paşa, Nevşehirli\" del TDV, il corpo del gran visir, ucciso a palazzo durante la Rivolta di Patrona Halil, fu trascinato per le strade di Istanbul e abbandonato presso la Fontana di Ahmed III nella Piazza del Sultanahmet. Il suo gran visirato di dodici anni e l'Età dei Tulipani ebbero così una fine sanguinosa.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["Abdicazione di Ahmed III, ascesa al trono di Mahmud I", "a43f5d40"], "d": ["Secondo la voce \"Mahmud I\" del TDV, di fronte alla pressione dei ribelli Ahmed III abdicò dopo aver ottenuto garanzie per sé e per i figli e fece salire personalmente al trono il nipote şehzade Mahmud. Mahmud I, salito al trono con il consiglio dello zio 'prendi gli affari di Stato nelle tue mani, non fidarti di nessuno', come prima cosa si accinse a spezzare l'influenza del gruppo di ribelli che lo aveva portato sul trono.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["Riforma dell'ocak di artiglieria da parte di Humbaracı Ahmed Pascià", "ea3a7c64"], "d": ["Secondo la voce \"Humbaracı\" del TDV, l'ufficiale di origine francese convertito all'islam Ahmed Pascià, al tempo del gran visir Hekimoğlu Ali Pascià, si accinse a riformare all'europea l'organizzazione degli humbaracı con ulufe. Creò una nuova struttura di 601 persone, di cui 300 stipendiate e 301 titolari di timar, direttamente dipendente dal gran visir. Con la tecnologia dell'epoca fece produrre 100 mortai e 50.000 palle.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["Fondazione dell'Hendesehâne (primo esempio di scuola di ingegneria)", "a77ed1f3"], "d": ["Secondo la voce \"Mahmud I\" del TDV, Humbaracı Ahmed Pascià, fondando a Üsküdar l'Hendesehâne, detta anche Humbarahâne, impartì un'istruzione militare basata su matematica e geometria a studenti scelti tra i servitori di palazzo e i bostancı. Questa istituzione è considerata il primo esempio delle scuole di ingegneria sviluppatesi in seguito.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["Trattato di Ganja: restituzione di Derbent e Baku all'Iran", "ff19d531"], "d": ["La Russia, che cercava un'alleanza con l'Iran contro la minaccia ottomana, con il Trattato di Ganja restituì all'Iran, al comando di Nadir Khan (che non aveva ancora assunto il titolo di shah), le città della costa del Caspio che teneva da tredici anni. Secondo la voce Derbend del TDV İslâm Ansiklopedisi questo ritiro fu conseguenza del fatto che la Russia non voleva lottare su due fronti a sud (ottomano e iraniano) e consolidò il prestigio militare di Nadir, che aprì la strada alla sua ascesa al trono pochi anni dopo. Anche Tarki (Tarku), in amministrazione russa, con questo ritiro tornò dalla parte iraniana (sulla mappa si usa il giorno di Ganja). Anche Salyan e Şâbüran, in amministrazione russa, con questo ritiro tornano dalla parte iraniana (il giorno specifico per le località non è nella fonte, sulla mappa si usa il giorno di Ganja — beyanlı yaklaşıklık).", "711f14d9"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["Ascesa al trono di Nadir Shah nella pianura di Mugan: fine di fatto della dinastia safavide", "4f640979"], "d": ["Secondo la voce Nadir Şah del TDV İslâm Ansiklopedisi il kurultay di circa ventimila persone riunito nella pianura di Mugan chiese con insistenza che si ponesse alla testa dell'Iran; Nadir accettò la proposta a condizione che si abbandonasse la concezione sciita estrema che aveva causato le guerre tra Safavidi e Ottomani e si adottasse la moderata scuola giafarita, e il 24 Şevval 1148 (8 marzo 1736) salì al trono con il titolo di Nadir Shah. Ciò significava la fine di fatto della dinastia safavide di due secoli e la fondazione della dinastia afsharide.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["Inizio dell'epidemia di peste a Istanbul", "9fa82b56"], "d": ["Secondo la voce \"Tâun\" del TDV, l'epidemia di peste che fu attiva nella geografia islamica tra il 1739 e il 1743 colpì in questo periodo anche Istanbul. La voce indica che le epidemie nel XVIII secolo ebbero un decorso relativamente più lieve rispetto ai secoli precedenti. Tra i periodi epidemici sono annoverati anche gli anni 1713, 1719, 1728-1729 e 1759-1765.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["Incendio di Hocapaşa", "321c7d0d"], "d": ["Secondo la voce \"Fatma Sultan Camii\" del TDV, l'incendio di Hocapaşa scoppiato di notte devastò la Sublime Porta e i dintorni; si suppone che anche la Moschea di Fatma Sultan nella zona sia stata danneggiata da questo incendio. Questa catastrofe, uno dei grandi incendi che colpirono Istanbul al tempo di Osman III, causò gravi distruzioni nel centro commerciale e amministrativo della città.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["Gran visirato di Koca Ragıp Mehmed Pascià", "a1846910"], "d": ["Ragıp Pascià, noto come poeta e diplomatico, fu messo da Osman III alla carica di gran visir (nell'ottobre 1757, alla morte di Osman III, continuò l'incarico, ricevendo un nuovo sigillo da Mustafa III). Mentre proseguivano le Guerre dei Sette Anni, seguì una politica estera equilibrata che teneva l'Impero ottomano fuori dai conflitti in Europa. Durante il suo gran visirato di sei anni diede importanza anche ad attività culturali come la fondazione di biblioteche.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["Morte di Ragıp Pascià", "6bc19323"], "d": ["Ragıp Pascià morì dopo un gran visirato di sei anni. Con la sua morte ebbe fine il gran visirato più duraturo ed equilibrato del periodo di Mustafa III.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["Grande terremoto di Istanbul e crollo della Moschea di Fatih", "2475b4dc"], "d": ["Secondo la voce \"Fâtih Camii ve Külliyesi\" del TDV, nel grande terremoto del 1766 la cupola principale della moschea crollò completamente e le mura subirono danni irreparabili. La ricostruzione, iniziata nel 1767 per ordine di Mustafa III sotto la direzione degli architetti Sarım İbrahim Efendi e İzzet Mehmed Bey, fu completata nel 1771 con un nuovo progetto diverso dal piano antico.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["Breve tentativo di scuola di artiglieria guidato dal barone de Tott", "4192260c"], "d": ["Secondo la voce \"Mühendishâne-i Bahrî-i Hümâyun\" del TDV, i fallimenti della guerra ottomano-russa del 1768 misero in evidenza la necessità di un'istruzione militare tecnica; la breve scuola di artiglieria aperta con il contributo dell'ufficiale francese barone de Tott entrò in attività nell'ottobre 1772 ma rimase inefficace. Questo tentativo è considerato il precursore della Mühendishâne-i Bahrî-i Hümâyun che sarebbe stata fondata nel 1775.", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["Selim III sale al trono", "00d046d9"], "d": ["Alla morte di Abdülhamid I salì al trono il nipote Selim III. Secondo la voce Selim III del TDV İslâm Ansiklopedisi, il nuovo sultano, interessato fin da şehzade alla riforma degli eserciti europei, poco dopo l'ascesa fece iniziare a preparare un programma di profondo rinnovamento. Questo programma sarebbe stato noto in pochi anni con il nome di Nizâm-ı Cedîd.", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["Inizio della preparazione del programma di riforma del Nizâm-ı Cedîd", "eff78a68"], "d": ["Selim III fece preparare un programma di rinnovamento ampio in base ai layiha richiesti ai dignitari dello Stato e a esperti stranieri. Secondo la voce Nizâm-ı Cedîd del TDV İslâm Ansiklopedisi questo programma non si limitò a creare un nuovo esercito; si trasformò in un vasto movimento di riforma che comprendeva finanze, amministrazione provinciale e diplomazia. Il programma avrebbe trovato nei quindici anni successivi sia sostenitori sia oppositori.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["Istituzione di ambasciate permanenti nelle capitali europee", "2e9dc8a1"], "d": ["Selim III inviò per la prima volta nella storia dell'Impero ottomano ambasciatori permanenti nei grandi centri europei. Secondo la voce Elçi del TDV İslâm Ansiklopedisi, questo passo diede un'organizzazione stabile alla diplomazia ottomana, condotta fino ad allora solo con delegazioni temporanee e occasionali. Il compito principale delle nuove ambasciate era comunicare regolarmente a Istanbul gli sviluppi politici e militari in Europa.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["Fondazione del tesoro İrad-ı Cedîd", "ae5c8ce2"], "d": ["Fu istituito un tesoro separato per coprire le spese dell'esercito del Nizâm-ı Cedîd e del programma di riforma. Secondo la voce Esham del TDV İslâm Ansiklopedisi, tra le entrate del nuovo tesoro vi erano la gestione diretta da parte dello Stato di alcune mukataa e il controllo delle vendite di esham. Questo riordino fu un tentativo di creare una nuova fonte al di fuori del sistema finanziario tradizionale.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["Inizio della rivolta di Kabakçı Mustafa", "b98eee17"], "d": ["Il malcontento accumulato contro il Nizâm-ı Cedîd esplose con la sollevazione dei soldati yamak guidati da Kabakçı Mustafa. Secondo la voce Kabakçı İsyanı del TDV İslâm Ansiklopedisi i ribelli in breve presero il controllo di Istanbul e chiesero le teste degli statisti favorevoli al Nizâm-ı Cedîd. La sollevazione si concluse in pochi giorni con la deposizione di Selim III.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["Selim III deposto", "ff2c30ec"], "d": ["Sotto la pressione della rivolta di Kabakçı Mustafa, con la fatwa ottenuta dallo şeyhülislam Selim III fu deposto. Secondo la voce Selim III del TDV İslâm Ansiklopedisi questa decisione fu il momento in cui il periodo di riforme di diciotto anni terminò di fatto; anche l'esercito del Nizâm-ı Cedîd fu abolito in breve tempo. Selim cominciò a essere tenuto sotto sorveglianza nel Palazzo di Topkapı.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["Mustafa IV sale al trono", "8f1ac86c"], "d": ["Subito dopo la deposizione di Selim III il nipote Mustafa IV fu proclamato sultano. Secondo la voce Mustafa IV del TDV İslâm Ansiklopedisi, il nuovo sultano iniziò il regno sotto l'influenza degli ambienti contrari al Nizâm-ı Cedîd che avevano sostenuto la rivolta. Questo breve periodo fu una fase di instabilità in cui l'autorità centrale si indebolì ulteriormente.", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["Alemdar Mustafa Pascià entra a Istanbul con l'esercito", "0cad3dea"], "d": ["Alemdar Mustafa Pascià, ayan di Ruse, giunse davanti a Istanbul con il suo esercito allo scopo di rimettere sul trono Selim III. Secondo la voce Alemdar Mustafa Paşa del TDV İslâm Ansiklopedisi, il suo ingresso in città fu accolto personalmente da Mustafa IV; ma in pochi giorni l'equilibrio di potere a palazzo sarebbe cambiato del tutto. Questo ingresso avviò la catena di eventi che si concluse sia con la morte di Selim sia con una nuova ascesa al trono.", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["Selim III ucciso", "e452f5f6"], "d": ["Nel giorno in cui Alemdar Mustafa Pascià si impadronì della Sublime Porta, Selim III fu ucciso a palazzo per ordine di Mustafa IV. Secondo la voce Selim III del TDV İslâm Ansiklopedisi, fu una decisione presa allo scopo di impedire il tentativo di rimettere sul trono un sultano deposto. La morte di Selim si concluse nello stesso giorno con l'ascesa al trono di Mahmud.", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["Mahmud II sale al trono", "661c1974"], "d": ["Dopo l'uccisione di Selim III, Mahmud, rimasto unico membro maschio della dinastia, salì al trono con il sostegno di Alemdar Mustafa Pascià. Secondo la voce Mahmud II del TDV İslâm Ansiklopedisi, il nuovo sultano trascorse i primi mesi del regno sotto la tutela di Alemdar, che lo aveva fatto salire al trono, e nello sforzo di ristabilire l'equilibrio tra gli ayan e il centro. Questo periodo fu l'inizio del successivo processo di profonde riforme di vent'anni.", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["Fondazione dell'esercito Sekbân-ı Cedîd", "6f9eb5e4"], "d": ["Alemdar Mustafa Pascià fece costituire al posto del Nizâm-ı Cedîd, abolito, un nuovo esercito equipaggiato all'europea. Secondo la voce Sekbân-ı Cedîd del TDV İslâm Ansiklopedisi, questa forza composta da tre reggimenti fu vista dai giannizzeri come una minaccia diretta e fu eliminata in una rivolta dei giannizzeri solo pochi mesi dopo la sua fondazione.", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["Caduta di Ibraila — prima grande breccia nella linea del Danubio", "ee519321"], "d": ["Nella guerra russa iniziata nel 1806 la fortezza di Ibraila, sulla riva settentrionale del Danubio, fu assediata e bombardata dalle forze russe al comando del conte Kaminskij. All'interno vi erano 4100 fanti, 1100 cavalieri e 260 cannoni; la fortezza si arrese al generale Essen per la scarsità di viveri. L'estremità settentrionale della linea di difesa del Danubio fu così aperta.", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["Resa di Ruse — anche la riva meridionale del Danubio va perduta", "084062e8"], "d": ["Ruse resistette al lungo e sanguinoso assedio dell'esercito russo al comando del conte Kaminskij; si arrese a condizione che la guarnigione e la popolazione civile lasciassero la città in sicurezza. La caduta della più forte città-fortezza sulla riva meridionale del Danubio volse il corso della guerra a favore della Russia.", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["Fondazione dell'Eşkinci Ocağı", "67c56759"], "d": ["Mahmud II fece costituire un nuovo reparto con soldati scelti all'interno dell'ocak dei giannizzeri, che sarebbe stato addestrato all'europea. Secondo la voce Eşkinci Ocağı del TDV İslâm Ansiklopedisi, il reparto iniziò l'addestramento il 12 giugno 1826, ma i giannizzeri lo videro come la fine del proprio ocak. La rivolta scoppiata tre giorni dopo pose termine anche alla breve vita dell'Eşkinci Ocağı.", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["Fondazione degli Asâkir-i Mansûre-i Muhammediyye", "14b84a7e"], "d": ["Subito dopo l'abolizione del Corpo dei giannizzeri Mahmud II fece costituire al suo posto un nuovo esercito regolare con addestramento all'europea. Secondo la voce Asâkir-i Mansûre-i Muhammediyye del TDV İslâm Ansiklopedisi, questo esercito, per ordinamento dei gradi, programma di addestramento e sistema di paga, a differenza dei tentativi precedenti divenne un'istituzione duratura. L'esercito si sarebbe trasformato negli anni seguenti nell'esercito Nizâmiye dell'epoca del Tanzimat.", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["Chiusura dell'ordine bektashi", "f7d9a367"], "d": ["Contemporaneamente all'abolizione del Corpo dei giannizzeri fu vietato anche l'ordine bektashi, noto per i legami religiosi con l'ocak. Secondo la voce Bektaşîlik del TDV İslâm Ansiklopedisi, mentre alcuni sceicchi di piccole tekke furono giustiziati, lo sceicco della dergâh di Hacı Bektaş fu esiliato ad Amasya e le tekke furono affidate all'amministrazione naqshbandi. L'ordine, nonostante questo duro colpo, continuò segretamente la propria organizzazione.", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["Episodio del ventaglio — il pretesto dell'occupazione", "e949001e"], "d": ["Nei negoziati inaspriti dal mancato pagamento dell'antico debito di grano della Francia verso Algeri, il dey Hüseyin colpì con il ventaglio che teneva in mano il console francese Deval. Questo episodio, nato da una controversia su un credito, fu fatto il pretesto ufficiale dell'occupazione che sarebbe iniziata tre anni dopo.", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["Blocco francese della costa algerina — assedio di tre anni", "d0ba97a5"], "d": ["Dopo l'episodio del ventaglio la Francia pose sotto blocco la costa algerina. Il blocco durò tre anni; il commercio marittimo e le fonti di reddito dell'ocak furono prosciugati e la capacità di resistenza fu erosa prima dell'inizio dell'occupazione.", "79d27be2"]},
"OLAYLAR_EK7:1828-02-22:0":{"b": ["Trattato di Turkmenchay: Erevan e Talysh passano alla Russia", "abffcfdb"], "d": ["Quando la guerra russo-iraniana del 1826-1828 si concluse con una grave sconfitta dell'Iran, con il trattato firmato a Turkmenchay i khanati di Erevan e Nakhchivan e la regione di Talysh sulla costa del Caspio (Lankaran, Astara) furono lasciati alla Russia; fu imposta inoltre una pesante indennità di guerra. Secondo la voce Revan del TDV İslâm Ansiklopedisi questa perdita è il momento in cui fu tracciato il confine russo-iraniano nel Caucaso, destinato a rimanere in gran parte valido fino a oggi, e innescò anche la migrazione della popolazione armena a Erevan. Con questo trattato il khanato di Erevan (Echmiadzin, Iğdır, Norapat, Beri) e il khanato di Nakhchivan (Julfa, Şerur) passarono alla Russia.", "847d76d5"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["Seconda caduta di Ibraila — lo zar Nicola davanti alla fortezza", "eb6a8741"], "d": ["Ibraila, restituita agli Ottomani nel 1812 e rifortificata nel 1817-1818, fu assediata in aprile con 4000 uomini di guarnigione e 278 cannoni al suo interno. Il comandante Ebûbekir Pascià stabilì una nuova linea di difesa; lo zar Nicola I giunse personalmente davanti alla fortezza alla fine di maggio. La città subì l'occupazione russa, ma sarebbe stata restituita con il Trattato di Edirne e lasciata al principato di Valacchia.", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["Proclamazione del fez come copricapo ufficiale", "f55be4eb"], "d": ["Mahmud II, attuando un cambiamento radicale nell'abbigliamento di funzionari e soldati, proclamò il fez copricapo ufficiale al posto del turbante. Secondo la voce Fes del TDV İslâm Ansiklopedisi, questa decisione fu annunciata con un hatt-ı hümâyun e messa in pratica insieme alle riforme all'occidentale degli Asâkir-i Mansûre-i Muhammediyye. Il cambiamento significava anche la fine della gerarchia tradizionale dell'abbigliamento.", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["Cessione di Akhaltsikhe alla Russia — il centro dell'eyalet di Çıldır va perduto", "e2e00b2a"], "d": ["Akhaltsikhe, in amministrazione ottomana dalla Guerra di Çıldır del 1578 e centro dell'eyalet di Çıldır, fu ceduta alla Russia con il Trattato di Edirne firmato alla fine della guerra del 1828-1829. La perdita della città creò profonda tristezza tra la gente e fu oggetto di molti lamenti funebri. Con questo fatto Akhalkalaki, Zazalo e Ts'q'altbila (regione di Akhaltsikhe–Akhalkalaki) passarono alla Russia.", "bab87a04"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["Sbarco a Sidi Ferruch — l'esercito francese sul suolo algerino", "33327553"], "d": ["Dopo il blocco di tre anni l'esercito di sbarco francese al comando del conte de Bourmont sbarcò truppe nella baia di Sidi Ferruch, nell'Algeria occidentale. Le forze avanzanti verso la città spezzarono la linea di difesa in tre settimane; il 4 luglio cadde il Forte dell'Imperatore che domina la città, il giorno dopo il dey Hüseyin si arrese.", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["Esilio del dey Hüseyin — fine di fatto dell'ocak di Algeri", "e122403b"], "d": ["In forza delle condizioni di resa l'ultimo dey di Algeri, Hüseyin, fu fatto uscire dalla città con la famiglia e il tesoro e inviato a Napoli. L'amministrazione dell'ocak, legato nel 1519 a Selim I (il Severo) e per trecento anni la più forte base navale ottomana nel Mediterraneo, ebbe così fine.", "bf7169cf"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["Ritiro dell'esercito russo da Valacchia e Moldavia — fine dell'occupazione di sei anni", "efdb0275"], "d": ["Nella guerra ottomano-russa del 1828-1829 i Russi avevano occupato Valacchia e Moldavia e dopo il Trattato di Edirne non si erano ritirati fino al pagamento dell'indennità di guerra. Quando nel gennaio 1834 l'indennità fu ridotta a cinque milioni, le forze russe evacuarono i Principati (Memleketeyn) e per i due principati furono nominati nuovi voivodi. La sovranità ottomana tornò sulla carta, ma la Russia conservò l'influenza stabilita con il Regolamento Organico.", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["Fondazione dell'organizzazione Redif-i Asâkir-i Mansûre", "15947493"], "d": ["L'organizzazione Redif, come forza di riserva a sostegno degli Asâkir-i Mansûre-i Muhammediyye, fu istituita con il regolamento dell'8 luglio 1834. Secondo la voce Redif del TDV İslâm Ansiklopedisi, sotto la direzione del seraschiere Koca Hüsrev Pascià furono formati nei kaza di provincia battaglioni di circa millequattrocento uomini ciascuno. L'organizzazione era concepita in modo da sostenere anche la sicurezza locale senza essere chiamata al servizio permanente.", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["Fondazione del Ministero degli Affari Esteri (Hariciye Nezareti)", "750c6c7d"], "d": ["Mahmud II, abolita la carica di Reisülküttâb che conduceva gli affari esteri, fondò al suo posto l'Hariciye Nezareti. Secondo la voce Hariciye Nezâreti del TDV İslâm Ansiklopedisi, come primo ministro del nuovo ministero fu nominato Mehmed Âkif Pascià e l'organizzazione iniziò l'attività nella dimora dell'ambasciatore a Vienna Rıfat Bey. Questo riordino fu l'inizio della conduzione della politica estera ottomana secondo il principio del ministero moderno.", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["Fondazione del Meclis-i Vâlâ-yı Ahkâm-ı Adliyye", "69db056e"], "d": ["Mahmud II fece fondare il Meclis-i Vâlâ-yı Ahkâm-ı Adliyye come assemblea di alto livello in cui discutere le leggi e i regolamenti da preparare. Secondo la voce Meclis-i Vâlâ-yı Ahkâm-ı Adliyye del TDV İslâm Ansiklopedisi l'assemblea iniziò di fatto a lavorare il 31 marzo 1838 e quasi tutte le successive riforme del Tanzimat furono preparate e controllate tramite questo organo. L'istituzione divenne uno dei più importanti centri della burocrazia ottomana moderna.", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["Incursione di Sinope", "5947e93f"], "d": ["La flotta russa del Mar Nero, al comando dell'ammiraglio Nachimov, attaccò senza dichiarazione di guerra la flotta ottomana ancorata nel porto di Sinope; affondarono dodici navi, più di duemila soldati caddero martiri e il comandante della flotta Osman Pascià fu fatto prigioniero. Secondo la voce Sinop del TDV İslâm Ansiklopedisi, nell'incursione bruciarono in città anche sette mescid, due scuole, 247 case e 170 botteghe, e persero la vita civili, cinque musulmani e sedici cristiani. L'episodio, che ebbe eco in Europa come 'disastro di Sinope', fu l'innesco diretto dell'entrata in guerra di Inghilterra e Francia al fianco degli Ottomani nel giro di pochi mesi.", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["Pubblicazione del Tasvir-i Efkâr", "506c98e2"], "d": ["Il Tasvir-i Efkâr, pubblicato da Şinasi, iniziò le pubblicazioni come quarto giornale turco dopo Takvîm-i Vekāyi', Cerîde-i Havâdis e Tercüman-ı Ahvâl. Secondo la voce \"Tasvîr-i Efkâr\" del TDV, il giornale divenne, nel periodo di Nâmık Kemal che ne assunse poi la direzione, il portavoce del movimento dei Nuovi Ottomani.", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["Fondazione della Società dei Nuovi Ottomani", "335fb02d"], "d": ["Gli intellettuali ottomani fuggiti in Europa sotto la guida di Mustafa Fâzıl Pascià si organizzarono con il nome di Giovane Turchia con un regolamento di tredici articoli. Secondo la voce \"Yeni Osmanlılar Cemiyeti\" del TDV, il gruppo diffuse la richiesta di governo costituzionale pubblicando a Parigi, Londra e Ginevra giornali come Muhbir e Hürriyet.", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["Fondazione dello Şûrâ-yı Devlet", "b863b306"], "d": ["Il Meclis-i Ahkâm-ı Adliyye fu diviso in due e furono costituiti lo Şûrâ-yı Devlet, che si occupava degli affari amministrativi, e il Dîvân-ı Ahkâm-ı Adliyye, che si occupava degli affari giudiziari. Secondo la voce \"Şûrâ-yı Devlet\" del TDV, alla prima presidenza dell'istituzione, che aveva come modello il Conseil d'État francese, fu posto Midhat Pascià; lo scopo era la separazione di legislativo, esecutivo e giudiziario.", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["Emanato il decreto di fondazione del Darülfünun", "513704bf"], "d": ["Con l'irade preparato dal gran visir Âli Pascià e dal ministro dell'Istruzione Saffet Pascià il Darülfünun fu fondato ufficialmente; le prime lezioni erano già iniziate nel 1863. Secondo la voce \"Darülfünun\" del TDV l'istituzione passò di fatto all'insegnamento nel febbraio 1870, sotto la direzione di Hoca Tahsin Efendi, con le sezioni di filosofia-letteratura, scienze e diritto.", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["Inizio dei lavori della Mecelle-i Ahkâm-ı Adliyye", "8abdcbee"], "d": ["La Società della Mecelle, costituita sotto la presidenza di Ahmed Cevdet Pascià, presidente del Dîvân-ı Ahkâm-ı Adliyye, intraprese la preparazione di un codice civile fondato sul diritto hanafita. Secondo la voce \"Mecelle-i Ahkâm-ı Adliyye\" del TDV l'opera, composta di sedici libri e 1851 articoli, fu completata nell'ultimo fascicolo il 15 settembre 1876 ed entrò in vigore; è considerata la prima codificazione del diritto islamico.", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["Messa in scena di \"Vatan yahut Silistre\", Nâmık Kemal inviato in esilio", "3861284c"], "d": ["Quando l'opera di Nâmık Kemal a tema patriottico fu messa in scena al Teatro di Gedikpaşa, gli spettatori si riversarono per le strade gridando \"Viva la patria, viva Kemal\". Secondo la voce \"Nâmık Kemal\" del TDV il governo, spaventato da questa manifestazione, chiuse il giornale İbret e il 6 aprile 1873 mandò Nâmık Kemal in esilio a Cipro (Famagosta) senza processo.", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["Morte sospetta di Abdülaziz", "85816692"], "d": ["Abdülaziz, trasferito per sua richiesta al Palazzo di Feriye dopo la deposizione (1° giugno 1876), il 4 giugno fu trovato nella sua stanza con le vene dei polsi tagliate. Una commissione medica di diciannove persone, che comprendeva anche i medici delle ambasciate, preparò un rapporto dal tenore ambiguo; la morte fu proclamata il 6 giugno sui giornali come suicidio. L'inchiesta fatta aprire da Abdülhamid II giunse invece alla convinzione che la morte non fosse un suicidio ma un omicidio e gli imputati furono giudicati nel 1881 dal Tribunale di Yıldız; la questione è ancora oggi discussa nella storiografia.", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["Destituzione ed esilio di Midhat Pascià dal gran visirato", "b5247b06"], "d": ["Il gran visir Midhat Pascià, architetto del Kanun-i Esasi, sei settimane dopo la proclamazione fu destituito da Abdülhamid II ed esiliato all'estero in una notte. Secondo la voce Midhat Paşa del TDV İslâm Ansiklopedisi, la destituzione è collegata al disagio del sultano per le disposizioni della costituzione che limitavano i suoi poteri. Il pascià si recò prima a Napoli, poi in varie città d'Europa.", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["Abd al-Aziz b. Saud riprende Riyad ai Rashidi", "75eb8830"], "d": ["Il giovane Abd al-Aziz della dinastia Saud, che dieci anni prima era andato in esilio in Kuwait, con un piccolo distaccamento fece irruzione a Riyad e, uccidendo il vice-governatore degli Al Rashid (Shammar), si impadronì della città. Secondo la voce Riyad del TDV İslâm Ansiklopedisi il progressivo indebolimento dei Rashidi e la loro incapacità di inviare rinforzi in città facilitarono il successo di questa incursione; l'episodio è considerato il momento di fondazione del Secondo Stato saudita, che nei trent'anni successivi avrebbe costituito il nucleo dell'odierna Arabia Saudita.", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["Ingresso dell'Hareket Ordusu a Istanbul", "41c8304c"], "d": ["L'Hareket Ordusu (Esercito d'Azione), partito da Salonicco e composto in maggioranza da unità legate al Comitato Unione e Progresso, entrò a Istanbul per reprimere la rivolta del 31 Mart. Secondo la voce Hareket Ordusu del TDV İslâm Ansiklopedisi il comando fu assunto da Mahmud Şevket Pascià, mentre capo di stato maggiore fu Kolağası Mustafa Kemal. Dopo brevi scontri l'ordine in città fu ristabilito.", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["Scioglimento dell'ultimo Meclis-i Mebusan ottomano", "2b709269"], "d": ["Dopo l'occupazione ufficiale di Istanbul da parte delle forze dell'Intesa e l'arresto di molti deputati, il Meclis-i Mebusan divenne incapace di lavorare e fu sciolto ufficialmente con l'irade di Mehmed VI. Secondo la voce Meclis-i Mebusan del TDV İslâm Ansiklopedisi questo scioglimento simboleggiò la fine di fatto della tradizione parlamentare costituzionale ottomana. La chiusura rafforzò la necessità di riunire ad Ankara una nuova assemblea nazionale.", "4caabf36"]},
"OLAYLAR_EK7:1920-04-23:0":{"b": ["Apertura della Grande Assemblea Nazionale di Turchia", "6eab539d"], "d": ["Dopo lo scioglimento del Meclis-i Mebusan a Istanbul i deputati si riunirono ad Ankara e aprirono la Grande Assemblea Nazionale di Turchia (GANT), e Mustafa Kemal Pascià fu eletto presidente dell'assemblea. Secondo la voce Türkiye Büyük Millet Meclisi del TDV İslâm Ansiklopedisi l'assemblea ebbe un carattere straordinario, riunendo in sé sia il potere legislativo sia quello esecutivo. Questa apertura fu il punto di svolta in cui il centro politico e istituzionale della lotta nazionale si spostò ad Ankara. Con questo fatto 124 località (le regioni della Turchia non occupate), tra cui Konya, Sivas, Kayseri, Eskişehir, Erzurum, Trabzon, Samsun, Diyarbakır, Van, Malatya, Denizli e Isparta, entrarono sotto l'amministrazione del governo della GANT.", "47a80fa7"]},
"OLAYLAR_EK8:1460-01-01:0":{"b": ["Conquista della fortezza di Zvornik (İzvornik)", "657c465a"], "d": ["La fortezza di Zvornik, sulla riva della Drina, fu conquistata dagli Ottomani nel 1460. Secondo il TDV İslâm Ansiklopedisi, per la sua posizione favorevole dal punto di vista amministrativo e militare fu fatta dapprima centro di kaza, nel 1480 divenne centro del sanjak con lo stesso nome e nel 1491, fortificata con mura di pietra, si trasformò in un importante centro amministrativo-commerciale con sei moschee, otto tekke e bagni.", "160e9a01"]},
"OLAYLAR_EK8:1468-01-01:0":{"b": ["Morte di Qasim Khan, ascesa al trono di Daniyal Khan (Khanato di Qasim)", "522fd0fd"], "d": ["Con la morte nel 873/1468 del fondatore del khanato Qasim Khan gli succedette il figlio Daniyal; Daniyal regnò fino al 1486.", "6217828f"]},
"OLAYLAR_EK8:1509-02-03:0":{"b": ["Battaglia navale di Diu — supremazia del Portogallo nell'Oceano Indiano", "1778d347"], "d": ["La flotta sostenuta dai Mamelucchi di Malik Ayaz, che governava la regione a nome del Sultanato del Gujarat, subì una grave sconfitta al largo di Diu di fronte alla flotta del governatore generale portoghese Francisco de Almeida, che cercava di stabilire una base di rifornimento su queste coste. Questa sconfitta diede al Portogallo una supremazia navale duratura nell'Oceano Indiano e spezzò la potenza navale mamelucco-gujarati; è considerata l'inizio dello squilibrio di forze che costituisce lo sfondo della lotta tra Mar Rosso e Oceano Indiano ereditata dagli Ottomani dopo il 1517 (difesa di Gedda, assedio di Diu del 1538).", "88e4e561"]},
"OLAYLAR_EK8:1526-01-01:0":{"b": ["Rivolta di Kalender Shah", "f60f6ca4"], "d": ["Per le difficoltà finanziarie in Anatolia, il malcontento per i nuovi riordinamenti amministrativi e l'effetto della propaganda safavide, grandi tribù turcomanne come Çiçekli, Akça Koyunlu, Masadlı e Bozoklu e i gruppi rimasti della precedente rivolta di Baba Zünnûn si riunirono intorno a Kalender Shah, raggiungendo una forza di circa trentamila persone. I ribelli sconfissero dapprima il beylerbey di Rum; quando il gran visir Makbul İbrâhim Pascià raccolse soldati e promise loro i diritti, il sostegno a Kalender si dissolse e la rivolta fu repressa nei dintorni di Elbistan; Kalender Shah e Veli Dündar furono uccisi nel giugno 1527.", "a12c9471"]},
"OLAYLAR_EK8:1554-08-22:0":{"b": ["Conquista di Shahrizor — presa della fortezza di Zalm", "4320d9b8"], "d": ["Durante la campagna di Nakhchivan di Solimano il Legislatore il beylerbey di Baghdad Osman Pascià era stato incaricato di prendere la zona di Shahrizor; Baltacı Mehmed Pascià, divenuto beylerbey di Baghdad dopo la sua morte, assediò la fortezza centrale della regione, Zalm, e la prese il 22 agosto 1554 (23 Ramazan 961). Così il bacino di Shahrizor sul versante occidentale dello Zagros entrò sotto amministrazione ottomana e fu assicurato il collegamento tra Baghdad e il Kurdistan; la regione fu fatta dapprima sanjak e data a Murad Bey. Nel 1563 il beylerbey Muzaffer Pascià costruì la fortezza di Gülanber come nuovo centro dell'eyalet; la fortezza sarebbe stata demolita nel 1623 per ordine di Shah Abbas e rifondata nel 1638 al tempo di Hüsrev Pascià.", "068e1ae8"]},
"OLAYLAR_EK8:1573-01-01:0":{"b": ["Conversione al cristianesimo del sovrano del Khanato di Qasim e sua rimozione dal khanato", "a1a8eeb9"], "d": ["Il sovrano a capo del khanato prese il nome di 'Semën (Simeone)' e si fece cristiano; i Russi, tenendo conto della reazione dei sudditi musulmani, lo tolsero dal khanato. Questa persona fu poco dopo proclamata da Ivan il Terribile, a Mosca, sovrano nominale con il titolo di 'gran principe dello zar e di tutta la Russia' (1575) — l'intreccio più eclatante tra il Khanato di Qasim e il trono di Mosca.", "123a7380"]},
"OLAYLAR_EK8:1577-01-01:0":{"b": ["Legame del sanjak del Fezzan con Tripoli — Murzuq e il crocevia carovaniero del Sahara", "2e6554a4"], "d": ["In seguito alla pressione del beylerbeylik di Tripoli, il Fezzan, crocevia carovaniero del Sahara, con centro Murzuq, accettò la dipendenza ottomana. Secondo la voce Fizan del TDV İslâm Ansiklopedisi, la dinastia degli Awlad Muhammad, che governava la regione, fu lasciata libera nelle questioni interne a condizione di pagare regolarmente le imposte; il Fezzan fu organizzato come sanjak dipendente dall'eyalet di Tripoli, preso nel 1551. Così il commercio di schiavi, oro e cammelli lungo la linea Tripoli-Murzuq-Bornu entrò sotto il controllo ottomano. Questa amministrazione indiretta sarebbe passata nel 1711 ai Karamanlı e nel 1842 all'organizzazione diretta in kaza.", "dff1c8b1"]},
"OLAYLAR_EK8:1586-01-01:0":{"b": ["Nakhchivan e Ordubad entrano sotto amministrazione ottomana", "24d939b3"], "d": ["Dopo la presa di Erevan nel 1583 e la sua trasformazione in centro di beylerbeylik, le forze scese lungo la valle dell'Aras verso sudest legarono all'amministrazione ottomana Nakhchivan e Ordubad; le due città divennero sanjak del nuovo eyalet di Erevan. Secondo la voce Nahcıvan del TDV İslâm Ansiklopedisi, la prima amministrazione ottomana duratura nella città fu stabilita durante questa guerra — nella campagna di Nakhchivan del 1553 la città era stata presa ma solo saccheggiata e abbandonata. Così la via dell'esercito tra Erevan e Tabriz fu aperta e nel settembre dello stesso anno fu possibile entrare a Tabriz. Shah Abbas avrebbe ripreso Nakhchivan nel 1603.", "270c0faa"]},
"OLAYLAR_EK8:1603-03-01:0":{"b": ["Rivolta di Deli Hasan Pascià e pacificazione con il beylerbeylik di Bosnia", "144f3f2d"], "d": ["Dopo la morte di Karayazıcı Abdülhalim, capo dei Celâli, nel 1602, il fratello Deli Hasan, messosi alla testa del movimento, approfittando della libertà di movimento che le guerre austriache in corso concedevano ai gruppi celâli invase Kütahya e marciò su Afyonkarahisar. In questo periodo, in cui lo Stato era impegnato contemporaneamente sui fronti austriaco e iraniano, la questione fu risolta 'con dolcezza': a Deli Hasan furono dati il rango di pascià e il beylerbeylik di Bosnia e il movimento di rivolta fu chiuso ufficialmente nel 1603.", "22ea1f34"]},
"OLAYLAR_EK8:1609-01-01:0":{"b": ["Presa della città di Kasimov da parte delle forze russe, Ural Muhammad Khan", "b3f0bd34"], "d": ["Come riflesso del Periodo dei Torbidi (Smuta) in Russia, le forze russe assediarono e presero la città di Kasimov e ne passarono a fil di spada la maggior parte degli abitanti. Ural Muhammad, a capo del khanato, era stato preso di mira perché aveva sostenuto il Falso Dmitrij II; l'anno seguente (1610) fu ucciso anch'egli in un complotto.", "3583477d"]},
"OLAYLAR_EK8:1637-06-18:0":{"b": ["Perdita della fortezza di Azak a favore dei cosacchi del Don", "ba068b2f"], "d": ["I cosacchi del Don presero la fortezza di Azak, che assediavano dal 21 aprile 1637, due mesi dopo; la fortezza, porta nordorientale del Mar Nero e chiave del commercio del Don, uscì per la prima volta dalle mani ottomane. Secondo la voce Azak del TDV İslâm Ansiklopedisi i cosacchi presero la fortezza nel 1637, nel 1641 resistettero al grande assedio di tre mesi al comando di Deli Hüseyin Pascià e solo nel 1642, con l'arrivo del khan di Crimea Mehmed Giray, evacuarono la fortezza. Lo Stato era allora impegnato sul fronte di Baghdad; il fatto che la fortezza non sia stata tenuta per cinque anni è la prima crepa nella qualità del Mar Nero di 'lago ottomano'.", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["Ripresa di Lemno e Samotracia", "c445553b"], "d": ["Dopo la liberazione di Bozcaada il 31 agosto 1657 Köprülü Mehmed Pascià diresse la flotta verso nord e riprese Lemno e Samotracia, che Venezia teneva da sedici mesi. Secondo la voce Limni del TDV İslâm Ansiklopedisi l'isola era passata a Venezia nel luglio 1656 ed era stata ripresa nel novembre 1657. Così il blocco veneziano all'imboccatura dei Dardanelli fu completamente spezzato e la via del grano di Istanbul fu di nuovo messa in sicurezza; questo è il guadagno più concreto del primo anno in cui il gran visir era giunto con poteri straordinari.", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["Perdita di Knin a favore di Venezia — cade la fortezza di confine dalmata di 166 anni", "252406b7"], "d": ["Nella guerra aperta su più fronti dopo la disfatta di Vienna del 1683 le forze veneziane avanzarono nell'interno della Dalmazia. Knin, assediata dal generale di Dalmazia Girolamo Cornaro, dopo un assedio di dodici giorni fu consegnata dal beylerbey Mehmed Pascià. Knin era la fortezza chiave della linea di confine dalmata conquistata nel 1522 da Gazi Hüsrev Bey e rimasta per 166 anni in mano ottomana; la sua perdita aprì in gran parte la regione a Venezia.", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["Ripresa di Bassora dall'occupazione iraniana", "5b10c5c1"], "d": ["Bassora, presa nel 1776 da Sadiq Khan, fratello di Karim Khan Zand, fu evacuata quando dopo la morte di Karim Khan il 2 marzo 1779 iniziò in Iran la lotta per il trono; Sadiq Khan tornò in Iran con la pretesa al sultanato. La città, rimasta per breve tempo in mano alla tribù dei Muntafiq, entrò di nuovo sotto amministrazione ottomana. L'ex mütesellim Süleyman Ağa, tornato da Shiraz, chiese il governatorato di Bassora e divenne, con il nome di Büyük Süleyman Pascià, governatore di Bassora, Baghdad e Shahrizor. Il commercio del Golfo tornò sotto controllo ottomano; negli anni dell'occupazione una parte del commercio si era spostata in Kuwait e dal 1778 anche la posta del deserto partiva dal Kuwait.", "2f14ff54"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["Morte di Timur Shah, ascesa al trono di Zaman Shah (Stato durrani)", "c3effdb2"], "d": ["Con la morte di Timur Shah, che per oltre vent'anni aveva consolidato il paese dall'interno, i tre fratelli governatori di Kandahar-Herat-Kabul si contesero il trono; il governatore di Kabul, che teneva la capitale, Zaman Shah, divenne shah il 20 maggio 1793. Questa crisi di successione è l'inizio di fatto del processo di frammentazione della dinastia.", "4b3d7d19"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["ʻAi Noa — fine del sistema tradizionale del kapu alle Hawaii", "0b10e1d8"], "d": ["Sei mesi dopo la morte di Kamehameha I il nuovo re Liholiho, con il sostegno della madre Kaʻahumanu, infranse deliberatamente il divieto di mangiare separatamente uomini e donne (ʻaikapu). Quest'atto, noto come 'ʻAi Noa' (mangiare libero), pose fine ufficialmente al tradizionale sistema religioso-giuridico del kapu; gli antichi templi (heiau) sulle isole furono presto abbattuti. È la maggiore frattura religioso-politica prima dell'arrivo dei missionari occidentali (1820).", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["Protocollo di Londra — riconoscimento dell'indipendenza della Grecia", "4c7b4b72"], "d": ["Il protocollo firmato a Londra da Inghilterra, Francia e Russia, superando l'autonomia prevista dal Trattato di Edirne, riconobbe la Grecia come Stato INDIPENDENTE. Disposizioni: la penisola di Morea, l'Attica e Negroponte con le Cicladi furono lasciate al nuovo Stato; il confine fu tracciato sulla linea Arta-Volos; fu stabilito il pagamento di un'indennità all'Impero ottomano; la forma di governo dello Stato fu fissata come 'monarchia indipendente'. È il PRIMO Stato indipendente staccatosi dall'Impero e ha stabilito l'esempio giuridico delle successive indipendenze balcaniche. Alla Grecia, la cui indipendenza fu riconosciuta con il Protocollo di Londra, furono incluse le isole Cicladi (Nasso, İstendil, Santorini, Paro, Mylos, Siro, Micono ecc.).", "920bfab9"]},
"OLAYLAR_EK8:1835-01-01:0":{"b": ["Abdallah b. Rashid prende l'emirato di Ha'il — fondazione della dinastia Shammar (Rashidi)", "fb513b8a"], "d": ["Con la caduta di Dir'iyya per opera delle forze di Mehmed Ali Pascià nel 1818 la regione del Jebel Shammar uscì dal dominio saudita e l'emirato rimase in mano alla famiglia Ibn Ali. Abdallah b. Rashid, che sosteneva il ristabilimento del dominio ottomano, vinse nel 1835, insieme al fratello Ubayd, la lotta intrapresa contro la famiglia Ibn Ali, prese l'emirato di Ha'il e stabilì il dominio della dinastia Rashidi.", "631e33a9"]},
"OLAYLAR_EK8:1840-10-08:0":{"b": ["Proclamata la prima costituzione scritta delle Hawaii", "401a8a1d"], "d": ["Fu proclamata la prima costituzione scritta completa del regno; questo documento, che limitava il potere del re e istituiva un'assemblea rappresentativa, trasformò le Hawaii in una monarchia costituzionale.", "a32cdab2"]},
"OLAYLAR_EK8:1887-07-06:0":{"b": ["Costituzione della Baionetta — ridotti i poteri del re Kalākaua", "4953363b"], "d": ["Un gruppo armato di milizia, minacciando il re Kalākaua, lo costrinse a firmare una nuova costituzione che riduceva in gran parte i poteri del regno; il documento è noto come 'Costituzione della Baionetta' (Bayonet Constitution) e pose di fatto il trono sotto il controllo dell'élite di coloni bianchi.", "cc95eabb"]},
"OLAYLAR_EK8:1893-02-18:0":{"b": ["Morte di George Tupou I, ascesa al trono di George Tupou II (Tonga)", "b56e2b32"], "d": ["Con la morte del re fondatore George Tupou I salì al trono il pronipote George Tupou II; l'incoronazione si tenne il 17 marzo 1893 a Nukuʻalofa.", "01fe9fa1"]},
"OLAYLAR_EK8:1893-09-19:0":{"b": ["La Nuova Zelanda diventa il primo paese autonomo a concedere il voto alle donne", "0d277cde"], "d": ["Con la nuova Legge Elettorale firmata dal governatore Lord Glasgow la Nuova Zelanda divenne il primo paese autonomo al mondo a riconoscere alle donne il diritto di voto nelle elezioni parlamentari.", "ba9b7f63"]},
"OLAYLAR_EK8:1894-07-04:0":{"b": ["Proclamata la Repubblica delle Hawaii", "4346bd5d"], "d": ["Nel 1893 i cospiratori che avevano rovesciato la regina Liliuokalani trasformarono il governo provvisorio in una repubblica ufficiale; Sanford Dole fu proclamato presidente. Questo regime intermedio durò fino all'annessione agli Stati Uniti del 1898.", "d1a76858"]},
"OLAYLAR_EK8:1901-06-11:0":{"b": ["I confini della Nuova Zelanda si ampliano fino a comprendere le Isole Cook e Niue", "d0370a33"], "d": ["I confini della Nuova Zelanda furono ampliati in modo da comprendere le Isole Cook (Rarotonga, Aitutaki e le isole meridionali con le Isole Cook settentrionali) e Niue; queste isole divennero territori legati alla Nuova Zelanda.", "464148bd"]},
"OLAYLAR_EK8:1918-04-05:0":{"b": ["Morte di George Tupou II, ascesa al trono di Sālote Tupou III (Tonga)", "a3084f3b"], "d": ["George Tupou II morì di tubercolosi; la figlia diciottenne Sālote fu proclamata regina il giorno seguente e l'incoronazione si tenne l'11 ottobre 1918.", "a63672b5"]},
"OLAYLAR_EK8:1920-04-26:0":{"b": ["Proclamata la Repubblica Popolare del Khorezm", "0a6b79f9"], "d": ["Dopo il rovesciamento del khan di Khiva in seguito alla Rivoluzione d'Ottobre del 1917 fu proclamata la Repubblica Popolare del Khorezm.", "1934b071"]},
"OLAYLAR_EK8:1920-08-10:0":{"b": ["Trattato di Sèvres — testo di spartizione dell'Impero", "64980d7b"], "d": ["Il testo firmato dal governo ottomano con gli Stati dell'Intesa che di fatto liquidava l'Impero. Disposizioni: Tracia orientale e regione di Smirne alla Grecia; nell'Anatolia orientale erano previsti un'Armenia indipendente e un Kurdistan autonomo; la Siria fu lasciata alla Francia, Iraq e Palestina all'Inghilterra come mandati; gli Stretti furono ceduti a una commissione internazionale; l'esercito fu ridotto a 50.700 uomini, le capitolazioni tornarono e le finanze furono poste sotto controllo dell'Intesa. La Grande Assemblea Nazionale di Ankara NON LO RICONOBBE AFFATTO e dichiarò traditori della patria i firmatari; il testo non entrò in vigore e fu sostituito nel 1923 da Losanna. Per questo non ha corrispondenza sulla mappa — Sèvres non fu mai applicato giuridicamente.", "c9b2648b"]},
"OLAYLAR_EK8:1920-09-02:0":{"b": ["L'Armata Rossa entra nella città di Bukhara — deposto l'ultimo emiro Alim Khan", "f8f5bfcf"], "d": ["L'Armata Rossa entrò nella città di Bukhara il 2 settembre 1920 e l'ultimo emiro mangita Alim Khan fu allontanato dal trono. L'emiro si ritirò a Dušanbe, nell'est del paese, e da lì per mezzo anno diresse la lotta contro i Sovietici; l'Armata Rossa prese Dušanbe il 21 febbraio 1921, l'emiro passò più a est e di lì in Afghanistan. Il khanato fu abolito ufficialmente il 6 ottobre 1920 (cfr. Repubblica Popolare Sovietica di Bukhara).", "19580033"]},
"OLAYLAR_EK8:1920-10-08:0":{"b": ["Proclamata la Repubblica Popolare Sovietica di Bukhara", "ef579627"], "d": ["Dopo che l'Armata Rossa, il 28-31 agosto 1920, ebbe abbattuto l'Emirato di Bukhara e fatto fuggire l'emiro Alim Khan nella Bukhara orientale, fu proclamata la Repubblica Popolare Sovietica di Bukhara sotto la presidenza di Faizullah Khodzhaev.", "690bfb2f"]},
"OLAYLAR_EK8:1921-08-14:0":{"b": ["La Repubblica Popolare di Tannu Tuva proclama l'indipendenza", "8710ea3d"], "d": ["Sotto la guida del Partito Rivoluzionario Popolare Tuvano fu proclamata l'indipendenza; il primo articolo della prima costituzione stabiliva che lo Stato agiva 'nelle relazioni internazionali sotto la protezione della Russia sovietica'. Con questo fatto Kyzyl (Belotsarsk, Tannu-Tuva) passò alla Repubblica Popolare di Tannu Tuva.", "dc0ac64a"]},
"OLAYLAR_EK8:1921-09-01:0":{"b": ["Adottata la nuova costituzione della Repubblica Popolare Sovietica di Bukhara", "fb17bf39"], "d": ["Fu adottata una nuova costituzione che, a differenza della costituzione russa del 1918, consentiva la proprietà privata della terra e della produzione e riconosceva il diritto di voto anche ai non proletari (esclusi i parenti dell'emiro deposto e i grandi proprietari terrieri).", "91bf1a32"]},
"OLAYLAR_EK8:1921-09-05:0":{"b": ["Trasformazione in Repubblica Socialista Sovietica del Khorezm", "14a1d26f"], "d": ["Il paese cambiò nome e status e divenne Repubblica Socialista Sovietica del Khorezm; la struttura amministrativo-legale fu riordinata secondo il sistema sovietico.", "e3e9b939"]},
"OLAYLAR_EK8:1922-03-03:0":{"b": ["Il governo di Tannu Tuva entra di fatto in funzione", "22ea1516"], "d": ["Il governo costituito dopo la prima riunione del partito del febbraio 1922 entrò di fatto in funzione.", "3b3c6c39"]},
"OLAYLAR_EK8:1923-10-12:0":{"b": ["Si riunisce il primo Gran Khural di Tannu Tuva", "80fe15f2"], "d": ["Si riunì il primo Gran Khural (Assemblea Popolare) del paese; è la prima grande riunione rappresentativa nel processo di istituzionalizzazione dello Stato.", "e8cf06ac"]},
"OLAYLAR_EK8:1924-01-01:0":{"b": ["Fine della RSS del Khorezm e della Repubblica Popolare Sovietica di Bukhara con la delimitazione nazionale — fondazione delle RSS di Uzbekistan e Turkmenistan", "e8c8ab4f"], "d": ["Con la decisione sovietica di 'delimitazione nazionale' (nacional'no-territorial'noe razmeževanie) la Repubblica Socialista Sovietica del Khorezm e la Repubblica Popolare Sovietica di Bukhara furono abolite; i loro territori furono spartiti tra le nuove Repubbliche Socialiste Sovietiche di Uzbekistan e Turkmenistan (la parte orientale di Khiva all'Uzbekistan, la parte occidentale al Turkmenistan). Voce `harizm` del TDV: '1924’te Hîve Hanlığı’nın doğu kesimleri Özbekistan Sovyet Sosyalist Cumhuriyeti’ne, batı tarafı da Türkmenistan Sovyet Sosyalist Cumhuriyeti’ne bırakıldı.' — dà solo l'anno.", "58053c38"]},
"OLAYLAR_EK9:1427-01-01:0":{"b": ["Vendita di Alanya al sultano mamelucco Barsbay", "c8bd35f2"], "d": ["Alanya, presa nel 1293 dal Karamanoğlu Mecdüddin Mahmud Bey, era divenuta un beylicato separato governato da un ramo dei Karamanidi; Ibn Battuta registra nel 1333 che l'amministrazione era in mano al Karamanoğlu Yûsuf Bey. Karaman b. Savcı Bey nel 1427 vendette la città per cinquemila monete d'oro al sultano mamelucco Barsbay e Alanya entrò sotto amministrazione mamelucca. Questo porto chiave del Mediterraneo divenne così un ostacolo in mano mamelucca sulla via che si apriva agli Ottomani verso sud; nel 1471, quando Gedik Ahmed Pascià la assediò, l'ultimo bey Kılıçarslan consegnò la città.", "9be5efe7"]},
"OLAYLAR_EK9:1741-06-12:0":{"b": ["Presa di Tabarka ai Genovesi — fine della concessione del corallo dei Lomellini", "b1f33eb5"], "d": ["Dopo l'accordo di Carlo V con il bey di Tunisi nel 1544 la famiglia genovese dei Lomellini si era stabilita nell'isola di Tabarka e per duecento anni aveva tenuto la concessione del corallo; l'isola rimase, in mezzo alla Tunisia ottomana, come avamposto commerciale cristiano. Ali Pascià della dinastia husainide, saputo del tentativo della famiglia di sbarazzarsi dell'isola, inviò forze e il 12 giugno 1741 prese l'isola; circa millecinquecento cristiani furono trasferiti in Tunisia. Da questa data Tabarka entrò sotto l'amministrazione dell'ocak di Tunisi.", "93c8bd7b"]},
"OLAYLAR_EK9:1798-07-21:0":{"b": ["Battaglia delle Piramidi e presa del Cairo da parte dei Francesi", "3ddd6b96"], "d": ["Napoleone marciò da Alessandria verso sud lungo il Nilo e il 21 luglio 1798 a Imbaba, di fronte a Giza, affrontò la cavalleria kölemen di Murad Bey. La fanteria francese in quadrato spezzò le cariche di cavalleria; l'esercito kölemen si disperse e il Cairo due giorni dopo si arrese senza resistenza. Murad Bey si ritirò nell'Alto Egitto, İbrâhim Bey in Siria. I Francesi istituirono al Cairo un dîvân e cercarono di condurre l'amministrazione per mano degli ulema; nell'ottobre 1798 e nel marzo 1800 scoppiarono due grandi rivolte del Cairo.", "ad9a3113"]},
"OLAYLAR_EK9:1799-03-18:0":{"b": ["Assedio di Acri da parte di Napoleone — arresto della campagna di Siria", "d2a947ad"], "d": ["Napoleone, che voleva disperdere le forze preparate dagli Ottomani per riprendere l'Egitto, all'inizio del 1799 marciò in Siria; prese al-Arish il 18 febbraio, Giaffa a marzo e il 18 marzo 1799 assediò Acri. La difesa di Cezzâr Ahmed Pascià e il sostegno dal mare dell'ammiraglio inglese Sidney Smith spezzarono per due mesi l'assedio; poiché le artiglierie d'assedio erano state catturate in mare, le mura non poterono essere superate. Napoleone si ritirò a maggio e questa sconfitta fu il punto estremo dell'occupazione francese.", "288b9bd9"]},
"OLAYLAR_EK9:1832-11-22:0":{"b": ["Fondazione dello Stato dell'emiro Abd al-Qadir — centralizzazione della resistenza nell'Algeria occidentale", "9e482383"], "d": ["La resistenza dispersa dopo la caduta di Algeri si raccolse intorno al giovane Abd al-Qadir, figlio dello sceicco qadiri Muhyi al-Din; il 22 novembre 1832, presso Mascara, i capi tribù gli prestarono giuramento di fedeltà con il titolo di 'emir dei credenti'. La struttura da lui creata non era un'alleanza tribale ma uno Stato regolare: aveva una zecca, una fabbrica di polvere da sparo, un sistema fiscale e una capitale a Tagdempt. La Francia riconobbe ufficialmente il suo dominio con il Trattato della Tafna del 1837. Abd al-Qadir si pose sotto la sovranità non degli Ottomani ma del sultano del Marocco Abd al-Rahman; dunque questi territori dopo il 1832 non sono sotto dipendenza ottomana. Si arrese il 23 dicembre 1847 e anche l'Impero ottomano nello stesso anno dichiarò la fine dei propri diritti sull'Algeria.", "ee2bb181"]},
"OLAYLAR_EK9:1837-10-13:0":{"b": ["Caduta di Costantina — fine del beylicato dell'Algeria orientale", "159fed36"], "d": ["Dopo la caduta di Algeri nel 1830 il beylerbeylik orientale non si dissolse: l'ultimo bey, Ahmed, continuò la propria amministrazione a Costantina e dichiarò di agire a nome ottomano. La prima campagna dei Francesi nel 1836 si concluse con una disfatta; la seconda campagna assediò la città il 6 ottobre 1837, il comandante Damrémont morì il 12 ottobre per un colpo di cannone e il 13 ottobre, superate le mura, la città fu presa strada per strada. Ahmed Bey si ritirò sui monti e si arrese solo nel 1848. Questa data è la fine di fatto dell'amministrazione ottomano-turca di trecento anni nell'Algeria orientale.", "41606785"]},
"OLAYLAR_EK9:1840-01-01:0":{"b": ["Conquista della regione di Taka e fondazione di Kassala", "cc3e0631"], "d": ["Ahmed Pascià Abu Widan, governatore del Sudan, nel 1840 legò all'amministrazione egiziana la regione di Taka tra i fiumi Atbara e Gash e fondò la città di Kassala come quartier generale militare. La città divenne centro di mudiriyya che controllava la via carovaniera tra Sennar e Suakin e la fascia di confine abissina.", "b7898c36"]},
"OLAYLAR_EK9:1841-01-01:0":{"b": ["Occupazione francese di Mascara — perdita della capitale di Abd al-Qadir", "bd363c05"], "d": ["Con l'arrivo di Bugeaud al governatorato nel 1841 la strategia francese cambiò: invece di tenersi sulla costa, occupare una a una le città dell'interno. Le colonne mobili partite da Orano, Mostaganem e Medea presero i centri dello Stato regolare di Abd al-Qadir; Mascara, vera capitale con la zecca, la fabbrica di polvere da sparo e i granai, era la più importante. L'emiro rinunciò allora a stabilire un centro fisso e trasformò il proprio esercito nel campo nomade detto 'smala'.", "b5e65ffc"]},
"OLAYLAR_EK9:1843-01-01:0":{"b": ["Occupazione della valle dello Chelif e di Tenes — fondazione di Orléansville", "e1eeeb68"], "d": ["Per poter inseguire Abd al-Qadir i Francesi nell'aprile 1843 fondarono nel mezzo della valle dello Chelif una nuova città, Orléansville; nello stesso anno fu occupato anche il porto costiero di Tenes. Così il corridoio interno tra Algeri e Orano entrò sotto controllo francese e la resistenza sui monti del Dahra fu accerchiata. Il 16 maggio dello stesso anno il campo nomade di Abd al-Qadir, la 'smala', fu trovato per caso e disperso.", "67e95822"]},
"OLAYLAR_EK9:1843-06-12:0":{"b": ["Fondazione del campo fortificato di Sidi Bel Abbès", "fb33ec29"], "d": ["Bugeaud il 12 giugno 1843 diede al generale Bedeau l'ordine di costruire a Sidi Bel Abbès un campo fortificato con fossato e mura; i lavori iniziarono il 18 giugno e nel novembre dello stesso anno vi si stabilì un battaglione della Legione Straniera. Il campo divenne una base permanente che controllava la pianura interna tra Orano e Tlemcen.", "aab075d5"]},
"OLAYLAR_EK9:1844-01-01:0":{"b": ["Passaggio di Nedroma e della fascia di confine con il Marocco al controllo francese", "61d821f3"], "d": ["Dopo il ritiro di Abd al-Qadir in Marocco nel 1843, Nedroma e la costa di Trara, a nordovest di Tlemcen, entrarono sotto controllo francese. La battaglia dell'Isly del 14 agosto 1844 sconfisse l'esercito marocchino e il confine tra i due paesi fu tracciato con la Convenzione di Lalla Maghnia del 18 marzo 1845; Nedroma rimase sul lato algerino di questa linea.", "0456a776"]},
"OLAYLAR_EK9:1852-12-04:0":{"b": ["Caduta di Laghouat — apertura della porta del Sahara", "b161b32c"], "d": ["Il generale Pélissier con una forza di seimila uomini assediò Laghouat il 21 novembre 1852 e il 4 dicembre la città cadde con un sanguinoso assalto. Laghouat era una città-oasi che teneva il passaggio tra il Tell e il Sahara; la sua caduta aprì l'avanzata francese alle vie carovaniere del deserto e preparò la strada all'assoggettamento a imposta della confederazione del Mzab entro un anno.", "049b3d0a"]},
"OLAYLAR_EK9:1872-01-01:0":{"b": ["Annessione all'Egitto della regione dei Bogos (Keren)", "b2ab83ce"], "d": ["Werner Munzinger Pascià, governatore della provincia di 'Sudan orientale e costa del Mar Rosso' fondata dal khedivé İsmâil sulla costa occidentale del Mar Rosso, nel 1872 legò all'Egitto la regione dei Bogos, abitata dal popolo Bilen, con il centro Keren. Fu l'avanzata più duratura dell'Egitto sul bordo dell'altopiano abissino e diede inizio a una controversia di confine di dodici anni con l'Abissinia.", "e52afaf4"]},
"OLAYLAR_EK9:1874-11-02:0":{"b": ["Annessione del Sultanato del Darfur all'Egitto — Zubayr Pascià entra a El Fasher", "f41268ed"], "d": ["Zubayr Rahma Pascià, rafforzato dal commercio di avorio e schiavi, con forze dotate di fucili Remington il 25 ottobre 1874 disperse a Manawashi l'esercito Fur; il sultano Ibrahim morì in battaglia. Zubayr il 2 novembre entrò a El Fasher senza combattere e il regno della dinastia Keira, in corso dal 1603, terminò di fatto. Il Darfur fu così aggregato alle province sudanesi dell'Egitto di Kavala; ma la resistenza della famiglia Keira sulle montagne continuò fino al 1891.", "b9679678"]},
"OLAYLAR_EK9:1882-01-01:0":{"b": ["Annessione delle oasi del Mzab (Ghardaïa)", "9372959f"], "d": ["Le città ibadite del Mzab nel 1852 avevano accettato di pagare le imposte alla Francia ma avevano conservato la propria amministrazione interna; trent'anni dopo, nel 1882, la regione fu annessa direttamente ai territori francesi e Ghardaïa fu legata all'amministrazione militare. Così terminò giuridicamente anche l'ultima fascia autonoma del Sahara settentrionale.", "8ced1a9f"]},
"OLAYLAR_EK9:1882-07-11:0":{"b": ["Bombardamento di Alessandria e sbarco inglese", "18d57bf8"], "d": ["Quando il movimento di ufficiali guidato da Urabi Pascià prese il controllo del khedivé, l'Inghilterra intervenne con il pretesto della sicurezza della via di Suez. La flotta dell'ammiraglio Seymour l'11-12 luglio 1882 bombardò i forti costieri di Alessandria; dopo l'incendio e il saccheggio scoppiati in città, il 15 luglio le truppe inglesi sbarcarono. L'Impero ottomano non poté impedire questa operazione in una provincia di cui era giuridicamente sovrano e lasciò senza risposta anche l'invito a partecipare all'intervento. Così fu compiuto il primo passo dell'occupazione destinata a durare trentadue anni.", "d828a872"]},
"OLAYLAR_EK9:1882-09-13:0":{"b": ["Battaglia di Tell el-Kebir — dispersione dell'esercito di Urabi", "8e38fecf"], "d": ["Wolseley, sbarcate le sue forze a Ismailia attraverso il Canale di Suez e marciando attraverso il deserto, all'alba del 13 settembre 1882 attaccò di sorpresa le trincee egiziane a Tell el-Kebir; la battaglia finì in un'ora. Urabi si arrese il giorno seguente e la cavalleria inglese entrò al Cairo lo stesso giorno. Da questa data le finanze, l'esercito e gli affari esteri dell'Egitto passarono di fatto al controllo inglese; la sovranità ottomana continuò invece giuridicamente fino al 1914.", "a399d51c"]},
"OLAYLAR_EK9:1883-06-08:0":{"b": ["Convenzione di La Marsa — completamento del protettorato sulla Tunisia", "71338640"], "d": ["Il Trattato del Bardo (Kasr Said) del 12 maggio 1881 aveva lasciato alla Francia gli affari esteri della Tunisia ma l'amministrazione interna al bey; due anni dopo, la Convenzione di La Marsa firmata l'8 giugno 1883 pose sotto controllo francese anche le riforme finanziarie e amministrative e completò il protettorato. L'Impero ottomano continuò a sostenere la propria pretesa di sovranità sulla Tunisia e non riconobbe mai l'occupazione, ma non poté fare una contromossa di fatto. Così la Tunisia, ocak ottomano dal 1574, passò ufficialmente sotto protettorato francese.", "c04210c4"]},
"OLAYLAR_EK9:1883-11-05:0":{"b": ["Disfatta di Shaykan — distruzione dell'esercito di Hicks Pascià", "a0e08986"], "d": ["Hicks Pascià, ufficiale inglese in pensione che comandava la forza egiziana di circa diecimila uomini inviata dal Cairo, mentre avanzava senza acqua e senza guide nel deserto del Kordofan il 5 novembre 1883 fu accerchiato a Shaykan dalle forze del Mahdi e l'esercito fu quasi interamente annientato. Questa disfatta spezzò la spina dorsale dell'amministrazione egiziana in Sudan: in un mese si arresero Darfur e Bahr al-Ghazal, l'intero Kordofan passò al Mahdi. La strada verso la caduta di Khartum comincia da qui.", "c78a6d57"]},
"OLAYLAR_EK9:1883-12-23:0":{"b": ["Passaggio del Darfur alle forze del Mahdi — resa di Slatin Pascià", "6d8992d4"], "d": ["Il governatore generale del Darfur Slatin Pascià dal 1882 era alle prese con la sollevazione mahdista della tribù dei Rizeigat; ritenendo che le sconfitte dei suoi soldati fossero attribuite al suo essere cristiano, nel 1883 si fece apertamente musulmano e prese il nome di Abdülkadir. Dopo la distruzione dell'esercito di Hicks Pascià nel Kordofan nel novembre 1883 la resistenza non ebbe più senso e il 23 dicembre 1883 si arrese all'emiro Madibbo. Anche i piccoli presidi egiziani nel Darfur seguirono presto la stessa strada; l'amministrazione turco-egiziana di dieci anni terminò. Con questo fatto Jebel Marra (Darfur) passò all'amministrazione dello Stato del Mahdi.", "bd700253"]},
"OLAYLAR_EK9:1884-01-01:0":{"b": ["Passaggio di Zeila e della costa somala all'amministrazione inglese", "1d649502"], "d": ["Quando la rivolta del Mahdi fece crollare le guarnigioni egiziane in Sudan e sul Mar Rosso, il Cairo fu costretto a evacuare gli avamposti lontani sulla costa abissina. L'amministrazione inglese di Aden nel 1884 sbarcò truppe a Zeila e Berbera; l'anno seguente, con la firma di trattati di protezione con i capi tribù somali, fu fondato il Somaliland britannico. Zeila, legata all'eyalet di Abissinia dal 1559, andò così perduta.", "3c41ddf4"]},
"OLAYLAR_EK9:1884-01-15:0":{"b": ["Resa della guarnigione di El Fasher ai mahdisti", "68f0760d"], "d": ["Anche dopo la resa di Slatin del 23 dicembre 1883, la guarnigione egiziana nella fortezza di El Fasher resistette. La guarnigione, persi i pozzi in sette giorni di assedio, si arrese il 15 gennaio 1884; le armi furono deposte e la fortezza passò ai mahdisti.", "18287ab0"]},
"OLAYLAR_EK9:1884-06-03:0":{"b": ["Trattato di Hewett (Adua) — cessione dei Bogos all'Abissinia", "0de1b701"], "d": ["Quando la rivolta del Mahdi assediò le guarnigioni egiziane in Sudan, l'Inghilterra, per ottenere l'aiuto dell'Abissinia, il 3 giugno 1884 firmò ad Adua un trattato con Yohannes IV. Il secondo articolo del trattato restituiva i Bogos all'Abissinia, in cambio l'Abissinia avrebbe favorito l'evacuazione delle guarnigioni assediate attraverso Massaua. Keren uscì così dall'amministrazione egiziana di dodici anni; cinque anni dopo la regione sarebbe stata aggregata all'Eritrea italiana.", "b7e73617"]},
"OLAYLAR_EK9:1896-09-23:0":{"b": ["Ripresa di Dongola — inizio della campagna lungo il Nilo", "f63aa14f"], "d": ["Dopo la sconfitta degli Italiani ad Adua, l'Inghilterra fece marciare l'esercito egiziano verso sud lungo il Nilo al comando di Kitchener. Man mano che la ferrovia avanzava nel deserto il problema dei rifornimenti fu risolto e la provincia di Dongola fu ripresa il 23 settembre 1896. L'amministrazione del Mahdi di undici anni terminò qui; la campagna sarebbe durata altri due anni fino a raggiungere Omdurman.", "ef465d34"]},
"OLAYLAR_EK9:1898-09-02:0":{"b": ["Battaglia di Omdurman — caduta dello Stato del Mahdi", "28dff7b2"], "d": ["L'esercito anglo-egiziano di Kitchener, dotato di artiglieria e mitragliatrici, il 2 settembre 1898 davanti a Omdurman disperse in poche ore le forze del califfo Abdullahi al-Ta'aishi. Il giorno dopo si entrò a Khartum e fu issata la bandiera nel palazzo in cui tredici anni prima era stato ucciso Gordon. La capitale dello Stato del Mahdi cadde; il califfo fu ucciso alla fine del 1899 nell'operazione di inseguimento. Il dominio di fatto cambia di mano in questa data — il 19 gennaio 1899 è invece l'accordo che stabilisce la cornice giuridica dell'amministrazione. Con questa sconfitta dello Stato del Mahdi il Darfur (El Fasher, Nyala, Zalingei, Kutum ecc.) passò al Sultanato del Darfur rifondato da Ali Dinar.", "ad27827a"]},
"OLAYLAR_EK9:1899-01-19:0":{"b": ["Accordo del Condominio — amministrazione congiunta anglo-egiziana del Sudan", "8033c688"], "d": ["L'accordo firmato al Cairo quattro mesi dopo Omdurman legò il Sudan con il nome di 'Sudan anglo-egiziano' all'amministrazione congiunta dei due Stati: le due bandiere sarebbero state issate insieme e il governatore generale sarebbe stato nominato dal khedivé con il consenso dell'Inghilterra. Nella pratica l'amministrazione era interamente in mano inglese. L'Impero ottomano, sostenendo che i suoi diritti sul Sudan gli spettavano tramite l'Egitto, non fu parte dell'accordo e non lo riconobbe; ma di fatto ne rimase fuori. Con questo accordo i territori sudanesi a sud del 22° parallelo (Dongola, Khartum, Sennar, Kordofan, costa di Suakin ecc.) passarono all'amministrazione congiunta anglo-egiziana (Sudan anglo-egiziano).", "097331bb"]},
"OLAYLAR_EK9:1911-10-08:0":{"b": ["Sbarco italiano a Tobruk — prima occupazione in Tripolitania", "44780018"], "d": ["L'Italia dichiarò guerra il 29 settembre 1911 e la sua flotta il 25-26 settembre bloccò la costa. La prima operazione di terra fu fatta a Tobruk l'8 ottobre: la piccola guarnigione ottomana si ritirò all'interno e il porto fu occupato senza combattimento. Tobruk era il porto ottomano più vicino al confine egiziano; la sua caduta aprì il fianco orientale della Cirenaica e agevolò la marcia delle forze italiane verso ovest lungo la costa.", "fa489107"]},
"OLAYLAR_EK9:1911-10-09:0":{"b": ["Resa della città di Tripoli agli Italiani", "785091ad"], "d": ["Tripoli si arrese il 9 ottobre 1911 dopo tre giorni di bombardamento. Le forze ottomane, invece di difendere la città, scelsero di ritirarsi ad Aziziya e Gharyan e di organizzare la resistenza all'interno; questa resistenza, a cui parteciparono Enver e Mustafa Kemal Bey, tenne gli Italiani confinati sulla fascia costiera fino alla fine della guerra. Cioè, benché la città fosse caduta, l'interno della provincia rimase sotto controllo ottomano.", "7deeaf70"]},
"OLAYLAR_EK9:1911-10-16:0":{"b": ["Perdita di Derna con lo sbarco italiano", "f014c741"], "d": ["Dopo Tobruk toccò a Derna, secondo porto della Cirenaica; la città fu occupata il 16 ottobre 1911. L'altopiano intorno a Derna era la regione di maggiore presenza della confraternita dei Senussi e i mujahidin raccolti con la chiamata al jihad dello sceicco Ahmed Sharif tennero gli Italiani assediati intorno al porto. L'occupazione rimase limitata alla città e non si estese mai alle retrovie.", "b6ada646"]},
"OLAYLAR_EK9:1911-10-21:0":{"b": ["Sbarco italiano a Bengasi — perdita del centro del sanjak di Cirenaica", "f9183c40"], "d": ["Bengasi, centro della Cirenaica, fu occupata il 21 ottobre 1911 con il quarto e più importante sbarco sulla costa. Così l'Italia, tre settimane dopo la dichiarazione di guerra, teneva tutti i grandi porti della provincia di Tripolitania (Tripoli, Tobruk, Derna, Bengasi); ma non poté penetrare nell'entroterra di nessuno. Il resto dell'anno di guerra trascorse in avanzate senza esito dall'interno di questi quattro punti sulla costa.", "6181e67f"]},
"OLAYLAR_EK9:1911-11-05:0":{"b": ["Decreto di annessione unilaterale dell'Italia", "cfe3f9c2"], "d": ["L'Italia, mentre la guerra continuava, il 5 novembre 1911 emanò un decreto e dichiarò di aver annesso Tripolitania e Cirenaica. L'Impero ottomano non lo riconobbe e la guerra continuò per un altro anno; l'annessione ottenne validità giuridica solo con il Trattato di Ouchy del 18 ottobre 1912. Per questo il decreto non cambia il colore ottomano sulla mappa — la proprietà giuridica è ottomana fino al 1912, il controllo italiano è mostrato come occupazione tratteggiata.", "23668758"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Presa di Köprühisar e preparativi per la fondazione di Yenişehir", "39abff03"], "d": ["Con la caduta delle fortezze di passo tra Bursa e İznik fu posta la base del quartier generale avanzato che avrebbe stretto d'assedio le due città.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Fondazione di Yenişehir", "d3275837"], "d": ["Per dirigere gli assedi di Bursa e İznik fu fondato il primo insediamento-guarnigione ottomano regolare; Orhan Gazi nacque qui.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Primo assedio di İznik e conquista di Marmaracık", "cdca2349"], "d": ["İznik fu assediata per la prima volta ma non cadde (la conquista definitiva è del 1331); nel frattempo fu presa la vicina fortezza di Marmaracık.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Campagna della Compagnia Catalana in Anatolia", "4fd940d5"], "d": ["La compagnia catalana assoldata da Bisanzio per fermare l'avanzata turca ottenne successi temporanei ma non durevoli; con il suo ritiro l'avanzata dei beylik di frontiera si accelerò.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal si converte all'Islam e passa agli Ottomani", "ca0d86e1"], "d": ["Köse Mihal, tekfur di Harmankaya, si convertì all'Islam e si unì a Osman Gazi con la sua fortezza e i suoi uomini; fu il primo comandante ottomano di origine bizantina.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Bey assume di fatto il governo", "6dadbefc"], "d": ["Per la vecchiaia e la malattia di Osman Gazi, la direzione e la conduzione effettiva dell'assedio di Bursa e delle campagne passarono al figlio Orhan Bey (l'ascesa ufficiale al trono è del 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Presa di Mudanya", "0a623368"], "d": ["Fu presa Mudanya, porto di Bursa, e il collegamento della città con il mare fu tagliato; l'assedio di Bursa entrò nella fase di strangolamento.", "c13020d5"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Conquista di Akyazı e dell'isola di İmralı", "d041b0c8"], "d": ["Fu presa Akyazı, a nord del Sakarya; con la conquista dell'isola di İmralı gli Ottomani, per la prima volta, divennero vicini dell'isola di Marmara.", "591424a4"]},
"OLAYLAR_EK:1324-03-01:0":{"b": ["Conquista di Gemlik (Kios) e Armutlu", "682d3bac"], "d": ["Tagliato l'ultimo collegamento marittimo di Bursa, la città fu preparata alla resa del 1326.", "c2b80b4a"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koca conquistò Kandıra e dintorni", "341bb97e"], "d": ["Akça Koca, uno dei beg di frontiera di Orhan Gazi, mentre compiva incursioni nella regione di İzmit dal suo quartier generale a ovest del lago di Sapanca, verso il 1326 si impadronì di Kandıra e dei dintorni. İzmit era ancora in mano bizantina; la città sarebbe caduta solo nel 1337.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["Annessione di Yalova e Karamürsel", "133cb07a"], "d": ["Yalova e dintorni, sulla costa meridionale del golfo di İzmit, quest'anno passarono in mano turca; la fascia costiera fu data come timar da Orhan Bey a Karamürsel Gazi.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koca prese Aydos e la fortezza di Samandıra", "ce4daa8a"], "d": ["Dopo la presa di Kandıra, Akça Koca insieme a Konuralp e Gazi Abdurrahman prese la fortezza di Aydos presso Kartal e poi la fortezza di Samandıra a nord di essa; la regione di Samandıra gli fu data come proprietà. Akça Koca morì nel 1328 presso Kandıra; il beylik di frontiera fu dato al principe Murad.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Alleanza ottomano-Aydın-Saruhan", "9df6bb74"], "d": ["Tre beylik agirono insieme contro Bisanzio; la flotta di Umur Bey degli Aydınoğlu logorò Bisanzio su un secondo fronte con le incursioni sulle coste della Tracia.", "32ca49ea"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Matrimonio di Orhan Gazi con Teodora: alleanza bizantina", "9b67a590"], "d": ["Orhan Gazi, che nella lotta per il trono bizantino sosteneva Cantacuzeno, sposò la figlia di lui, Teodora; questa alleanza permise alle forze ottomane di conoscere da vicino la Rumelia.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Presa di Ankara", "49bf1f6d"], "d": ["Ankara, retta dagli ahi, entrò nell'amministrazione ottomana; si aprì la strada dell'Anatolia centrale. Altri luoghi annessi nella stessa data: Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Avanzata in Tracia al tempo di Süleyman Paşa: Malkara, İpsala e Tekirdağ", "fb31cf02"], "d": ["Dopo aver stabilito la testa di ponte a Gallipoli, Süleyman Paşa salì a nord dalla penisola e conquistò passo dopo passo la pianura tra la costa del Marmara e la foce della Maritza. Malkara, İpsala e Rodosçuk (Tekirdağ) formarono così un corridoio ininterrotto che univa Gallipoli e la valle della Maritza. Senza la costituzione di questo corridoio non si poteva marciare su Edirne; l'avanzata, fermata dalla morte improvvisa del principe nel 1357, sarebbe stata proseguita da Lala Şahin e Hacı İlbey.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Rapimento del principe Halil", "b52ac3d7"], "d": ["Halil, figlio minore di Orhan Gazi, fu rapito dai pirati di Focea; la crisi del riscatto occupò per anni le relazioni ottomano-bizantine.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Tagliate le vie di soccorso di Edirne: fortezze di Çorlu, Lüleburgaz, Babaeski e Keşan", "8e8ad485"], "d": ["Il principe Murad, ripresa la campagna di conquista dopo la liberazione di Halil, mandò gli akıncı fino alle porte di Costantinopoli per isolare Edirne da ogni aiuto esterno. Furono presi le fortezze di Çorlu, Lüleburgaz e Babaeski sulla strada Costantinopoli-Edirne e Keşan, snodo stradale della Tracia meridionale. La resa di Edirne giunse dopo il completamento di questo anello d'assedio.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Presa di Dimetoka — apertura della valle della Maritza", "b59aee83"], "d": ["Fu presa Dimetoka, fortezza chiave della valle della Maritza; si aprì così la strada della conquista di Edirne. Senza il completamento del corridoio che si estende a nord da Gallipoli non era possibile marciare su Edirne, per questo la fortezza nell'ordine delle conquiste in Rumelia precede Edirne. La città divenne per un periodo il quartier generale dei sultani in Rumelia. Le forze che presero Dimetoka misero poi sotto controllo l'intera regione della media Maritza, insieme a piccole fortezze come Kuleli Burgaz (Pythion).", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Perdita di Gallipoli (crociata di Savoia)", "00e7e415"], "d": ["La flotta di Amedeo di Savoia, cugino dell'imperatore bizantino, prese Gallipoli e la consegnò a Bisanzio; la testa di ponte ottomana in Rumelia fu governata per dieci anni dalla sponda opposta dello stretto. Altri insediamenti perduti nella stessa data: Çimpe.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Battaglia di Çirmen — controllo della valle della Maritza", "cd738d8d"], "d": ["L'esercito dei signori serbi fu disperso in un attacco notturno; i signori locali serbi/bulgari della Macedonia e dei Rodopi cominciarono uno per uno a pagare tributo agli Ottomani — non una conquista diretta, ma l'inizio di un'ondata di vassallaggio. Nella tradizione ottomana questa battaglia è narrata anche con il nome di «Sırpsındığı» e con la data del 1364, come attacco notturno di Hacı İlbey contro l'esercito crociato venuto a riprendere Edirne; il TDV afferma che tale data è errata e che le due narrazioni si riferiscono alla stessa battaglia.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Conquista di Filibe e Eski Zağra", "e780c9ae"], "d": ["Furono prese Filibe (Plovdiv), a monte della valle della Maritza, e Eski Zağra (Stara Zagora) a nord; lo zarato bulgaro fu reso tributario. Il percorso Tatarpazarcığı-İhtiman tra Filibe e Sofia rimase in mano ai signori locali divenuti vassalli dopo Çirmen.", "b8131db8"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Bisanzio vassallo: Giovanni V nell'esercito di Murad I (conseguenza della vittoria di Çirmen del 1371)", "13ffe568"], "d": ["Secondo il TDV, dopo la vittoria di Çirmen (Maritza) del 26 settembre 1371 l'Impero bizantino aveva riconosciuto il dominio ottomano e, accettando di pagare tributo e di servire nell'esercito ottomano, era caduto nella condizione di Stato vassallo. L'imperatore Giovanni V, con questo obbligo, nel 1373 si unì all'esercito di Murad I; il figlio Andronico IV, lasciato nel frattempo a Costantinopoli, si ribellò al padre insieme al principe Savcı Bey, a Bursa.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Riconquista di Gallipoli", "5f96c0a5"], "d": ["Andronico IV, che nella contesa per il trono bizantino aveva ottenuto l'appoggio ottomano, in cambio restituì Gallipoli; il ponte tra Rumelia e Anatolia fu ricostituito. Altri luoghi annessi nella stessa data: Çimpe.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Dote germiyanide: annessione di Kütahya", "d6a6fe61"], "d": ["Nel matrimonio di Devletşah Hatun, figlia di Germiyanoğlu Süleyman Şah, con Yıldırım Bayezid, Kütahya, Simav, Tavşanlı ed Eğrigöz passarono agli Ottomani come dote — l'esempio classico di espansione senza guerra. Altri luoghi annessi nella stessa data: Afyon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Acquisto del territorio di Hamîd: annessione di Isparta", "4a1b6047"], "d": ["Hamîdoğlu Hüseyin Bey vendette a Murad I, in cambio di denaro, una parte del suo beylik (Akşehir-Beyşehir-Isparta); il resto del territorio di Hamid sarebbe stato annesso da Yıldırım nel 1391.", "d316dea5"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Conquista di Serez", "d4d28b60"], "d": ["Fu presa Serez, chiave della Macedonia orientale; Salonicco entrò nel cerchio d'assedio. La linea Köstendil-Petriç-Nevrokop-Drama tra Sofia e Serez a questa data non era ancora annessa direttamente: passò in successione a vassallaggio fra gli anni 1370 e il 1383 e a governo diretto dopo il 1383.", "573cc19c"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Conquista di Sofia", "96d5f01f"], "d": ["Furono messi sotto controllo i passi occidentali dei monti Balcani; poiché a questa data Serez era già in mano dal 1383, i territori di Tracia e Macedonia formavano un blocco ininterrotto.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Conquista di Niš", "77f5d632"], "d": ["Con la presa di Niš, chiave della valle della Morava, il despotato serbo fu direttamente minacciato.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Prima resa di Salonicco", "96010ee9"], "d": ["Dopo un lungo blocco la città si arrese (sarebbe stata restituita a Bisanzio nel 1403 e conquistata definitivamente nel 1430). Altri luoghi annessi nella stessa data: Kavala.", "5ef8bffd"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Ahidnâme ottomano-genovese — rinnovo del trattato del 1352", "be11d17a"], "d": ["Con gli ambasciatori genovesi di Pera fu rinnovato l'accordo commerciale del 1352, risalente all'epoca di Orhan Gazi; furono nuovamente fissati le imposte, il trattamento dei prigionieri e il libero commercio tra i due Stati. È considerato il primo ahidnâme ufficialmente noto di amicizia e commercio tra Ottomani e Genovesi — non un'alleanza militare, ma un accordo interamente commerciale.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Campagna di Bulgaria di Çandarlı Ali Paşa: presa di Şumnu e Rusçuk", "2781c3a9"], "d": ["Le fortezze dello zarato bulgaro lungo il Danubio furono prese in una sola campagna; non va confuso con la sconfitta subita nello stesso anno a Bileća in Bosnia — fu un successo simultaneo su un fronte separato. Tırnova e Vidin erano ancora gli ultimi centri bulgari in mano.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Sconfitta di Bileća", "89ba0a64"], "d": ["La forza di akıncı diretta in Bosnia cadde in un'imboscata a Bileća e fu annientata; questa prima grande battuta d'arresto balcanica incoraggiò l'alleanza che condusse al Kosovo.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Annessione dei beylik dell'Anatolia occidentale: Saruhan, Aydın, Menteşe", "dcc33b71"], "d": ["Tre beylik furono annessi in un'unica volta: Manisa, centro dei Saruhanoğulları; Aydın, centro degli Aydınoğulları (compresa la fortezza superiore di Smirne, ma con porto/fortezza bassa ancora ai Cavalieri di San Giovanni — fino al 1402); Muğla-Milas, centro dei Menteşeoğulları, compresa la fascia costiera Datça-Bodrum-Marmaris-Fethiye. Le coste egee furono per la prima volta riunite sotto un'unica mano. Altri luoghi annessi nella stessa data: Söke.", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Annessione del territorio di Teke: annessione di Antalya", "fdbeee5c"], "d": ["Il territorio di Teke, sulla costa mediterranea, fu annesso ai territori ottomani. I Tekeoğulları sono un ramo staccatosi dagli Hamîdoğulları: Feleküddin Dündar Bey aveva lasciato Antalya, da lui conquistata, al fratello Yûnus Bey e verso il 1321 era nato un beylik separato. Per questo Antalya e dintorni sulla mappa dopo il 1321 sono mostrati con il colore dei Tekeoğulları e non degli Hamîdoğulları. Il beylik fu ricostituito dopo la battaglia di Ankara e fu liquidato in modo definitivo solo nel 1423.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Conquista di Üsküp", "9e5a1af5"], "d": ["Fu presa Üsküp, centro della Macedonia del Vardar; Üsküp divenne uno dei principali centri di frontiera della Rumelia.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Annessione di Kastamonu", "876330ba"], "d": ["Il ramo di Kastamonu dei Candaroğulları fu liquidato; il ramo di Sinope continuò come vassallo. Altri luoghi annessi nella stessa data: Bartın, Safranbolu.", "34d8e600"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Caduta di Tırnova — annessione della Bulgaria", "ff666977"], "d": ["Cadde la capitale dello zarato bulgaro; la Bulgaria entrò sotto governo ottomano diretto. Altri luoghi annessi nella stessa data: Plevne, Lofça.", "182028e2"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["La fortezza di Lofça (Lovech) passa agli Ottomani", "a55e87a0"], "d": ["Lofça, una delle fortezze dello zar bulgaro Ivan Šišman, nella campagna del 1393 in cui cadde Tırnova fu annessa ai territori ottomani insieme alle altre province di Šišman. La fonte non è categorica: si «ritiene» che la conquista sia avvenuta in quest'anno.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Annessione della Dobrugia", "478e36f2"], "d": ["Furono annessi i territori della Dobrugia che si estendono fino al delta del Danubio. Altri luoghi annessi nella stessa data: Silistre, Köstence.", "05bdabb4"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Discesa in Tessaglia", "8bec60dd"], "d": ["La pianura della Tessaglia, centrata su Yenişehir (Larissa), fu posta sotto amministrazione ottomana. Altri luoghi annessi nella stessa data: Tırhala, İzdin (Lamia).", "d9f2128c"]},
"OLAYLAR_EK:1394-01-01:1":{"b": ["Inizio dello stretto assedio di Costantinopoli (blocco dal ~1387)", "0068bc04"], "d": ["Yıldırım Bayezid tenne Costantinopoli sotto blocco a intervalli per dieci anni; la città si salvò solo per l'avvicinarsi di Tamerlano.", "504fcb33"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["Battaglia di Rovine — campagna di Valacchia", "343ae7a9"], "d": ["Dopo la battaglia sanguinosa dall'esito controverso con il voivoda di Valacchia Mircea, la Valacchia accettò di pagare tributo agli Ottomani; fu stabilito l'assetto di vassallaggio a nord del Danubio.", "dd69200f"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Conquista di Nicopoli", "b9791717"], "d": ["Dopo la battaglia di Rovine del 1395 contro i Valacchi, Yıldırım Bayezid prese la fortezza di Nicopoli sul Danubio; alcune cronache bulgare anonime indicano che la conquista avvenne il 3 giugno 1395. La data della conquista non è univoca nelle fonti: la voce Niğbolu Savaşı del TDV İslâm Ansiklopedisi scrive che Bayezid prese Silistra e Nicopoli in una campagna sul Danubio del 1394. La fortezza sarebbe stata assediata nella celebre Crociata del 1396, ma non sarebbe caduta. Altri luoghi annessi nella stessa data: Ohri.", "bc450a9f"]},
"OLAYLAR_EK:1395-06-03:0":{"b": ["La fortezza di Nicopoli passò agli Ottomani", "327012c9"], "d": ["Dopo l'incursione di Rovine Yıldırım Bayezid prese Nicopoli; lo zar bulgaro Ivan Šišman, che vi risiedeva come vassallo ottomano, fu eliminato. Nell'atlante Nicopoli è registrata in questo giorno come passata dallo Zarato bulgaro agli Ottomani.", "6e7d5207"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Costruzione di Anadolu Hisarı", "aa259b00"], "d": ["Per sostenere il blocco di Costantinopoli sulla sponda anatolica del Bosforo fu costruita Güzelcehisar (Anadolu Hisarı) — il primo passo duraturo del controllo dello stretto.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Annessione di Vidin", "ee1ae44b"], "d": ["Dopo la vittoria di Nicopoli fu annesso anche Vidin, ultimo principato bulgaro.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Prima annessione di Karaman", "3cf07876"], "d": ["Con la vittoria di Akçay i territori dei Karamanoğulları furono annessi per la prima volta agli Ottomani (sarebbero stati ricostituiti durante il Fetret).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Annessione delle coste del Canik: Samsun", "af9c40fa"], "d": ["Nel vuoto creato dalla cattura di Kadı Burhâneddin da parte dell'aqquyunlu Karayülük Osman Bey, Yıldırım Bayezid pose dapprima sotto amministrazione ottomana la regione del Canik, sulla costa del Mar Nero. Samsun e dintorni divennero così il primo porto del Mar Nero della dinastia. La linea interna Sivas-Tokat-Kayseri sarebbe stata annessa due settimane dopo, con la dissoluzione di fatto dello Stato di Kadı Burhâneddin.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Presa di Malatya", "7cb6ae16"], "d": ["Fu conquistata Malatya, sul confine mamelucco — uno dei passi che accrebbero la tensione con Tamerlano.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Tamerlano prese Malatya e la lasciò a Karayülük Osman — quando Tamerlano si ritirò i Dulkadiroğulları la ripresero", "ad2ce7d8"], "d": ["Yıldırım Bayezid, lasciata Malatya, presa nel 1399, a Dulkadıroğlu Nasreddin Mehmed, era tornato a Bursa. Tamerlano, entrato in Anatolia nel 1400, prese prima Sivas ed Elbistan, poi Malatya; la città e i dintorni furono saccheggiati e l'amministrazione fu lasciata a Karayülük Osman, che era con Tamerlano. Quando Tamerlano lasciò la regione, Malatya fu di nuovo dominata dai Dulkadiroğulları; il dominio ottomano terminò dunque prima di Ankara.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Accordo di Süleyman Çelebi con Bisanzio: restituzione di Salonicco", "cc503cc2"], "d": ["Süleyman Çelebi, che durante il Fetret dominava la Rumelia, accordandosi con Bisanzio e con gli Stati latini, abbandonò a Bisanzio Salonicco e le coste del Mar Nero fino a Misivri (TDV fetret-devri: Trattato di Gallipoli, febbraio 1403) — sulla mappa İğneada, Rezve e Ahtapolu passano a Bisanzio; Salonicco a questa data esce dagli Ottomani.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Sconfitta navale di Gallipoli (Venezia)", "b71d4d68"], "d": ["La flotta veneziana inflisse una dura sconfitta alla flotta ottomana davanti a Gallipoli; l'evento mostrò i limiti della marineria ottomana delle origini.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Rivolta di Düzmece Mustafa", "0ec43138"], "d": ["Mustafa Çelebi, che sosteneva di essere figlio di Yıldırım, con l'appoggio bizantino proclamò il sultanato in Rumelia; Murad II represse la rivolta nel 1422 e fece giustiziare il rivale.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Assedio di Costantinopoli di Murad II", "4b9d9fba"], "d": ["In risposta al sostegno bizantino a Düzmece Mustafa, Murad II assediò Costantinopoli; l'assedio fu tolto quando il fratello Küçük Mustafa fu fatto insorgere in Anatolia.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Cessione di Salonicco a Venezia", "bfa6c4a0"], "d": ["Il governatore bizantino, sotto la pressione ottomana, cedette la città a Venezia; iniziò la contesa ottomano-veneziana destinata a durare sette anni.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Nuova annessione dei beylik dell'Anatolia occidentale: Menteşe e Aydın", "aca30a48"], "d": ["I due beylik egei ricostituiti durante il Fetret Devri furono definitivamente annessi ai territori ottomani sotto Murad II. Secondo la voce Menteşeoğulları del TDV, Murad II conquistò il territorio di Menteşe nell'827 (1424) e fece imprigionare i due fratelli a capo del beylik. Secondo la voce Aydınoğulları, il beylerbey d'Anatolia Hamza Bey fece catturare Cüneyd Bey, di nuovo uscito dall'obbedienza, e lo fece giustiziare con la sua famiglia (829/1425-26), e il territorio di Aydın passò agli Ottomani. I Cavalieri di San Giovanni, che dal 1344 tenevano la fortezza portuale di Smirne, l'avevano perduta nel 1402 a favore di Tamerlano e la regione era tornata sotto il controllo degli Aydınoğulları; con questa annessione anch'essa fu annessa agli Ottomani. Il territorio di Teke (Antalya) non è oggetto di questa voce: i Tekeoğulları erano stati liquidati separatamente nel 1423. Germiyan sarebbe invece stato annesso nel 1429 per testamento.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Annessione di Germiyan per testamento", "9eb86b77"], "d": ["Il bey di Germiyan Yakub II, morto senza figli, lasciò il paese agli Ottomani per testamento — l'esempio da manuale di annessione senza guerra. Altri luoghi annessi nella stessa data: Karahisâr-ı Sâhib (Afyon).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Conquista definitiva di Salonicco", "bc021768"], "d": ["La città, sotto dominio veneziano, fu presa d'assalto; il secondo grande porto della Rumelia divenne definitivamente ottomano. Altri luoghi annessi nella stessa data: Kesendire (Cassandra).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Resa di Ioannina", "ee45cb52"], "d": ["Ioannina, centro dell'Epiro, si arrese con un accordo.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Prima presa di Smederevo", "c11ca17d"], "d": ["Con un assedio di tre mesi fu presa la capitale del despotato serbo e la Serbia fu annessa per la prima volta (sarebbe stata restituita con il trattato di Edirne-Seghedino del 1444).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Assedio di Belgrado (fallito)", "3e05f425"], "d": ["Il primo grande assedio di Belgrado, durato sei mesi, non diede risultati; per ottant'anni la fortezza rimase come chiave di volta davanti all'avanzata ottomana.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Disfatta di Zlatica — la «Lunga Campagna»", "97df1466"], "d": ["L'esercito che Hunyadi aveva portato nei Balcani in pieno inverno, superate Niš e Sofia, giunse fino a Zlatica; la difesa ottomana resse a fatica. Questo clima di disfatta portò al tavolo la pace di Edirne-Seghedino.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Trattato di Edirne-Seghedino", "0aa4e0de"], "d": ["Pace decennale: il despotato serbo fu restituito, il Danubio fu accettato come confine. La rottura del trattato nel giro di mesi, per istigazione papale, condusse al disastro di Varna.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Restituzione di Smederevo e delle fortezze serbe alla Serbia", "cda3cf9e"], "d": ["La disposizione del trattato di Edirne-Seghedino fu messa in esecuzione: Murad II il 15 agosto 1444 restituì a Đurađ Branković Smederevo con le sue ventiquattro importanti fortezze e gli altri territori serbi occupati (TDV semendire); anche Niš (TDV nis), Alacahisar (TDV alacahisar), Şehirköy (TDV sehirkoy) e Priştine (TDV pristine) furono lasciate ai Serbi. Vidin, non essendo territorio serbo, non entrò nella restituzione — è questa l'origine della perdita territoriale nord-occidentale visibile sulla mappa intorno alla vittoria di Varna; pochi mesi dopo, con la disfatta di Varna, il trattato sarebbe comunque decaduto.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Completato Rumeli Hisarı — il «Taglia-Stretto»", "480e8a76"], "d": ["Con la fortezza, completata secondo le fonti in una costruzione straordinariamente rapida di quattro o cinque mesi, il controllo dello Stretto passò interamente agli Ottomani; la via di soccorso dal Mar Nero a Costantinopoli fu chiusa. È considerato il primo passo effettivo dell'assedio.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Inizio dell'assedio di Costantinopoli", "8af50742"], "d": ["L'esercito si dispose davanti alle mura; nell'assedio, destinato a durare 54 giorni, i cannoni giganteschi furono usati per la prima volta in modo sistematico contro le mura di una capitale.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Le navi calate dalla terra nel Corno d'Oro", "4f2ba07c"], "d": ["Circa 70 navi della flotta, che non poteva entrare nel Corno d'Oro chiuso dalla catena, furono trasportate sopra le alture di Galata su slitte unte e calate in una notte nel Corno d'Oro; la difesa fu divisa in due fronti.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Conquista di Atene", "4f0f1bb2"], "d": ["Il Ducato di Atene finì; sull'Acropoli fu issata la bandiera ottomana. Altri luoghi annessi nella stessa data: İstefe (Tebe), Livadya.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Annessione della Serbia (caduta di Smederevo)", "75fd0a62"], "d": ["Smederevo, capitale del despotato serbo, si arrese; la Serbia divenne un sancak ottomano.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Conquista della Morea", "7d5a3c18"], "d": ["Il despotato di Morea fu liquidato; la penisola (escluse le fortezze veneziane) entrò sotto amministrazione ottomana.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Annessione di Sinope", "e03c2739"], "d": ["Il candaroğlu consegnò Sinope senza combattere; si aprì la strada della campagna di Trebisonda. Altri luoghi annessi nella stessa data: Kastamonu, Bartın, Safranbolu. La voce Candaroğulları del TDV cita anche Bolu, Eflani e Tosya tra i territori del beylik dei Candaroğlu annessi nel 1461; nell'atlante anche questi tre luoghi sono registrati in questo giorno come passati dai Candaroğlu agli Ottomani.", "4ef62060"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Caduta del Regno di Bosnia — campagna di Bosnia del Conquistatore", "5362e3f2"], "d": ["Quando l'ultimo re di Bosnia, Stjepan Tomašević (1461-1463), confidando nel sostegno occidentale, rifiutò di pagare il tributo, fu considerato decaduto dalla condizione di sovrano soggetto e l'esercito sotto Mehmed il Conquistatore liquidò il Regno di Bosnia in una sola campagna. Il re fu catturato e giustiziato, il regno scomparve e nella regione fu istituito il sancak di Bosnia. Tuttavia la caduta del regno non è la stessa cosa della conquista della Bosnia. L'amministrazione ottomana era già presente nella pianura da quindici anni — Hodidjed e la piana di Saray erano state prese nel 1448 e il beylik di frontiera di Îsâ Bey era stato fondato in mezzo al regno. La conquista non finì neppure nel 1463: Foça nel 1465, Livno nel 1469, il Ducato di Erzegovina nel 1483, il banato di Srebrenik nel 1512, Yayça e Banaluka a nord solo nel 1528, dopo Mohács — gli Ungheresi, dopo il 1463, avevano costituito nel nord della Bosnia un banato che resistette sessantacinque anni. Il luogo che cambia direttamente mano a questa data è Travnik; Yayça passa invece in questa data non agli Ottomani ma all'Ungheria.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Annessione definitiva di Karaman", "f1dcecaa"], "d": ["I territori centrali dei Karamanoğulları furono annessi in modo definitivo; le lotte interne durarono fino agli anni 1470. Altri luoghi annessi nella stessa data: Niğde, Mostar, Beyşehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Conquista di Negroponte", "5c97daf3"], "d": ["Cadde Negroponte, principale base veneziana nell'Egeo.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Annessione di Alanya, Anamur e Silifke (İçel)", "a0b9d461"], "d": ["La fascia costiera dell'İçel, dipendente dai Karamanoğulları (l'intero Mediterraneo tra Antalya e Mersin), fu annessa con la campagna navale di Gedik Ahmed Paşa; Alanya era importante per il suo arsenale strategico di epoca selgiuchide.", "8302df58"]},
"OLAYLAR_EK:1478-01-15:0":{"b": ["Annessione di Novgorod a Mosca", "bed87170"], "d": ["Il granduca Ivan III tolse la campana simbolica dell'assemblea popolare (veče) di Novgorod, sostituì le autorità locali con i propri governatori e legò di fatto la città a Mosca; Novgorod cessò di essere una repubblica indipendente. Il territorio di Novgorod si estendeva dal Mar Baltico al Mar Bianco e agli Urali. Nell'atlante Novgorod è registrata in questo giorno come passata dalla Repubblica di Novgorod a Mosca.", "65b660e7"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Trattato di Costantinopoli — Albania e Scutari", "b09652f7"], "d": ["La guerra ottomano-veneziana di 16 anni terminò; Scutari e le coste albanesi rimasero agli Ottomani. Altri luoghi annessi nella stessa data: Limni, Sisam, Bozbaba (Ay Strati).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Sbarco a Otranto", "7916b89d"], "d": ["Le forze ottomane sbarcate sulla costa della Puglia (Apulia) assediarono e presero la fortezza di Otranto; poiché si entrò in città combattendo, una parte dei notabili che avevano resistito fu giustiziata e un'altra parte presa prigioniera. La tradizione ecclesiastica ricorda i morti come i «martiri di Otranto», circa 800 persone; il TDV attribuisce l'esagerazione di questo numero alla propaganda ecclesiastica. Furono tenute solo la fortezza all'estremità della penisola salentina e il suo ristretto circondario; gli altri territori del Regno di Napoli sulla linea Taranto-Brindisi-Lecce non andarono perduti — questa testa di ponte aperta sull'Italia sarebbe durata un anno.", "0e1004b8"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Evacuazione di Otranto", "37371bb0"], "d": ["Alla morte di Mehmed il Conquistatore (3 maggio 1481), senza più speranza di nuovi rinforzi, la guarnigione di Otranto, di fronte all'assedio dell'erede al trono di Napoli Alfonso, evacuò la fortezza per accordo; l'unica testa di ponte ottomana in Italia andò così perduta un anno dopo.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Conquista di Modone e Corone", "38b608c4"], "d": ["Furono prese Modone e Corone, i «due occhi» di Venezia in Morea.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Conquista di Durazzo", "1f231b98"], "d": ["Durante la guerra ottomano-veneziana del 1499-1503, le forze al comando di Mehmed Bey presero Durazzo, l'ultimo grande porto albanese di Venezia sull'Adriatico. Dopo Scutari (1479) e Valona (1417), con questa conquista la fascia costiera albanese passò interamente sotto il controllo ottomano.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Annessione dell'Anatolia orientale", "e0cb8f8f"], "d": ["Dopo Çaldıran furono annessi Diyarbakır e dintorni; i beylik curdi furono legati agli Ottomani per opera di İdrîs-i Bitlisî.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Conquista della fortezza di Varadino (Petrovaradin)", "abf392a5"], "d": ["L'esercito partito per la campagna di Mohács passò da Belgrado nelle terre ungheresi; di Varadino furono prese prima le periferie e, dopo un assedio di quattordici giorni, cadde anche la fortezza. Solimano ordinò di non bruciare i villaggi lungo la strada, perché ormai erano considerati terra ottomana.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Resa di Buda dopo Mohács — due re sul trono ungherese", "9d3568a0"], "d": ["All'esercito ottomano che marciava su Buda dopo la vittoria di Mohács le chiavi della città furono presentate al sultano l'11 settembre 1526; ma Solimano non tenne Buda e ritirò l'esercito. Nell'Ungheria rimasta senza re i nobili elessero due re distinti: János Szapolyai il 10 novembre 1526 e il 17 dicembre 1526 l'asburgico Ferdinando I. Ferdinando prese Buda nell'agosto 1527. L'insediamento di Szapolyai a Buda come re sotto protezione ottomana avverrà con la campagna del 1529 (si veda la voce del 1529); il governo ottomano diretto sarebbe stato stabilito nel 1541.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["János Szapolyai eletto re d'Ungheria — gli Ottomani riconobbero il suo regno a condizione che fosse vassallo", "32bc6baf"], "d": ["Per il trono ungherese rimasto vacante con la morte del re a Mohács una parte dei nobili elesse János Szapolyai, voivoda di Transilvania; Szapolyai fu incoronato a Székesfehérvár. Gli Ottomani, che avevano lasciato Buda, per tenere la regione come zona cuscinetto riconobbero il regno di Szapolyai a condizione che fosse loro vassallo. Sulla mappa i luoghi legati a Szapolyai appaiono da questa data come vassalli degli Ottomani.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Ferdinando I proclamato re d'Ungheria — l'Ungheria occidentale e settentrionale alla corona asburgica", "b3910a2f"], "d": ["L'arciduca asburgico Ferdinando, in base al matrimonio della sorella con Luigi II, avanzò pretese sul trono ungherese e fu proclamato re da una parte dei nobili. L'Ungheria fu così divisa tra due re; la parte occidentale e settentrionale riconobbe Ferdinando. I nobili croati lo elessero a parte all'inizio del 1527.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Contesa dei due re: Esztergom sotto protezione asburgica, Szeged a Szapolyai", "da92dee5"], "d": ["Esztergom, che dal 1526 passava di mano tra i due re, dopo che l'arcivescovo si trasferì a nord con l'archivio e il tesoro, entrò sotto la protezione asburgica. Dallo stesso anno fino al 1541 Szeged rimase sotto il dominio di Szapolyai.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["Gli abitanti di Pécs passarono dalla parte di Szapolyai", "3fc4e7f2"], "d": ["Pécs, che nel 1528 aveva ottenuto privilegi da Ferdinando, poco dopo passò dalla parte di Szapolyai; re János nel 1533 soggiornò per un periodo in città. Con la caduta di Buda nel 1541 la città tornò dalla parte di Ferdinando.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Conquista di Tripoli", "8c659986"], "d": ["Tripoli fu presa ai cavalieri di San Giovanni; la costa centrale del Nord Africa divenne ottomana. Altri luoghi annessi nella stessa data: Misrata.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Conquista di Timișoara", "e9fd4995"], "d": ["Fu presa la regione del Banato e fu istituito il Beylerbeylik di Timișoara.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Conquista definitiva di Tunisi", "7bbd11bc"], "d": ["Tunisi, sotto controllo ispano-hafside, entrò definitivamente nell'amministrazione ottomana; la linea nordafricana fu completata. Altri luoghi annessi nella stessa data: Kayrevan, Gabes, Sfaks.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Conquista di Kanije", "0c7b6aa3"], "d": ["Nella Lunga Guerra fu presa Kanije; l'anno seguente la difesa di Tiryâki Hasan Paşa divenne epica.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Inizio della campagna di Uyvar — Fâzıl Ahmed Paşa marciò da Edirne contro l'Austria", "306a86db"], "d": ["Dopo che l'Austria aveva attaccato la Transilvania e preso le fortezze di Székelyhíd e Cluj, Costantinopoli decise la campagna contro gli Asburgo. Il gran visir Köprülüzâde Fâzıl Ahmed Paşa partì da Edirne il 13 aprile 1663. A Belgrado giunse la richiesta di pace dell'Austria, ma in due colloqui a Osijek le condizioni ottomane furono respinte. Anche nella consultazione di Buda l'obiettivo fu fissato in Uyvar.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Conquista di Uyvar", "ce289470"], "d": ["Fu presa Uyvar, fortezza chiave dell'Ungheria settentrionale; l'espressione «forte come un Turco davanti a Uyvar» passò nelle lingue europee. Dopo Uyvar anche Nitra e Léva si arresero con breve resistenza; entrambe furono riprese da De Souches nella primavera del 1664.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Riconquista della Morea", "9b6460f1"], "d": ["La Morea, lasciata a Venezia a Karlowitz, fu ripresa in una sola campagna. Altri luoghi annessi nella stessa data: Balyabadra (Patrasso), İnebahtı.", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Seconda perdita di Belgrado — assedio del principe Eugenio", "6a194354"], "d": ["Dopo la disfatta di Varadino e la perdita di Timișoara il principe Eugenio assediò Belgrado; quando fu sconfitto anche l'esercito di soccorso venuto a salvare la città, la fortezza si arrese. La città, ripresa nel 1690 dopo Karlowitz, andò così nuovamente perduta e la linea difensiva del Danubio crollò. Belgrado avrebbe potuto essere ripresa solo ventidue anni dopo, con il trattato di Belgrado del 1739. Altri insediamenti perduti nella stessa data: Semendire. L'atlante assegna inoltre in questo giorno agli Asburgo le zone di Hisarcık (Grocka) e Yagodina (Jagodina) (giorno di zona; il giorno a livello di luogo non è nella fonte, approssimazione dichiarata); Mehádia passa invece agli Asburgo con la data del 27 agosto 1717 (Bánlaky 0019/1715).", "83c63cd6"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Caduta di Özi", "90a67a6c"], "d": ["Özi, fortezza chiave a nord del Mar Nero, cadde in mano russa con un sanguinoso assalto; la popolazione della città fu passata a fil di spada.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Trattato di Bucarest — perdita della Bessarabia", "932da4d6"], "d": ["Con il trattato che pose fine alla guerra russa del 1806-1812, l'est del Prut (Bessarabia) fu lasciato alla Russia. Altri insediamenti perduti nella stessa data: Akkirman, Kili, Hotin, Bender, İsmail. L'atlante considera inoltre passati nello stesso giorno dalla Moldavia (vassalla ottomana) alla Russia Kişinev (Chișinău), Bălți, Kahul (Cahul) e Orhei all'interno della Bessarabia. Anche Soroka (Soroca) passa alla Russia nello stesso giorno.", "b5921c60"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Trattato di Edirne", "b3a8fe4c"], "d": ["Al termine della guerra in cui l'esercito russo entrò a Edirne fu perduto il delta del Danubio; l'autonomia/indipendenza della Grecia fu di fatto accettata. Altri insediamenti perduti nella stessa data: İbrail, Anapa, Ahıska. Benché il trattato restituisse il territorio, non pose subito fine all'occupazione: Valacchia-Moldavia e Silistra rimasero come pegno sotto amministrazione russa fino al pagamento dell'indennità di guerra — è per questo che sulla mappa questi luoghi appaiono occupati anche dopo il 1829.", "d09a34fb"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Firmano di autonomia alla Serbia — knezato ereditario e condizione della guarnigione", "6a5d901d"], "d": ["Il hatt-ı hümâyun emanato in base alla disposizione del trattato di Edirne relativa alla Serbia riconobbe Miloš Obrenović knez ereditario e fece della Serbia un principato autonomo, libero negli affari interni e vassallo degli Ottomani all'esterno. Disposizioni: il knezato sarebbe passato di padre in figlio, il tributo annuo sarebbe stato pagato in somma fissa, l'assemblea serba avrebbe costituito la propria amministrazione interna, la chiesa sarebbe stata autonoma; in cambio nelle fortezze di Belgrado, Smederevo, Šabac, Böğürdelen e Fethülislâm sarebbero rimaste guarnigioni ottomane. Questa struttura doppia durò fino al ritiro delle guarnigioni nel 1867. Sulla mappa la città di Belgrado a questa data viene annessa alla Serbia autonoma; la fortezza di Kalemegdan è mostrata con guarnigione ottomana fino al 1867.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Cessione di Cipro all'amministrazione britannica", "423da3ee"], "d": ["In cambio di un'alleanza contro la minaccia russa l'amministrazione di Cipro fu ceduta all'Inghilterra; giuridicamente rimase territorio ottomano. Altri insediamenti perduti nella stessa data: Lefkoşa, Magosa, Girne, Limasol, Larnaka (Tuzla), Baf, Güzelyurt (Morphou), Akrotiri, Episkopi, Dikelya (Dhekelia); cioè l'intera isola.", "d1abea1c"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Cessione della Tessaglia alla Grecia", "ac614d24"], "d": ["In base alle decisioni del Congresso di Berlino la Tessaglia e la zona di Narda furono cedute alla Grecia. Altri insediamenti perduti nella stessa data: Arta, Yenişehir (Larissa), Tırhala, İzdin (Lamia). Con questa cessione Golos (Volos), Kalabaka e Kardiçe (Tessaglia) passarono alla Grecia.", "9fc28546"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Unione della Rumelia orientale alla Bulgaria", "ee43f137"], "d": ["La provincia autonoma di Rumelia orientale fu unita alla Bulgaria con un colpo di mano; la Sublime Porta accettò il fatto compiuto. Con questa unione l'intera Rumelia orientale (Eski Zağra, Tatarpazarcığı, İslimye, Hasköy, Burgaz, Aydos, Elhova) passò al Principato di Bulgaria.", "7fe3cc42"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Battaglia di Domokos", "9c6f29a5"], "d": ["Nella guerra ottomano-greca del 1897 l'esercito ottenne una vittoria decisiva a Domokos; per la pressione diplomatica i guadagni territoriali rimasero limitati.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Autonomia a Creta", "2e764881"], "d": ["Benché la guerra ottomano-greca fosse terminata con una vittoria ottomana, Inghilterra, Russia, Francia e Italia il 18 dicembre 1897 proclamarono l'autonomia di Creta; l'isola sarebbe stata una provincia neutrale e autonoma sotto sovranità ottomana. Dopo il 6 novembre 1898 a Candia e a Kisamo la bandiera turca non fu più issata; con l'entrata in carica del principe Giorgio, figlio del re di Grecia, come commissario straordinario il 22 dicembre 1898, Creta uscì di fatto dall'amministrazione ottomana (se ne separò ufficialmente nel 1913). Altri insediamenti perduti nella stessa data: Kandiye (Creta), Hanya.", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Indipendenza della Bulgaria e annessione della Bosnia", "393feaa4"], "d": ["Nel caos della Monarchia Costituzionale la Bulgaria proclamò l'indipendenza e l'Austria-Ungheria annesse la Bosnia-Erzegovina. Con questa proclamazione tutti i territori del Principato di Bulgaria (Varna, Şumnu, Rusçuk, Burgaz, İslimye ecc.) divennero il Regno di Bulgaria indipendente.", "b7f0bb26"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Riconquista di Edirne", "536e5599"], "d": ["Nella Seconda guerra balcanica l'esercito attraversò la Maritza e riprese Edirne senza combattere. Altri luoghi annessi nella stessa data: Kırklareli, Tekirdağ.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Vittoria di Kut al-Amara", "98b972bc"], "d": ["Il comandante della divisione britannica assediata a Kut si arrese con 13 mila soldati — una delle più grandi vittorie ottomane della Prima guerra mondiale.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Perdita di Baghdad", "2c18a816"], "d": ["La Baghdad ottomana, dopo 383 anni, passò all'esercito britannico. Altri insediamenti perduti nella stessa data: Kerbelâ.", "4add66da"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Perdita di Gerusalemme", "94067617"], "d": ["La Gerusalemme ottomana, dopo 401 anni, fu consegnata senza poter essere difesa.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Perdita di Damasco", "ed177b68"], "d": ["Con il crollo del fronte della Palestina Damasco fu evacuata; il governo ottomano di quattro secoli in Siria ebbe termine. Altri insediamenti perduti nella stessa data: Hama, Humus.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Resa di Medina", "76b505f6"], "d": ["Settantadue giorni dopo l'armistizio la resistenza di Fahreddin Paşa, la «Tigre del Deserto», terminò per volontà del sultano; l'ultima unità ottomana nel Hegiaz depose le armi.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Occupazione di Smirne", "e32e5e77"], "d": ["L'esercito greco sbarcò a Smirne; la resistenza iniziata con il primo colpo di fucile accese la miccia della Guerra di Liberazione Nazionale. Aydın fu invece occupata il 27 maggio 1919 (voce separata).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Occupazione ufficiale di Costantinopoli", "a8e98ada"], "d": ["Le forze dell'Intesa occuparono ufficialmente Costantinopoli e il Meclis-i Meb'ûsan fu sciolto; i deputati si diressero ad Ankara.", "09ed005b"]},
"OLAYLAR_EK:1921-10-13:0":{"b": ["Trattato di Kars", "bb32d4e0"], "d": ["Tra la Grande Assemblea Nazionale e le repubbliche caucasiche fu tracciato il confine orientale nella sua forma attuale.", "fe736259"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["Presa dell'emirato di Ha'il da parte delle forze saudita-wahhabite — il governo era nella famiglia Ibn Ali della tribù Abde", "2d29ceb9"], "d": ["Quando le forze del Primo Stato saudita presero l'emirato di Ha'il, l'amministrazione della città era nella famiglia Ibn Ali della tribù Abde dei Shammar. Questa famiglia governò Ha'il fino alla presa dell'emirato da parte di Abdallah b. Rashid nel 1835; la dinastia dei Rashidi fu fondata solo in quella data. Nell'atlante Ha'il fino a oggi appariva priva di proprietario fino al 1836, mentre la fonte dà già nel 1820 il nome dell'emiro della città.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["Passaggio delle isole del Quarnaro al Regno d'Italia napoleonico e delle Bocche di Cattaro all'amministrazione russa", "c5e411c8"], "d": ["Dopo il Trattato di Presburgo le isole del Quarnaro — a differenza della Dalmazia — furono legate non direttamente alla Francia ma al Regno d'Italia di Napoleone; entrarono nelle Province Illiriche solo nel 1809. Nelle Bocche di Cattaro invece l'amministrazione austriaca terminò e tra il 1806 e il 1807 fu stabilita un'amministrazione russa; le Bocche passarono alla Francia solo nel 1807. Queste due distinzioni non si possono rendere con un'unica finestra 'Francia' dell'atlante.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["Passaggio della Dalmazia all'amministrazione francese — applicazione del Trattato di Presburgo (Pojun)", "00bfe4f6"], "d": ["Il Trattato di Presburgo (Pojun, Bratislava) del 26 dicembre 1805 costrinse l'Austria a rinunciare a Istria, Dalmazia e a tutte le isole dell'Adriatico. La Francia rilevò di fatto l'amministrazione nel febbraio 1806; Zara rimase sede del provveditore generale e dal 1806 al 1810 questo incarico fu svolto dal veneziano Vincenzo Dandolo. La Dalmazia dopo il Trattato di Schönbrunn del 1809 fu aggregata alle Province Illiriche. La prima amministrazione austriaca, in corso dal 1797, ebbe così fine — nell'atlante questo periodo fino a oggi appariva come ininterrottamente austriaco.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["Ripresa da parte dell'Austria delle Province Illiriche e della Dalmazia — fine dell'amministrazione napoleonica", "1b2ac942"], "d": ["Alla fine del 1813 le truppe asburgiche ripresero la regione a sud della Sava e fu ristabilita l'antica organizzazione di confine; l'esercito austriaco entrò in Istria nell'ottobre 1813. Karlovac da quella data divenne parte del Regno d'Illiria austriaco. Anche il periodo dell'amministrazione francese in Dalmazia si chiuse nel 1813. L'appartenenza della regione all'Austria fu confermata ufficialmente dalla Pace di Parigi del 1814 e dalle decisioni del Congresso di Vienna del 1815. Con questa operazione Villach, Tarvisio, Gorizia, Gradisca e Pola (Province Illiriche) tornarono all'Austria alla fine del 1813.", "bf1e49a8"]}
});
